const codeIndex = new Map();
const nameIndex = [];
let stockDbReady = null;
let stockDbSourceNote = "內建備援清單";

const STOCK_LIST_ENDPOINTS = [
  {
    label: "TWSE OpenAPI 上市股票/ETF",
    ex: "t",
    url: "https://openapi.twse.com.tw/v1/exchangeReport/STOCK_DAY_ALL",
    codeKeys: ["Code"],
    nameKeys: ["Name"],
  },
  {
    label: "TPEx OpenAPI 上櫃股票/ETF",
    ex: "o",
    url: "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_quotes",
    codeKeys: ["SecuritiesCompanyCode"],
    nameKeys: ["CompanyName"],
  },
];

function isWarrantEntry(code, name) {
  const cleanCode = String(code || "").trim().toUpperCase();
  const cleanName = String(name || "").trim();
  return /權證|認購|認售|牛證|熊證|展延型牛熊證/.test(cleanName)
    || (/^7\d{5}$/.test(cleanCode) && /購|售|牛|熊/.test(cleanName));
}

function addStockEntry(code, name, ex, source = "") {
  const cleanCode = String(code || "").trim().toUpperCase();
  const cleanName = String(name || "").trim();
  if (!cleanCode || !cleanName || !/^\d{4,6}[A-Z]?$/.test(cleanCode)) return false;
  if (isWarrantEntry(cleanCode, cleanName)) return false;
  const entry = { code: cleanCode, name: cleanName, ex, source };
  codeIndex.set(cleanCode, entry);
  return true;
}

function rebuildNameIndex() {
  nameIndex.length = 0;
  [...codeIndex.values()]
    .sort((a, b) => a.code.localeCompare(b.code))
    .forEach((entry) => nameIndex.push({ ...entry, kw: normalizeName(entry.name) }));
}

function pickText(row, keys) {
  for (const key of keys) {
    const value = row?.[key];
    if (value !== null && value !== undefined && String(value).trim()) return String(value).trim();
  }
  return "";
}

for (const [code, name, ex] of STOCK_DB) {
  addStockEntry(code, name, ex, "內建備援清單");
}
rebuildNameIndex();

async function loadStockDatabase() {
  if (stockDbReady) return stockDbReady;
  stockDbReady = (async () => {
    let loaded = 0;
    for (const endpoint of STOCK_LIST_ENDPOINTS) {
      try {
        const rows = await fetchJSON(endpoint.url, endpoint.label);
        if (!Array.isArray(rows)) continue;
        for (const row of rows) {
          const code = pickText(row, endpoint.codeKeys);
          const name = pickText(row, endpoint.nameKeys);
          if (addStockEntry(code, name, endpoint.ex, endpoint.label)) loaded += 1;
        }
      } catch (_) {}
    }
    if (loaded > 0) {
      rebuildNameIndex();
      stockDbSourceNote = `TWSE/TPEx OpenAPI 已載入 ${nameIndex.length.toLocaleString("zh-TW")} 檔上市櫃股票與 ETF`;
    }
    return nameIndex.length;
  })();
  return stockDbReady;
}

function getStockDbStatus() {
  return stockDbSourceNote;
}

