const lastTradeCache = new Map();
const portfolioUnitPriceCache = new Map();
const LAST_TRADE_STORAGE_PREFIX = "tq:last-trade:";
try {
  for (let i = localStorage.length - 1; i >= 0; i -= 1) {
    const key = localStorage.key(i);
    if (key?.startsWith(LAST_TRADE_STORAGE_PREFIX) && !(Number(localStorage.getItem(key)) > 0)) {
      localStorage.removeItem(key);
    }
  }
} catch (_) {}

function lastTradeKey(code) {
  return `${LAST_TRADE_STORAGE_PREFIX}${String(code || "").trim()}`;
}

function readCachedLastTrade(code) {
  const key = String(code || "").trim();
  if (!key) return null;
  if (lastTradeCache.has(key)) {
    const cached = Number(lastTradeCache.get(key));
    if (cached > 0) return cached;
    lastTradeCache.delete(key);
  }
  try {
    const stored = localStorage.getItem(lastTradeKey(key));
    const value = Number(stored);
    if (value > 0) {
      lastTradeCache.set(key, value);
      return value;
    }
    localStorage.removeItem(lastTradeKey(key));
  } catch (_) {}
  return null;
}

function writeCachedLastTrade(code, value) {
  const key = String(code || "").trim();
  const price = Number(value);
  if (!key || !(price > 0)) return;
  lastTradeCache.set(key, price);
  try {
    localStorage.setItem(lastTradeKey(key), String(price));
  } catch (_) {}
}

function isValidTradeUpdate(nextPrice, previousPrice) {
  const next = Number(nextPrice);
  if (!(next > 0)) return false;
  const previous = Number(previousPrice);
  if (!(previous > 0)) return true;
  return Math.abs(next - previous) / previous <= 0.1;
}

function normalizeAppPath(pathname) {
  const raw = String(pathname || "/").trim() || "/";
  if (raw === "/") return raw;
  return raw.replace(/\/+$/, "") || "/";
}

function getModePath(mode) {
  return MODE_ROUTE_MAP[mode] || MODE_ROUTE_MAP.home;
}

function resolveModeFromPath(pathname = location.pathname) {
  const path = normalizeAppPath(pathname);
  if (/^\/podcast\/\d+$/.test(path)) return "podcast";
  return ROUTE_MODE_MAP.get(path) || "home";
}

function syncBrowserPath(mode, replace = false) {
  const targetPath = getModePath(mode);
  const currentPath = normalizeAppPath(location.pathname);
  if (currentPath === targetPath) return false;
  const url = new URL(location.href);
  url.pathname = targetPath;
  url.search = "";
  url.hash = "";
  history[replace ? "replaceState" : "pushState"]({ mode }, "", url);
  return true;
}

function syncDocumentTitle(mode) {
  const section = MODE_TITLE_MAP[mode] || MODE_TITLE_MAP.home;
  document.title = `${section} | TWETQ Podcast 投資脈絡`;
}

function setSiteNavOpen(open) {
  const wasOpen = siteNavOpen;
  siteNavOpen = Boolean(open);
  document.body.classList.toggle("site-nav-open", siteNavOpen);
  navToggleButton?.setAttribute("aria-expanded", siteNavOpen ? "true" : "false");
  siteNavDrawer?.setAttribute("aria-hidden", siteNavOpen ? "false" : "true");
  if (siteNavOverlay) siteNavOverlay.hidden = !siteNavOpen;
  [brandHomeLink, document.querySelector("#desktopNavBar"), searchPanel, stepsSlot, liveSlot, errorSlot, resultSlot, document.querySelector(".footer-note"), backToTopButton]
    .filter(Boolean)
    .forEach((element) => { element.inert = siteNavOpen; });
  if (siteNavOpen) navCloseButton?.focus();
  else if (wasOpen) navToggleButton?.focus();
}

function closeSiteNav() {
  setSiteNavOpen(false);
}

function trapSiteNavFocus(event) {
  if (!siteNavOpen || event.key !== "Tab" || !siteNavDrawer) return;
  const focusable = [...siteNavDrawer.querySelectorAll('a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])')]
    .filter((element) => !element.hidden && element.getAttribute("aria-hidden") !== "true");
  if (!focusable.length) return;
  const first = focusable[0];
  const last = focusable.at(-1);
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
  }
}

closeSiteNav();

function quoteDisplayPrice(quote) {
  const trade = Number(quote?.lastTrade);
  if (trade > 0) return trade;
  const price = Number(quote?.price);
  return price > 0 ? price : null;
}

function guardTradeQuoteUpdate(quote, previousQuote = liveData) {
  const previousPrice = quoteDisplayPrice(previousQuote);
  const trade = Number(quote?.lastTrade);
  const nextTrade = trade > 0 ? trade : (previousPrice > 0 ? null : quoteDisplayPrice(quote));
  if (!isValidTradeUpdate(nextTrade, previousPrice)) return null;
  return quote;
}

function applyLastTradeCache(quote) {
  if (!quote?.code) return quote;
  const trade = Number(quote.lastTrade);
  if (trade > 0) {
    writeCachedLastTrade(quote.code, trade);
    quote.price = trade;
    return quote;
  }
  const cached = readCachedLastTrade(quote.code);
  if (Number(cached) > 0) {
    quote.lastTrade = Number(cached);
    quote.price = Number(cached);
  }
  return quote;
}
