function industryName(code) {
  const key = String(code || "").trim().padStart(2, "0");
  return INDUSTRY_NAMES[key] || (key ? `產業代碼 ${key}` : "ETF / 其他");
}

async function loadMarketUniverse() {
  if (marketUniverseReady) return marketUniverseReady;
  marketUniverseReady = (async () => {
    await loadStockDatabase();
    const records = [];
    const seen = new Set();
    for (const endpoint of MARKET_BASIC_ENDPOINTS) {
      try {
        const rows = await fetchJSON(endpoint.url, endpoint.label);
        if (!Array.isArray(rows)) continue;
        for (const row of rows) {
          const code = pickText(row, [endpoint.codeKey]).toUpperCase();
          const name = pickText(row, [endpoint.nameKey, endpoint.fullNameKey]);
          if (!code || !name || isWarrantEntry(code, name)) continue;
          const industryCode = String(row?.[endpoint.industryKey] || "").trim().padStart(2, "0");
          const key = `${endpoint.market}:${code}`;
          seen.add(key);
          records.push({
            code,
            name,
            fullName: pickText(row, [endpoint.fullNameKey]) || name,
            ex: endpoint.market === "listed" ? "t" : "o",
            market: endpoint.market,
            marketLabel: endpoint.market === "listed" ? "上市" : "上櫃",
            industryCode,
            industryName: industryName(industryCode),
            issuedShares: parseNum(row?.[endpoint.issueSharesKey]),
            source: endpoint.label,
          });
        }
      } catch (_) {}
    }
    for (const item of nameIndex) {
      const market = item.ex === "o" ? "otc" : "listed";
      const key = `${market}:${item.code}`;
      if (seen.has(key)) continue;
      records.push({
        code: item.code,
        name: item.name,
        fullName: item.name,
        ex: item.ex,
        market,
        marketLabel: market === "listed" ? "上市" : "上櫃",
        industryCode: "",
        industryName: item.code.startsWith("00") ? "ETF" : "ETF / 其他",
        source: item.source || "股票搜尋清單",
      });
    }
    return records.sort((a, b) => a.market.localeCompare(b.market) || a.industryName.localeCompare(b.industryName, "zh-Hant") || a.code.localeCompare(b.code));
  })();
  return marketUniverseReady;
}

