function normalizeChartPoint(date, value, extra = {}) {
  const n = parseNum(value);
  if (!Number.isFinite(n)) return null;
  return { date: formatTWSEDate(date), value: n, ...extra };
}

function normalizeMarketQuote(row, market) {
  if (market === "otc") {
    const code = String(row?.SecuritiesCompanyCode || "").trim().toUpperCase();
    const close = parseNum(row?.Close);
    const change = parseNum(row?.Change);
    const prev = Number.isFinite(close) && Number.isFinite(change) ? close - change : null;
    return {
      code,
      name: String(row?.CompanyName || "").trim(),
      date: formatTWSEDate(row?.Date),
      close,
      change,
      changePct: calcPercentChange(close, change),
      open: parseNum(row?.Open),
      high: parseNum(row?.High),
      low: parseNum(row?.Low),
      prevClose: prev,
      volume: parseNum(row?.TradingShares),
      value: parseNum(row?.TransactionAmount),
      transactions: parseNum(row?.TransactionNumber),
      source: "TPEx OpenAPI 上櫃收盤行情",
    };
  }
  const code = String(row?.Code || "").trim().toUpperCase();
  const close = parseNum(row?.ClosingPrice);
  const change = parseNum(row?.Change);
  const prev = Number.isFinite(close) && Number.isFinite(change) ? close - change : null;
  return {
    code,
    name: String(row?.Name || "").trim(),
    date: formatTWSEDate(row?.Date),
    close,
    change,
    changePct: calcPercentChange(close, change),
    open: parseNum(row?.OpeningPrice),
    high: parseNum(row?.HighestPrice),
    low: parseNum(row?.LowestPrice),
    prevClose: prev,
    volume: parseNum(row?.TradeVolume),
    value: parseNum(row?.TradeValue),
    transactions: parseNum(row?.Transaction),
    source: "TWSE OpenAPI 上市日行情",
  };
}

function normalizeMISMarketQuote(item, stock, fallback = null) {
  const last = parseNum(item?.z);
  const prevClose = parseNum(item?.y) ?? parseNum(fallback?.prevClose);
  const close = Number.isFinite(last) ? last : prevClose;
  const change = Number.isFinite(close) && Number.isFinite(prevClose) ? close - prevClose : parseNum(fallback?.change);
  const open = parseNum(item?.o) ?? parseNum(fallback?.open);
  const high = parseNum(item?.h) ?? parseNum(fallback?.high);
  const low = parseNum(item?.l) ?? parseNum(fallback?.low);
  return {
    ...(fallback || {}),
    code: item?.c || stock.code,
    name: item?.n || fallback?.name || stock.name,
    date: formatTWSEDate(item?.d) || fallback?.date || "",
    time: item?.t || fallback?.time || "",
    close,
    change,
    changePct: calcPercentChange(close, change),
    open,
    high,
    low,
    prevClose,
    volume: parseNum(item?.v) ?? parseNum(fallback?.volume),
    transactions: parseNum(fallback?.transactions),
    value: parseNum(fallback?.value),
    source: Number.isFinite(last) ? "TWSE MIS 批次即時報價" : "TWSE MIS 昨收 / OpenAPI 日行情",
    priceType: Number.isFinite(last) ? "MIS 盤中成交" : "MIS 昨收",
  };
}

async function fetchMarketMISQuotes(items) {
  const map = new Map();
  const symbols = items
    .filter((stock) => stock?.code && !isWarrantEntry(stock.code, stock.name))
    .map((stock) => ({
      stock,
      channel: `${stock.market === "otc" ? "otc" : "tse"}_${stock.code}.tw`,
    }));

  for (let i = 0; i < symbols.length; i += MARKET_MIS_CHUNK_SIZE) {
    const chunk = symbols.slice(i, i + MARKET_MIS_CHUNK_SIZE);
    const lookup = new Map(chunk.map(({ stock }) => [stock.code, stock]));
    try {
      const data = await fetchRealtimeMISData(chunk.map(({ channel }) => channel), "TWSE MIS 批次即時報價");
      const rows = Array.isArray(data?.msgArray) ? data.msgArray : [];
      for (const item of rows) {
        const code = String(item?.c || "").trim().toUpperCase();
        const stock = lookup.get(code);
        if (!stock) continue;
        map.set(`${stock.market}:${stock.code}`, normalizeMISMarketQuote(item, stock));
      }
    } catch (_) {}
  }

  return map;
}

function mapMarketSnapshotQuotes(payload) {
  const map = new Map();
  const rows = Array.isArray(payload?.quotes) ? payload.quotes : [];
  for (const row of rows) {
    const market = row.market === "otc" ? "otc" : "listed";
    const code = String(row.code || "").trim().toUpperCase();
    if (!code) continue;
    map.set(`${market}:${code}`, {
      ...row,
      market,
      code,
      close: parseNum(row.close),
      change: parseNum(row.change),
      changePct: parseNum(row.changePct),
      open: parseNum(row.open),
      high: parseNum(row.high),
      low: parseNum(row.low),
      prevClose: parseNum(row.prevClose),
      volume: parseNum(row.volume),
      value: parseNum(row.value),
      transactions: parseNum(row.transactions),
      source: row.source || "TWSE/TPEx OpenAPI 盤後市場快照",
      priceType: row.priceType || "OpenAPI 收盤",
    });
  }
  return map;
}

async function loadMarketSnapshotQuotes() {
  const payload = await fetchJSON(MARKET_SNAPSHOT_ENDPOINT, "市場盤後快照", { timeoutMs: 60000 });
  return mapMarketSnapshotQuotes(payload);
}

function mergeQuoteMaps(baseQuotes = new Map(), liveQuotes = new Map()) {
  const merged = new Map(baseQuotes);
  for (const [key, value] of liveQuotes || []) {
    if (value && Number.isFinite(parseNum(value.close))) merged.set(key, value);
  }
  return merged;
}

async function loadMarketQuotesForItems(items = [], baseQuotes = null) {
  const snapshotQuotes = baseQuotes || await loadMarketSnapshotQuotes();
  if (!Array.isArray(items) || !items.length) return snapshotQuotes;
  const liveQuotes = await fetchMarketMISQuotes(items).catch(() => new Map());
  return mergeQuoteMaps(snapshotQuotes, liveQuotes);
}

async function loadMarketClosingQuotes() {
  if (marketClosingQuotesReady) return marketClosingQuotesReady;
  marketClosingQuotesReady = loadMarketSnapshotQuotes();
  return marketClosingQuotesReady;
}

async function loadMarketQuotes() {
  if (marketQuotesReady) return marketQuotesReady;
  marketQuotesReady = loadMarketSnapshotQuotes();
  return marketQuotesReady;
}

function updateHistoryMetrics(map, key, patch) {
  const current = map.get(key) || {};
  map.set(key, { ...current, ...patch });
}

async function loadScreenHistory() {
  if (screenHistoryReady) return screenHistoryReady;
  screenHistoryReady = (async () => {
    const map = new Map();
    const [listedMonthlyResult, otcDailyResult] = await Promise.allSettled([
      fetchJSON(SCREEN_HISTORY_ENDPOINTS.listedMonthly, "TWSE OpenAPI 上市月成交資訊"),
      fetchJSON(SCREEN_HISTORY_ENDPOINTS.otcDaily, "TPEx OpenAPI 上櫃歷史日收盤行情"),
    ]);

    if (listedMonthlyResult.status === "fulfilled" && Array.isArray(listedMonthlyResult.value)) {
      const grouped = new Map();
      for (const row of listedMonthlyResult.value) {
        const code = String(row?.Code || "").trim().toUpperCase();
        const month = String(row?.Month || "").trim();
        if (!code || !month) continue;
        if (!grouped.has(code)) grouped.set(code, []);
        grouped.get(code).push(row);
      }
      for (const [code, rows] of grouped) {
        const latestRows = rows
          .sort((a, b) => String(b?.Month || "").localeCompare(String(a?.Month || "")))
          .slice(0, 2);
        let recentHigh = null;
        let supportLow = null;
        let totalVolume = 0;
        let totalValue = 0;
        let volumeMonths = 0;
        let valueMonths = 0;
        for (const row of latestRows) {
          const high = parseNum(row?.HighestPrice);
          const low = parseNum(row?.LowestPrice);
          const volume = parseNum(row?.TradeVolumeB);
          const value = parseNum(row?.TradeValueA);
          if (Number.isFinite(high)) recentHigh = Number.isFinite(recentHigh) ? Math.max(recentHigh, high) : high;
          if (Number.isFinite(low)) supportLow = Number.isFinite(supportLow) ? Math.min(supportLow, low) : low;
          if (Number.isFinite(volume)) {
            totalVolume += volume;
            volumeMonths += 1;
          }
          if (Number.isFinite(value)) {
            totalValue += value;
            valueMonths += 1;
          }
        }
        updateHistoryMetrics(map, `listed:${code}`, {
          recentHigh,
          supportLow,
          avgVolume: volumeMonths ? totalVolume / (volumeMonths * 20) : null,
          avgValue: valueMonths ? totalValue / (valueMonths * 20) : null,
          historySource: "TWSE FMSRFK_ALL 近2月月成交資訊",
          historyWindow: latestRows.map((row) => String(row?.Month || "")).filter(Boolean).join(", "),
        });
      }
    }

    if (otcDailyResult.status === "fulfilled" && Array.isArray(otcDailyResult.value)) {
      const grouped = new Map();
      for (const row of otcDailyResult.value) {
        const code = String(row?.SecuritiesCompanyCode || "").trim().toUpperCase();
        if (!code) continue;
        if (!grouped.has(code)) grouped.set(code, []);
        grouped.get(code).push(row);
      }
      for (const [code, rows] of grouped) {
        const latestRows = rows
          .sort((a, b) => String(b?.Date || "").localeCompare(String(a?.Date || "")))
          .slice(0, 40);
        let recentHigh = null;
        let supportLow = null;
        let totalVolume = 0;
        let totalValue = 0;
        let volumeDays = 0;
        let valueDays = 0;
        for (const row of latestRows) {
          const high = parseNum(row?.High);
          const low = parseNum(row?.Low);
          const volume = parseNum(row?.TradingShares);
          const value = parseNum(row?.TransactionAmount);
          if (Number.isFinite(high)) recentHigh = Number.isFinite(recentHigh) ? Math.max(recentHigh, high) : high;
          if (Number.isFinite(low)) supportLow = Number.isFinite(supportLow) ? Math.min(supportLow, low) : low;
          if (Number.isFinite(volume)) {
            totalVolume += volume;
            volumeDays += 1;
          }
          if (Number.isFinite(value)) {
            totalValue += value;
            valueDays += 1;
          }
        }
        updateHistoryMetrics(map, `otc:${code}`, {
          recentHigh,
          supportLow,
          avgVolume: volumeDays ? totalVolume / volumeDays : null,
          avgValue: valueDays ? totalValue / valueDays : null,
          historySource: "TPEx tpex_mainboard_daily_close_quotes 近可用日行情",
          historyWindow: latestRows.length ? `${formatTWSEDate(latestRows.at(-1)?.Date)} ~ ${formatTWSEDate(latestRows[0]?.Date)}` : "",
        });
      }
    }

    return map;
  })();
  return screenHistoryReady;
}

function calcPercentChange(value, change) {
  const v = parseNum(value);
  const c = parseNum(change);
  if (!Number.isFinite(v) || !Number.isFinite(c) || v - c === 0) return null;
  return (c / (v - c)) * 100;
}

function parsePercentText(value) {
  const n = parseNum(String(value || "").replace("%", ""));
  return Number.isFinite(n) ? n : null;
}

function decodeHtmlText(value) {
  return String(value || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, "\"")
    .replace(/&#39;/gi, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)));
}

function stripHtml(value) {
  return decodeHtmlText(String(value || "").replace(/<[^>]*>/g, " "))
    .replace(/\s+/g, " ")
    .trim();
}

function parseTaifexSignedNumber(value) {
  const cleaned = String(value || "").replace(/[\u25b2\u25bc]/g, "").replace("%", "").trim();
  return parseNum(cleaned);
}

function formatCompactTime(value) {
  const digits = String(value || "").replace(/\D/g, "").padStart(6, "0").slice(-6);
  if (!digits || digits === "000000") return "";
  return `${digits.slice(0, 2)}:${digits.slice(2, 4)}:${digits.slice(4, 6)}`;
}

function getFuturesMonthKey(value) {
  const text = String(value || "").trim();
  const match = text.match(/^(\d{6})$/);
  return match ? match[1] : "";
}

function getFuturesMonthlyExpiryDate(monthKey) {
  if (!/^\d{6}$/.test(monthKey)) return null;
  const year = Number(monthKey.slice(0, 4));
  const monthIndex = Number(monthKey.slice(4, 6)) - 1;
  const firstDay = new Date(year, monthIndex, 1);
  const firstWednesdayOffset = (3 - firstDay.getDay() + 7) % 7;
  return new Date(year, monthIndex, 1 + firstWednesdayOffset + 14);
}

function isSameLocalDate(a, b) {
  return a instanceof Date
    && b instanceof Date
    && a.getFullYear() === b.getFullYear()
    && a.getMonth() === b.getMonth()
    && a.getDate() === b.getDate();
}

function isFuturesExpiryToday(monthKey) {
  const expiry = getFuturesMonthlyExpiryDate(monthKey);
  return expiry ? isSameLocalDate(expiry, new Date()) : false;
}

function pickVisibleFuturesFrontMonth(months) {
  const sorted = [...new Set((months || []).map(getFuturesMonthKey).filter(Boolean))].sort();
  if (!sorted.length) return "";
  const front = sorted[0];
  return isFuturesExpiryToday(front) && sorted[1] ? sorted[1] : front;
}

function rollExpiringFrontFuturesRows(rows) {
  const groups = new Map();
  for (const row of rows || []) {
    const month = getFuturesMonthKey(row?.month);
    if (!month) continue;
    const key = `${row?.contract || ""}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(month);
  }
  const skipByGroup = new Map();
  for (const [key, months] of groups.entries()) {
    const sorted = [...new Set(months)].sort();
    if (sorted.length > 1 && isFuturesExpiryToday(sorted[0])) skipByGroup.set(key, sorted[0]);
  }
  return (rows || []).filter((row) => {
    const key = `${row?.contract || ""}`;
    const skipMonth = skipByGroup.get(key);
    return !skipMonth || getFuturesMonthKey(row?.month) !== skipMonth;
  });
}

function parseTaifexFuturesWeb(html) {
  const text = String(html || "");
  if (!text) return null;
  const rowMatches = text.match(/<tr\b[\s\S]*?<\/tr>/gi) || [];
  const txRows = rowMatches
    .map((row) => {
      const cells = [...row.matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map((m) => stripHtml(m[1]));
      return { row, cells };
    })
    .filter(({ cells }) => cells[0] === "TX" && /^\d{6}$/.test(cells[1] || ""));
  if (!txRows.length) return null;
  const currentMonth = pickVisibleFuturesFrontMonth(txRows.map(({ cells }) => cells[1]));
  const target = txRows.find(({ cells }) => cells[1] === currentMonth) || txRows[0];
  const cells = target.cells;
  const last = parseTaifexSignedNumber(cells[5]);
  const change = parseTaifexSignedNumber(cells[6]);
  const percent = parseTaifexSignedNumber(cells[7]);
  if (!Number.isFinite(last)) return null;
  return {
    contract: cells[0],
    month: cells[1],
    last,
    change: Number.isFinite(change) ? change : null,
    percent: Number.isFinite(percent) ? percent : null,
    source: `TAIFEX ${cells[0]} ${cells[1]} 官方盤後交易時段`,
  };
}

function normalizeTaifexOfficialFuturesRow(cells, session = "一般") {
  const contract = String(cells?.[0] || "").trim();
  const month = String(cells?.[1] || "").trim();
  const last = parseTaifexSignedNumber(cells?.[5]);
  if (!contract || !/^\d{6}$/.test(month) || !Number.isFinite(last)) return null;
  const general = cells.length >= 17;
  return {
    date: "",
    contract,
    label: futuresLabel(contract),
    month,
    session,
    open: parseTaifexSignedNumber(cells?.[2]),
    high: parseTaifexSignedNumber(cells?.[3]),
    low: parseTaifexSignedNumber(cells?.[4]),
    last,
    change: parseTaifexSignedNumber(cells?.[6]),
    percent: parseTaifexSignedNumber(cells?.[7]),
    volume: parseTaifexSignedNumber(cells?.[8]),
    settlement: general ? parseTaifexSignedNumber(cells?.[11]) : null,
    openInterest: general ? parseTaifexSignedNumber(cells?.[12]) : null,
    bestBid: parseTaifexSignedNumber(cells?.[general ? 13 : 11]),
    bestAsk: parseTaifexSignedNumber(cells?.[general ? 14 : 12]),
    source: `TAIFEX 官方${session === "盤後" ? "盤後" : "一般"}收盤`,
  };
}

function parseTaifexOfficialFuturesRows(html, session = "一般") {
  const text = String(html || "");
  if (!text) return [];
  const rowMatches = text.match(/<tr\b[\s\S]*?<\/tr>/gi) || [];
  return rowMatches
    .map((row) => [...row.matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map((m) => stripHtml(m[1])))
    .map((cells) => normalizeTaifexOfficialFuturesRow(cells, session))
    .filter(Boolean);
}

async function postFormText(url, body, label, options = {}) {
  const response = await fetchWithTimeout(proxyURL(url), {
    method: "POST",
    cache: "no-store",
    headers: { "content-type": "application/x-www-form-urlencoded; charset=UTF-8" },
    body,
  }, options.timeoutMs);
  const text = await response.text();
  if (!response.ok) {
    let detail = text.slice(0, 220);
    try {
      const payload = JSON.parse(text);
      detail = payload.message || payload.error || detail;
    } catch (_) {}
    throw new Error(`${label} HTTP ${response.status}${detail ? `：${detail}` : ""}`);
  }
  return text;
}

const TAIFEX_OFFICIAL_GENERAL_CONTRACTS = [
  "BRF", "BTF", "E4F", "F1F", "G2F", "GDF", "GTF", "M1F", "MTX", "RHF",
  "RTF", "SHF", "SOF", "SPF", "SXF", "TE", "TF", "TGF", "TJF", "TMF",
  "TX", "UDF", "UNF", "XAF", "XBF", "XEF", "XIF", "XJF", "ZEF", "ZFF",
];
const TAIFEX_OFFICIAL_AFTER_HOUR_CONTRACTS = ["TX"];

function pickFrontRowPerContract(rows) {
  const groups = new Map();
  (rows || []).forEach((row) => {
    if (!row?.contract) return;
    if (!groups.has(row.contract)) groups.set(row.contract, []);
    groups.get(row.contract).push(row);
  });
  return [...groups.values()].map((list) => {
    const regular = list.filter((row) => row.session === "一般");
    const candidates = regular.length ? regular : list;
    const months = candidates.map((row) => row.month).filter(Boolean);
    const frontMonth = pickVisibleFuturesFrontMonth(months) || months[0];
    return candidates.find((row) => row.month === frontMonth) || candidates[0] || null;
  }).filter(Boolean);
}

async function loadTaifexOfficialFrontRows(contracts, marketCode, session) {
  const tasks = contracts.map(async (contract) => {
    const body = new URLSearchParams({
      queryType: "2",
      marketCode: String(marketCode),
      commodity_id: contract,
      commodity_id2: "",
      dateaddcnt: "",
      queryDate: "",
    }).toString();
    const html = await postFormText(MARKET_INDEX_ENDPOINTS.futuresWeb, body, `TAIFEX 官方期貨收盤 ${contract}`, { timeoutMs: 12000 });
    const rows = parseTaifexOfficialFuturesRows(html, session).filter((row) => row.contract === contract);
    return pickFrontRowPerContract(rows)[0] || null;
  });
  const results = await Promise.allSettled(tasks);
  return results
    .map((result) => result.status === "fulfilled" ? result.value : null)
    .filter(Boolean);
}

async function loadTaifexOfficialGeneralRows() {
  if (taifexOfficialGeneralReady) return taifexOfficialGeneralReady;
  taifexOfficialGeneralReady = loadTaifexOfficialFrontRows(TAIFEX_OFFICIAL_GENERAL_CONTRACTS, 0, "一般");
  return taifexOfficialGeneralReady;
}

async function loadTaifexOfficialAfterHourRows() {
  if (taifexOfficialAfterHourReady) return taifexOfficialAfterHourReady;
  taifexOfficialAfterHourReady = loadTaifexOfficialFrontRows(TAIFEX_OFFICIAL_AFTER_HOUR_CONTRACTS, 1, "盤後");
  return taifexOfficialAfterHourReady;
}

function normalizeIndexSummary({ key, title, value, change, percent, source, accent, date = "", time = "", contractMonth = "", session = "", points = [] }) {
  const v = parseNum(value);
  const c = parseNum(change);
  const metadata = { date, time, contractMonth, session, points };
  if (!Number.isFinite(v)) return { key, title, value: null, change: null, percent: null, source, accent, ...metadata };
  return {
    key,
    title,
    value: v,
    change: Number.isFinite(c) ? c : null,
    percent: Number.isFinite(percent) ? percent : calcPercentChange(v, c),
    source,
    accent,
    ...metadata,
  };
}

