function futuresLabel(contract) {
  const key = String(contract || "").trim();
  return FUTURES_LABELS[key] || key || "期貨";
}

function futuresDisplayLabel(row) {
  const label = String(row?.label || futuresLabel(row?.contract)).trim();
  return row?.session === "盤後" && label && !label.endsWith("全") ? `${label}全` : label;
}

async function loadFuturesNameMap() {
  const nameMap = new Map(Object.entries(FUTURES_LABELS));
  const [stockResult, etfResult] = await Promise.allSettled([
    fetchJSON(MARKET_INDEX_ENDPOINTS.singleStockFutures, "TAIFEX 股票期貨保證金"),
    fetchJSON(MARKET_INDEX_ENDPOINTS.singleStockEtfFutures, "TAIFEX ETF 期貨保證金"),
  ]);
  for (const result of [stockResult, etfResult]) {
    const rows = result.status === "fulfilled" && Array.isArray(result.value) ? result.value : [];
    rows.forEach((row) => {
      const contract = String(row?.Contract || "").trim();
      const name = String(row?.ContractName || "").trim();
      if (contract && name) nameMap.set(contract, name);
    });
  }
  return nameMap;
}

function normalizeFuturesRow(row) {
  const contract = String(row?.Contract || "").trim();
  const month = String(row?.["ContractMonth(Week)"] || "").trim();
  return {
    date: formatTWSEDate(row?.Date),
    contract,
    label: futuresLabel(contract),
    month,
    session: String(row?.TradingSession || "").trim(),
    open: parseNum(row?.Open),
    high: parseNum(row?.High),
    low: parseNum(row?.Low),
    last: parseNum(row?.Last),
    change: parseNum(row?.Change),
    percent: parsePercentText(row?.["%"]),
    volume: parseNum(row?.Volume),
    settlement: parseNum(row?.SettlementPrice),
    openInterest: parseNum(row?.OpenInterest),
    bestBid: parseNum(row?.BestBid),
    bestAsk: parseNum(row?.BestAsk),
    source: "TAIFEX OpenAPI 期貨每日交易行情",
  };
}

function calcPercentFromRef(last, change, ref) {
  return Number.isFinite(change) && Number.isFinite(ref) && ref !== 0 ? (change / ref) * 100 : calcPercentChange(last, change);
}

function inferTaifexMISSession(row) {
  const marketType = String(row?.__marketType || "").trim();
  const symbolId = String(row?.SymbolID || "").trim();
  if (marketType === "0" || /-F$/i.test(symbolId)) return "一般";
  if (marketType === "1" || /-M$/i.test(symbolId)) return "盤後";
  const name = `${row?.DispCName || ""}${row?.DispEName || ""}`;
  if (name.includes("全")) return "盤後";
  const status = String(row?.Status || "").trim();
  return status === "TC" ? "一般" : "盤後";
}

function normalizeTaifexMISQuote(row, index = 0) {
  const name = String(row?.DispCName || "").trim();
  const displayName = String(row?.DispEName || "").trim();
  const symbolId = String(row?.SymbolID || "").trim();
  const contract = symbolId.startsWith("MX") || displayName.startsWith("MTX") || displayName.startsWith("MX")
    ? "MTX"
    : symbolId.startsWith("TM") || displayName.startsWith("TM")
      ? "TMF"
      : "TX";
  const last = parseNum(row?.CLastPrice);
  const change = parseNum(row?.CDiff);
  const ref = parseNum(row?.CRefPrice);
  const diffRate = parseNum(row?.CDiffRate);
  const time = String(row?.CTime || "").trim();
  const formattedTime = formatCompactTime(time);
  const status = String(row?.Status || "").trim();
  const session = inferTaifexMISSession(row);
  return {
    date: "",
    contract,
    label: futuresLabel(contract),
    month: displayName.replace(/^[A-Z]+/i, "") || name.replace(/[^\d]/g, "") || "",
    session,
    open: parseNum(row?.COpenPrice),
    high: parseNum(row?.CHighPrice),
    low: parseNum(row?.CLowPrice),
    last,
    change,
    percent: Number.isFinite(diffRate) ? diffRate : calcPercentFromRef(last, change, ref),
    volume: parseNum(row?.CTotalVolume),
    settlement: null,
    openInterest: null,
    bestBid: parseNum(row?.CBidPrice1),
    bestAsk: parseNum(row?.CAskPrice1),
    ref,
    time,
    status,
    marketType: String(row?.__marketType || "").trim(),
    order: index,
    source: `TAIFEX MIS 即時行情 ${session}${formattedTime ? ` ${formattedTime}` : ""}`,
  };
}

function pickTaifexMISFrontRows(quotes) {
  const normalized = (quotes || [])
    .map(normalizeTaifexMISQuote)
    .filter((row) => ["TX", "MTX", "TMF"].includes(row.contract) && Number.isFinite(row.last) && /^\d+$/.test(row.month))
    .sort((a, b) => a.contract.localeCompare(b.contract) || a.order - b.order);
  const byContract = {};
  for (const contract of ["TX", "MTX", "TMF"]) {
    const rows = normalized.filter((row) => row.contract === contract);
    const frontMonth = pickVisibleFuturesFrontMonth(rows.map((row) => row.month)) || rows[0]?.month || "";
    const frontRows = rows.filter((row) => row.month === frontMonth);
    byContract[contract] = {
      regular: frontRows.find((row) => row.session === "一般") || null,
      afterHour: frontRows.find((row) => row.session === "盤後") || null,
    };
  }
  return {
    byContract,
    regular: byContract.TX?.regular || null,
    afterHour: byContract.TX?.afterHour || null,
  };
}

async function loadTaifexMISQuotes() {
  if (futuresMISReady) return futuresMISReady;
  futuresMISReady = (async () => {
    const requests = [];
    for (const MarketType of ["0", "1"]) {
      for (const CID of ["TXF", "MXF", "TMF"]) {
        requests.push(postJSON(MARKET_INDEX_ENDPOINTS.futuresMIS, {
          MarketType,
          SymbolType: "F",
          KindID: "1",
          CID,
          ExpireMonth: "",
          RowSize: "999",
          PageNo: "",
          SortColumn: "",
          AscDesc: "A",
        }, `TAIFEX MIS 期貨即時行情 ${CID}`, { timeoutMs: 10000 }));
      }
    }
    const results = await Promise.allSettled(requests);
    const list = results.flatMap((result, requestIndex) => {
      const rows = result.status === "fulfilled" && Array.isArray(result.value?.RtData?.QuoteList) ? result.value.RtData.QuoteList : [];
      const marketType = requestIndex < 3 ? "0" : "1";
      return rows.map((row) => ({ ...row, __marketType: marketType }));
    });
    return { raw: results, quotes: list, ...pickTaifexMISFrontRows(list) };
  })();
  return futuresMISReady;
}

async function loadFuturesData() {
  if (futuresDataReady) return futuresDataReady;
  futuresDataReady = (async () => {
    const [rowsResult, nameMapResult] = await Promise.allSettled([
      fetchJSON(MARKET_INDEX_ENDPOINTS.futures, "TAIFEX 期貨每日交易行情"),
      loadFuturesNameMap(),
    ]);
    const nameMap = nameMapResult.status === "fulfilled" ? nameMapResult.value : new Map(Object.entries(FUTURES_LABELS));
    const allOpenApiRows = rowsResult.status === "fulfilled" && Array.isArray(rowsResult.value)
      ? rollExpiringFrontFuturesRows(rowsResult.value
        .map(normalizeFuturesRow)
        .map((row) => ({ ...row, label: nameMap.get(row.contract) || row.label }))
        .filter((row) => row.contract && row.month))
      : [];
    const openApiRows = allOpenApiRows.length
      ? pickFrontRowPerContract(allOpenApiRows.filter((row) => row.session !== "盤後"))
      : [];
    const openApiAfterHourRows = allOpenApiRows.length
      ? pickFrontRowPerContract(allOpenApiRows.filter((row) => row.session === "盤後"))
      : [];
    if (openApiRows.length || openApiAfterHourRows.length) {
      return { rows: [...openApiRows, ...openApiAfterHourRows], officialAfterHourRows: openApiAfterHourRows };
    }

    const [officialGeneralResult, officialAfterHourResult] = await Promise.allSettled([
      loadTaifexOfficialGeneralRows(),
      loadTaifexOfficialAfterHourRows(),
    ]);
    const officialGeneralRows = officialGeneralResult.status === "fulfilled"
      ? officialGeneralResult.value.map((row) => ({ ...row, label: nameMap.get(row.contract) || row.label }))
      : [];
    const officialAfterHourRows = officialAfterHourResult.status === "fulfilled"
      ? officialAfterHourResult.value.map((row) => ({ ...row, label: nameMap.get(row.contract) || row.label }))
      : [];
    const mergedRows = [
      ...officialGeneralRows,
      ...officialAfterHourRows,
    ];
    const seen = new Set();
    const rows = mergedRows.filter((row) => {
      const key = `${row.contract}|${row.month}|${row.session || ""}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
    return { rows, officialAfterHourRows };
  })();
  return futuresDataReady;
}

function pickTaifexFullQuote(mis) {
  if (!mis) return null;
  return mis.afterHour || mis.regular || null;
}

function getFrontFuturesRows(rows) {
  return ["TX", "MTX", "TMF", "TE", "TF", "GTF"]
    .map((contract) => {
      const list = rows
        .filter((row) => row.contract === contract && !row.month.includes("/") && Number.isFinite(row.last))
        .sort((a, b) => a.month.localeCompare(b.month) || (a.session === "一般" ? -1 : 1));
      const frontMonth = pickVisibleFuturesFrontMonth(list.map((row) => row.month));
      const frontRows = frontMonth ? list.filter((row) => row.month === frontMonth) : list;
      return frontRows.find((row) => row.session === "一般") || frontRows[0] || null;
    })
    .filter(Boolean);
}

function normalizeMISIndex(item, { key, title, source, accent }) {
  const value = parseNum(item?.z) ?? parseNum(item?.y);
  const prev = parseNum(item?.y);
  const change = Number.isFinite(value) && Number.isFinite(prev) ? value - prev : null;
  return normalizeIndexSummary({
    key,
    title,
    value,
    change,
    percent: calcPercentChange(value, change),
    source,
    accent,
    date: formatTWSEDate(item?.d),
    time: String(item?.t || "").trim(),
  });
}

async function fetchMarketIndexCharts() {
  if (marketIndexChartsReady) return marketIndexChartsReady;
  marketIndexChartsReady = (async () => {
    const payload = await fetchJSON(MARKET_INDEX_ENDPOINTS.marketIndexes, "市場即時指數");
    const indices = payload?.indices || {};
    const cards = [
      ["taiex", "加權指數", UI_COLORS.accent],
      ["tpex", "櫃買指數", UI_COLORS.accentHover],
      ["tx", "台指期日盤", UI_COLORS.accent],
      ["txAfterHour", "台指期夜盤", UI_COLORS.accent],
    ];
    return cards.map(([key, title, accent]) => {
      const value = parseNum(indices[key]?.value);
      const change = parseNum(indices[key]?.change);
      return normalizeIndexSummary({
        key,
        title,
        value,
        change,
        percent: indices[key]?.percent,
        source: indices[key]?.source,
        accent,
        date: formatTWSEDate(indices[key]?.dataDate || indices[key]?.date),
        time: indices[key]?.dataTime || "",
        points: indices[key]?.points || [],
      });
    });
  })();
  return marketIndexChartsReady;
}

function resolveStock(value) {
  const raw = String(value || "").trim().replace(/\s+/g, "");
  const q = raw.toUpperCase();
  const qName = normalizeName(raw);
  if (!q) return null;
  if (codeIndex.has(q)) return codeIndex.get(q);

  const exact = nameIndex.find((s) => s.name === raw || s.kw === qName);
  if (exact) return exact;
  const prefix = nameIndex.find((s) => s.name.startsWith(raw) || s.kw.startsWith(qName));
  if (prefix) return prefix;
  const contains = nameIndex.find((s) => s.name.includes(raw) || s.kw.includes(qName));
  if (contains) return contains;

  if (/^\d{4,6}[A-Z]?$/.test(q)) {
    const ex = q.length === 5 || q.startsWith("6") ? "o" : "t";
    return { code: q, name: q, ex };
  }
  return null;
}

function inferUnderlyingStock(underlyingCode, underlyingName) {
  const code = normalizeWarrantCode(underlyingCode);
  if (code && codeIndex.has(code)) return codeIndex.get(code);
  const name = String(underlyingName || "").trim();
  if (!name) return null;
  const normalized = normalizeLookupName(name);
  return nameIndex.find((s) => s.name === name || normalizeLookupName(s.name) === normalized || normalizeLookupName(s.kw) === normalized)
    || nameIndex.find((s) => s.name.startsWith(name) || normalizeLookupName(s.name).startsWith(normalized) || normalizeLookupName(s.kw).startsWith(normalized))
    || nameIndex.find((s) => s.name.includes(name) || normalizeLookupName(s.name).includes(normalized) || normalizeLookupName(s.kw).includes(normalized))
    || null;
}

function money(value) {
  if (value === null || value === undefined || value === "") return "—";
  const n = parseNum(value);
  return Number.isFinite(n) ? `NT$${n.toLocaleString("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "—";
}

function refreshTimeText(time = lastMarketRefreshAt || Date.now()) {
  return new Date(time).toLocaleTimeString("zh-TW", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

function pct(value) {
  if (value === null || value === undefined || value === "") return "—";
  const n = Number(value);
  return Number.isFinite(n) ? `${(n * 100).toFixed(1)}%` : "—";
}

function pct2(value) {
  if (value === null || value === undefined || value === "") return "—";
  const n = Number(value);
  return Number.isFinite(n) ? `${(n * 100).toFixed(2)}%` : "—";
}

function signedMoney(value) {
  const n = parseNum(value);
  if (!Number.isFinite(n)) return "—";
  const prefix = n > 0 ? "+" : n < 0 ? "-" : "";
  return `${prefix}${money(Math.abs(n))}`;
}

function signedPct(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  const prefix = n > 0 ? "+" : n < 0 ? "-" : "";
  return `${prefix}${Math.abs(n * 100).toFixed(2)}%`;
}

function moveMarker(value) {
  const n = Number(value);
  if (n > 0) return "▲";
  if (n < 0) return "▼";
  return "";
}

function formatMoveText(value, renderValue) {
  const n = parseNum(value);
  if (!Number.isFinite(n)) return "—";
  const marker = moveMarker(n);
  const text = renderValue(Math.abs(n));
  return `${marker ? `${marker} ` : ""}${text}`;
}

function formatMoveNumber(value, digits = 2) {
  return formatMoveText(value, (n) => fixed(n, digits));
}

function formatMoveQuote(value, digits = 2) {
  return formatMoveText(value, (n) => renderMarketQuoteCell(n, digits));
}

function formatMovePercent(value, digits = 2) {
  return formatMoveText(value, (n) => `${fixed(n, digits)}%`);
}

function fixed(value, digits = 3) {
  if (value === null || value === undefined || value === "") return "—";
  const n = Number(value);
  return Number.isFinite(n) ? n.toFixed(digits) : "—";
}

function intText(value) {
  if (value === null || value === undefined || value === "") return "—";
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(n).toLocaleString("zh-TW") : "—";
}

function round(value, digits = 2) {
  const p = 10 ** digits;
  return Math.round((Number(value) + Number.EPSILON) * p) / p;
}

function htmlEscape(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function parseNum(value) {
  const text = String(value ?? "").replaceAll(",", "").trim();
  if (!text || text === "-" || text === "--") return null;
  const n = Number(text);
  return Number.isFinite(n) ? n : null;
}

function pickNumber(row, fields) {
  for (const field of fields) {
    const value = parseNum(row?.[field]);
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function changeInfo(cur, prev) {
  if (!Number.isFinite(Number(cur)) || !Number.isFinite(Number(prev)) || Number(prev) === 0) return null;
  const diff = Number(cur) - Number(prev);
  return { diff, pct: (diff / Number(prev)) * 100, up: diff >= 0 };
}

function marketMoveClass(value) {
  const n = Number(value);
  if (n > 0) return "up";
  if (n < 0) return "down";
  return "flat";
}

function marketMoveColor(value) {
  const tone = marketMoveClass(value);
  if (tone === "up") return "var(--market-up)";
  if (tone === "down") return "var(--market-down)";
  return UI_COLORS.muted;
}

const LOCAL_APP_HOSTS = new Set(["localhost", "127.0.0.1", "::1", "[::1]"]);
const LOCAL_API_ORIGIN = "http://127.0.0.1:5173";
const LOCAL_WORKER_PORTS = new Set(["5099", "5173", "8787", "8899"]);
const PUBLIC_PROXY_HOSTS = new Set([
  "mis.taifex.com.tw",
  "openapi.twse.com.tw",
  "openapi.taifex.com.tw",
  "www.twse.com.tw",
  "www.tpex.org.tw",
  "www.taifex.com.tw",
  "mopsov.twse.com.tw",
  "stockhomes.org",
]);
const TPEX_STATIC_ENDPOINTS = new Set([
  "mopsfin_t187ap03_O",
  "mopsfin_t187ap06_O_basi",
  "mopsfin_t187ap06_O_bd",
  "mopsfin_t187ap06_O_ci",
  "mopsfin_t187ap06_O_fh",
  "mopsfin_t187ap06_O_ins",
  "mopsfin_t187ap06_O_mim",
  "mopsfin_t187ap07_O_basi",
  "mopsfin_t187ap07_O_bd",
  "mopsfin_t187ap07_O_ci",
  "mopsfin_t187ap07_O_fh",
  "mopsfin_t187ap07_O_ins",
  "mopsfin_t187ap07_O_mim",
  "mopsfin_t187ap37_O",
  "tpex_3insti_daily_trading",
  "tpex_exright_prepost",
  "tpex_index",
  "tpex_mainboard_daily_close_quotes",
  "tpex_mainboard_margin_balance",
  "tpex_mainboard_peratio_analysis",
  "tpex_mainboard_quotes",
  "tpex_mainborad_highlight",
  "tpex_warrant_daily_quts",
  "tpex_warrant_issue",
]);

function isLocalAppHost() {
  return location.protocol === "file:" || LOCAL_APP_HOSTS.has(location.hostname);
}

function shouldUseLocalApiOrigin() {
  return isLocalAppHost() && !(LOCAL_APP_HOSTS.has(location.hostname) && LOCAL_WORKER_PORTS.has(location.port));
}

function apiURL(path) {
  const normalized = String(path || "");
  if (!normalized.startsWith("/api/")) return normalized;
  return shouldUseLocalApiOrigin() ? `${LOCAL_API_ORIGIN}${normalized}` : normalized;
}

function tpexStaticURL(url) {
  if (isLocalAppHost()) return "";
  try {
    const parsed = new URL(url);
    if (parsed.hostname !== "www.tpex.org.tw" || !parsed.pathname.startsWith("/openapi/v1/")) return "";
    const endpoint = parsed.pathname.split("/").pop();
    return TPEX_STATIC_ENDPOINTS.has(endpoint) ? `/data/tpex/${endpoint}.json` : "";
  } catch (_) {
    return "";
  }
}

function shouldUsePublicProxy(url) {
  if (isLocalAppHost()) return false;
  try {
    return PUBLIC_PROXY_HOSTS.has(new URL(url).hostname);
  } catch (_) {
    return false;
  }
}

function proxyURL(url) {
  const normalized = String(url);
  if (normalized.startsWith("/api/")) return apiURL(normalized);
  if (normalized.startsWith("/")) return normalized;
  const staticUrl = tpexStaticURL(normalized);
  if (staticUrl) return staticUrl;
  if (shouldUsePublicProxy(normalized)) return apiURL(`/api/fetch?url=${encodeURIComponent(normalized)}`);
  return isLocalAppHost() ? apiURL(`/api/fetch?url=${encodeURIComponent(normalized)}`) : normalized;
}

async function fetchWithTimeout(url, options = {}, timeoutMs = 18000) {
  if (!timeoutMs || typeof AbortController === "undefined") return fetch(url, options);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } catch (error) {
    if (error?.name === "AbortError") throw new Error("請求逾時");
    throw error;
  } finally {
    clearTimeout(timer);
  }
}

async function fetchJSON(url, label, options = {}) {
  const response = await fetchWithTimeout(proxyURL(url), { cache: "no-store" }, options.timeoutMs);
  const text = await response.text();
  if (!response.ok) {
    let detail = text.slice(0, 220);
    try {
      const payload = JSON.parse(text);
      detail = payload.message || payload.error || detail;
    } catch (_) {}
    throw new Error(`${label} HTTP ${response.status}${detail ? `：${detail}` : ""}`);
  }
  const trimmed = text.trim();
  const jsonStart = trimmed.startsWith("[") ? 0 : text.indexOf("{");
  const jsonText = trimmed.startsWith("[") ? trimmed : jsonStart >= 0 ? text.slice(jsonStart) : text;
  return JSON.parse(jsonText);
}

function twseMISChannel(code, ex) {
  const prefix = ex === "o" || ex === "otc" ? "otc" : "tse";
  const normalizedCode = String(code || "").trim().toUpperCase();
  return normalizedCode ? `${prefix}_${normalizedCode}.tw` : "";
}

async function fetchRealtimeMISData(channels, label = "TWSE MIS 即時報價") {
  const list = [...new Set((Array.isArray(channels) ? channels : [channels])
    .map((channel) => String(channel || "").trim())
    .filter(Boolean))];
  if (!list.length) return { ok: true, msgArray: [] };
  return fetchJSON(`/api/realtime-quotes?channels=${encodeURIComponent(list.join("|"))}`, label, { timeoutMs: 12000 });
}

async function postJSON(url, payload, label, options = {}) {
  const response = await fetchWithTimeout(proxyURL(url), {
    method: "POST",
    cache: "no-store",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  }, options.timeoutMs);
  const text = await response.text();
  if (!response.ok) {
    let detail = text.slice(0, 220);
    try {
      const body = JSON.parse(text);
      detail = body.message || body.error || body.RtMsg || detail;
    } catch (_) {}
    throw new Error(`${label} HTTP ${response.status}${detail ? `：${detail}` : ""}`);
  }
  return JSON.parse(text.trim());
}

async function fetchText(url, label, options = {}) {
  const response = await fetchWithTimeout(proxyURL(url), { cache: "no-store" }, options.timeoutMs);
  const text = await response.text();
  if (!response.ok) {
    let detail = text.slice(0, 220);
    try {
      const payload = JSON.parse(text);
      detail = payload.message || payload.error || detail;
    } catch (_) {}
    throw new Error(`${label} HTTP ${response.status}${detail ? `：${detail}` : ""}`);
  }
  return text;
}

function normalizeWarrantCode(value) {
  return String(value || "").trim().replace(/\s+/g, "").toUpperCase();
}

function pickWarrantText(row, fields) {
  for (const field of fields) {
    const value = row?.[field];
    if (value !== null && value !== undefined && String(value).trim() !== "") return String(value).trim();
  }
  return "";
}

const WARRANT_ISSUER_NAMES = [
  "中國信託", "華南永昌", "摩根大通", "麥格理", "元大", "凱基", "群益", "統一", "永豐", "國票",
  "元富", "富邦", "國泰", "中信", "兆豐", "台新", "永昌", "第一", "合庫", "康和",
  "玉山", "宏遠", "日盛", "大展", "麥證", "花旗", "美林",
];

function normalizeIssuerName(value) {
  return String(value || "")
    .replace(/證券|綜合證券|股份|有限|公司|\s+/g, "")
    .trim();
}

function inferWarrantIssuer(entry = {}) {
  const direct = normalizeIssuerName(pickWarrantText(entry, [
    "發行人",
    "發行公司",
    "發行機構",
    "Issuer",
    "IssuerName",
    "Issuer Name",
    "SecuritiesCompany",
    "SecuritiesCompanyName",
  ]));
  if (direct) return direct;

  const nameHead = String(entry.name || entry.Name || entry["權證簡稱"] || entry["權證名稱"] || "")
    .split(/[購售牛熊]/)[0];
  let issuer = "";
  let issuerIndex = -1;
  for (const candidate of WARRANT_ISSUER_NAMES) {
    const index = nameHead.lastIndexOf(candidate);
    if (index > issuerIndex || (index === issuerIndex && candidate.length > issuer.length)) {
      issuer = candidate;
      issuerIndex = index;
    }
  }
  return issuerIndex >= 0 ? issuer : "";
}

function getWarrantIssuerOptions(warrants = warrantNameIndex) {
  return [...new Set(warrants.map((item) => normalizeIssuerName(item.issuer)).filter(Boolean))]
    .sort((a, b) => a.localeCompare(b, "zh-Hant"));
}

function updateWarrantIssuerOptions(inputElement, warrants = warrantNameIndex) {
  if (!inputElement) return;
  const selected = inputElement.value;
  const issuers = getWarrantIssuerOptions(warrants);
  const nextValue = selected && issuers.includes(selected) ? selected : "";
  inputElement.innerHTML = [
    `<option value="">全部發行公司</option>`,
    ...issuers.map((issuer) => `<option value="${htmlEscape(issuer)}">${htmlEscape(issuer)}</option>`),
  ].join("");
  inputElement.value = nextValue;
}

function updateStrategyIssuerOptions(warrants = warrantNameIndex) {
  updateWarrantIssuerOptions(strategyIssuerInput, warrants);
}

function formatMarketDate(value) {
  const text = String(value || "").trim();
  if (!text) return "—";
  if (/^\d{8}$/.test(text)) return `${text.slice(0, 4)}-${text.slice(4, 6)}-${text.slice(6, 8)}`;
  if (/^\d{7}$/.test(text)) return formatTWSEDate(text);
  return text;
}

function addWarrantEntry(entry) {
  const code = normalizeWarrantCode(entry.code);
  if (!code || warrantCodeIndex.has(code)) return;
  const name = String(entry.name || code).trim();
  const type = String(entry.type || "").trim();
  const underlying = String(entry.underlying || "").trim();
  const underlyingCode = normalizeWarrantCode(entry.underlyingCode);
  const issuer = normalizeIssuerName(entry.issuer || inferWarrantIssuer(entry));
  const exercisePrice = parseNum(entry.exercisePrice);
  const expiryDate = formatMarketDate(entry.expiryDate);
  const volume = parseNum(entry.volume);
  const value = parseNum(entry.value);
  const item = {
    code,
    name,
    ex: entry.ex,
    type,
    issuer,
    underlying,
    underlyingCode,
    exercisePrice,
    expiryDate,
    volume,
    value,
    kw: normalizeName(name),
    underlyingKw: normalizeName(underlying),
    searchText: normalizeName(`${code} ${name} ${type} ${issuer} ${underlying} ${underlyingCode}`),
  };
  warrantCodeIndex.set(code, item);
  warrantNameIndex.push(item);
}

async function loadWarrantDatabase() {
  if (warrantDbReady) return warrantDbReady;
  warrantDbReady = (async () => {
    const results = await Promise.allSettled([
      fetchJSON(WARRANT_ENDPOINTS.twseBasic, "TWSE 上市權證基本資料"),
      fetchJSON(WARRANT_ENDPOINTS.tpexIssue, "TPEx 上櫃權證發行資料"),
      fetchJSON(WARRANT_ENDPOINTS.tpexBasic, "TPEx 上櫃權證基本資料"),
      fetchJSON(WARRANT_ENDPOINTS.twseDaily, "TWSE 上市權證每日成交資料"),
      fetchJSON(WARRANT_ENDPOINTS.tpexDaily, "TPEx 上櫃權證收盤行情"),
    ]);
    const twseDailyMap = new Map((results[3].status === "fulfilled" && Array.isArray(results[3].value) ? results[3].value : [])
      .map((row) => [normalizeWarrantCode(row["權證代號"]), row]));
    const tpexDailyMap = new Map((results[4].status === "fulfilled" && Array.isArray(results[4].value) ? results[4].value : [])
      .map((row) => [normalizeWarrantCode(row.Code), row]));

    for (const row of results[0].status === "fulfilled" && Array.isArray(results[0].value) ? results[0].value : []) {
      const trade = twseDailyMap.get(normalizeWarrantCode(row["權證代號"])) || {};
      addWarrantEntry({
        code: row["權證代號"],
        name: row["權證簡稱"],
        ex: "t",
        type: row["權證類型"] || row["類別"],
        underlying: row["標的證券/指數"],
        underlyingCode: "",
        exercisePrice: row["最新履約價格(元)/履約指數"] || row["原始履約價格(元)/履約指數"],
        expiryDate: row["履約截止日"] || row["最後交易日"],
        volume: trade["成交張數"],
        value: trade["成交金額"],
      });
    }
    for (const row of results[1].status === "fulfilled" && Array.isArray(results[1].value) ? results[1].value : []) {
      const trade = tpexDailyMap.get(normalizeWarrantCode(row.Code)) || {};
      addWarrantEntry({
        code: row.Code,
        name: row.Name,
        ex: "o",
        type: row.Type,
        underlying: row.UnderlyingStock || row.UnderlyingStockCode,
        underlyingCode: row.UnderlyingStockCode,
        exercisePrice: row.LatestExercisePrice,
        expiryDate: row.ExpiryDate,
        volume: trade["TradeVol."],
        value: trade.TradeValue,
      });
    }
    for (const row of results[2].status === "fulfilled" && Array.isArray(results[2].value) ? results[2].value : []) {
      const trade = tpexDailyMap.get(normalizeWarrantCode(row["權證代號"])) || {};
      addWarrantEntry({
        code: row["權證代號"],
        name: row["權證簡稱"],
        ex: "o",
        type: row["權證類型"] || row["類別"],
        underlying: row["標的證券/指數"],
        underlyingCode: "",
        exercisePrice: row["最新履約價格(元)/履約指數"] || row["原始履約價格(元)/履約指數"],
        expiryDate: row["履約截止日"] || row["最後交易日"],
        volume: trade["TradeVol."],
        value: trade.TradeValue,
      });
    }

    warrantNameIndex.sort((a, b) => a.code.localeCompare(b.code));
    return warrantNameIndex;
  })();
  return warrantDbReady;
}

function resolveWarrant(value) {
  const raw = String(value || "").trim().replace(/\s+/g, "");
  const q = normalizeWarrantCode(raw);
  const qName = normalizeName(raw);
  if (!q) return null;
  if (warrantCodeIndex.has(q)) return warrantCodeIndex.get(q);
  return warrantNameIndex.find((s) => s.name === raw || s.kw === qName)
    || warrantNameIndex.find((s) => s.code.startsWith(q) || s.name.startsWith(raw) || s.kw.startsWith(qName) || s.underlyingCode.startsWith(q))
    || warrantNameIndex.find((s) => s.code.includes(q) || s.name.includes(raw) || s.kw.includes(qName) || s.underlying.includes(raw) || s.underlyingKw.includes(qName) || s.underlyingCode.includes(q))
    || (/^[0-9A-Z]{5,7}$/.test(q) ? { code: q, name: q, ex: q.startsWith("7") ? "o" : "t", type: "", underlying: "" } : null);
}

function getWarrantPredictions(raw) {
  const q = normalizeWarrantCode(raw);
  const qName = normalizeName(raw);
  if (!q && !qName) return [];
  return warrantNameIndex
    .map((s) => {
      let score = 0;
      if (s.code === q) score += 1000;
      else if (s.code.startsWith(q)) score += 760 - Math.abs(s.code.length - q.length);
      else if (s.code.includes(q)) score += 360;
      if (s.name === raw) score += 900;
      else if (s.name.startsWith(raw)) score += 640 - Math.abs(s.name.length - raw.length);
      else if (s.name.includes(raw)) score += 420;
      if (s.kw === qName) score += 760;
      else if (s.kw.startsWith(qName)) score += 540 - Math.abs(s.kw.length - qName.length);
      else if (s.kw.includes(qName)) score += 300;
      if (s.underlyingCode === q) score += 620;
      else if (s.underlyingCode.startsWith(q)) score += 460;
      else if (s.underlyingCode.includes(q)) score += 260;
      if (s.underlying === raw) score += 620;
      else if (s.underlying.startsWith(raw) || s.underlyingKw.startsWith(qName)) score += 460;
      else if (s.underlying.includes(raw) || s.underlyingKw.includes(qName)) score += 260;
      if (s.type && normalizeName(s.type).includes(qName)) score += 120;
      if (s.searchText.includes(qName)) score += 80;
      return { ...s, score };
    })
    .filter((s) => s.score > 0)
    .sort((a, b) => b.score - a.score || a.code.localeCompare(b.code))
    .slice(0, 7);
}

function resolveWarrantUnderlying(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  const q = normalizeWarrantCode(raw);
  const qName = normalizeLookupName(raw);
  const stock = resolveStock(raw);
  if (stock && (codeIndex.has(stock.code) || nameIndex.some((s) => s.code === stock.code))) return stock;
  return nameIndex.find((s) => s.code === q)
    || nameIndex.find((s) => normalizeLookupName(s.name) === qName || normalizeLookupName(s.kw) === qName)
    || nameIndex.find((s) => normalizeLookupName(s.name).startsWith(qName) || normalizeLookupName(s.kw).startsWith(qName))
    || null;
}

function getWarrantsByUnderlying(stock) {
  if (!stock) return [];
  const code = normalizeWarrantCode(stock.code);
  const rawName = String(stock.name || "").trim();
  const name = normalizeLookupName(stock.name);
  const seen = new Set();
  return warrantNameIndex
    .filter((w) => {
      const underlyingCode = normalizeWarrantCode(w.underlyingCode);
      const rawUnderlyingName = String(w.underlying || "").trim();
      const underlyingName = normalizeLookupName(w.underlying);
      return underlyingCode === code
        || (rawName && rawUnderlyingName === rawName)
        || (rawName && rawUnderlyingName.startsWith(rawName))
        || (rawName && String(w.name || "").startsWith(rawName))
        || (code && String(w.name || "").startsWith(rawName || code))
        || underlyingName === name
        || underlyingName.startsWith(name)
        || (name && underlyingName.includes(name));
    })
    .filter((w) => {
      if (seen.has(w.code)) return false;
      seen.add(w.code);
      return true;
    })
    .sort((a, b) => {
      const typeScore = (item) => String(item.type || item.name).includes("認購") || String(item.name).includes("購") ? 0 : String(item.type || item.name).includes("認售") || String(item.name).includes("售") ? 1 : 2;
      return typeScore(a) - typeScore(b) || a.code.localeCompare(b.code);
    });
}

function groupWarrantsByType(items) {
  const groups = {
    call: [],
    put: [],
    other: [],
  };
  for (const item of items) {
    const side = getWarrantSide(item);
    if (side === "call") groups.call.push(item);
    else if (side === "put") groups.put.push(item);
    else groups.other.push(item);
  }
  return groups;
}

function getWarrantSide(item) {
  const text = `${item?.type || ""} ${item?.name || ""}`;
  if (text.includes("認購") || text.includes("購")) return "call";
  if (text.includes("認售") || text.includes("售")) return "put";
  return "other";
}

function parseMarketDateValue(value) {
  const text = String(value || "").trim();
  if (!text || text === "—") return null;
  const normalized = formatMarketDate(text);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) return null;
  const date = new Date(`${normalized}T00:00:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function daysUntil(value) {
  const target = parseMarketDateValue(value);
  if (!target) return null;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.ceil((target.getTime() - today.getTime()) / 86400000);
}

function formatExpiryDistance(days) {
  if (!Number.isFinite(days)) return "";
  if (days > 0) return `距到期 ${Math.round(days)} 天`;
  if (days === 0) return "今日到期";
  return `已到期 ${Math.abs(Math.round(days))} 天`;
}

function readStrategyNumber(inputEl, fallback, options = {}) {
  const value = parseNum(inputEl?.value);
  const min = Number.isFinite(options.min) ? options.min : 0;
  if (!Number.isFinite(value) || value < min) return fallback;
  return options.integer ? Math.round(value) : Math.round(value * 100) / 100;
}

function normalizeRange(minValue, maxValue) {
  return minValue <= maxValue ? [minValue, maxValue] : [maxValue, minValue];
}

function getWarrantLookupConfig() {
  const rawIssuer = String(warrantIssuerInput?.value || "").trim();
  const issuer = rawIssuer && rawIssuer !== "全部發行公司" ? normalizeIssuerName(rawIssuer) : "";
  return { issuer };
}

function filterWarrantsByIssuer(warrants, issuer) {
  const activeIssuer = normalizeIssuerName(issuer);
  if (!activeIssuer) return warrants;
  return warrants.filter((item) => normalizeIssuerName(item.issuer) === activeIssuer);
}

function getStrategyConfig() {
  const [expiryMin, expiryMax] = normalizeRange(
    readStrategyNumber(strategyInputs.expiryMin, 110, { min: 1, integer: true }),
    readStrategyNumber(strategyInputs.expiryMax, 150, { min: 1, integer: true }),
  );
  const [callMin, callMax] = normalizeRange(
    readStrategyNumber(strategyInputs.callMin, 1.2, { min: 0.01 }),
    readStrategyNumber(strategyInputs.callMax, 1.5, { min: 0.01 }),
  );
  const [putMin, putMax] = normalizeRange(
    readStrategyNumber(strategyInputs.putMin, 0.5, { min: 0.01 }),
    readStrategyNumber(strategyInputs.putMax, 0.8, { min: 0.01 }),
  );
  const rawIssuer = String(strategyIssuerInput?.value || "").trim();
  const issuer = rawIssuer && rawIssuer !== "全部發行公司" ? normalizeIssuerName(rawIssuer) : "";
  return { expiryMin, expiryMax, callMin, callMax, putMin, putMax, issuer };
}

function formatStrategyRatio(value) {
  return Number(value).toFixed(2);
}

function formatStrategyInput(inputEl) {
  if (!inputEl) return;
  const isInteger = inputEl.id.includes("Expiry");
  const fallback = parseNum(inputEl.defaultValue);
  const value = readStrategyNumber(inputEl, fallback, { min: isInteger ? 1 : 0.01, integer: isInteger });
  inputEl.value = isInteger ? String(value) : formatStrategyRatio(value);
}

function getStrategyWarrants(warrants, currentPrice, config = getStrategyConfig()) {
  const price = parseNum(currentPrice);
  if (!Number.isFinite(price) || price <= 0) return [];
  const availableIssuers = new Set(warrants.map((item) => normalizeIssuerName(item.issuer)).filter(Boolean));
  const activeIssuer = config.issuer && availableIssuers.has(config.issuer) ? config.issuer : "";
  return warrants
    .map((item) => {
      const exercise = parseNum(item.exercisePrice);
      const expiryDays = daysUntil(item.expiryDate);
      const exerciseRatio = Number.isFinite(exercise) ? exercise / price : null;
      const strategySide = getWarrantSide(item);
      return { ...item, strategyExerciseRatio: exerciseRatio, strategyExpiryDays: expiryDays, strategySide };
    })
    .filter((item) => {
      const validExpiry = Number.isFinite(item.strategyExpiryDays)
        && item.strategyExpiryDays >= config.expiryMin
        && item.strategyExpiryDays <= config.expiryMax;
      if (!validExpiry || !Number.isFinite(item.strategyExerciseRatio)) return false;
      if (activeIssuer && normalizeIssuerName(item.issuer) !== activeIssuer) return false;
      if (item.strategySide === "call") return item.strategyExerciseRatio >= config.callMin && item.strategyExerciseRatio <= config.callMax;
      if (item.strategySide === "put") return item.strategyExerciseRatio >= config.putMin && item.strategyExerciseRatio <= config.putMax;
      return false;
    })
    .sort((a, b) => a.strategyExpiryDays - b.strategyExpiryDays || a.strategyExerciseRatio - b.strategyExerciseRatio || a.code.localeCompare(b.code));
}

async function enrichWarrantDetail(detail) {
  await fillWarrantDetailFromMIS(detail);
  try {
    await loadStockDatabase();
  } catch (_) {}
  const underlyingStock = inferUnderlyingStock(detail.underlyingCode, detail.underlying);
  if (!underlyingStock) {
    const fallback = await fetchUnderlyingQuoteByName(detail.underlying);
    if (fallback) {
      detail.underlyingCode = detail.underlyingCode || fallback.code;
      detail.underlying = detail.underlying || fallback.name;
      detail.underlyingExchange = fallback.ex === "otc" ? "上櫃 OTC" : "上市 TWSE";
      detail.underlyingClose = fallback.price;
      detail.underlyingPriceType = fallback.priceType;
      detail.underlyingQuoteDate = [fallback.date, fallback.time].filter(Boolean).join(" ");
    }
    return detail;
  }

  detail.underlyingCode = detail.underlyingCode || underlyingStock.code;
  detail.underlying = detail.underlying || underlyingStock.name;
  detail.underlyingExchange = underlyingStock.ex === "o" ? "上櫃 OTC" : "上市 TWSE";

  if (!Number.isFinite(parseNum(detail.underlyingClose)) || !detail.underlyingQuoteDate) {
    try {
      const quote = await fetchUnderlyingQuote(underlyingStock.code, underlyingStock.ex);
      if (!Number.isFinite(parseNum(detail.underlyingClose))) detail.underlyingClose = parseNum(quote.price);
      detail.underlyingPriceType = quote.priceType;
      detail.underlyingQuoteDate = [quote.date, quote.time].filter(Boolean).join(" ");
    } catch (_) {
      // Keep official warrant data even if the underlying quote endpoint is temporarily unavailable.
    }
  }
  return detail;
}

function applyMissingNumber(target, key, value) {
  const current = parseNum(target[key]);
  const next = parseNum(value);
  if (!Number.isFinite(current) && Number.isFinite(next)) target[key] = next;
}

async function fetchWarrantMISQuote(code, market) {
  const data = await fetchRealtimeMISData([twseMISChannel(code, market)], "TWSE MIS 權證即時報價");
  const s = data?.msgArray?.[0];
  if (!s || !s.c) return null;
  const last = parseNum(s.z);
  const prevClose = parseNum(s.y);
  const open = parseNum(s.o);
  const high = parseNum(s.h);
  const low = parseNum(s.l);
  return {
    code: s.c,
    name: s.n || s.nf || "",
    open,
    high,
    low,
    close: Number.isFinite(last) ? last : null,
    prevClose,
    change: Number.isFinite(last) && Number.isFinite(prevClose) ? round(last - prevClose, 2) : null,
    volume: parseNum(s.v),
    date: formatTWSEDate(s.d),
    time: s.t || s["%"] || "",
    source: "TWSE MIS 即時報價",
  };
}

async function fillWarrantDetailFromMIS(detail) {
  try {
    const quote = await fetchWarrantMISQuote(detail.code, detail.market);
    if (!quote) return detail;
    applyMissingNumber(detail, "open", quote.open);
    applyMissingNumber(detail, "high", quote.high);
    applyMissingNumber(detail, "low", quote.low);
    applyMissingNumber(detail, "close", quote.close);
    applyMissingNumber(detail, "prevClose", quote.prevClose);
    applyMissingNumber(detail, "change", quote.change);
    applyMissingNumber(detail, "volume", quote.volume);
    if (!detail.tradeDate && quote.date) detail.tradeDate = quote.date;
    if (!detail.tradeTime && quote.time) detail.tradeTime = quote.time;
    detail.tradeQuoteSource = quote.source;
    if (quote.name && (!detail.name || detail.name === detail.code)) detail.name = quote.name;
  } catch (_) {
    // Keep OpenAPI data when MIS is unavailable.
  }
  return detail;
}

async function fetchWarrantDetail(code) {
  const q = normalizeWarrantCode(code);
  const [twseBasic, twseDaily, tpexIssue, tpexBasic, tpexDaily] = await Promise.allSettled([
    fetchJSON(WARRANT_ENDPOINTS.twseBasic, "TWSE 上市權證基本資料"),
    fetchJSON(WARRANT_ENDPOINTS.twseDaily, "TWSE 上市權證每日成交資料"),
    fetchJSON(WARRANT_ENDPOINTS.tpexIssue, "TPEx 上櫃權證發行資料"),
    fetchJSON(WARRANT_ENDPOINTS.tpexBasic, "TPEx 上櫃權證基本資料"),
    fetchJSON(WARRANT_ENDPOINTS.tpexDaily, "TPEx 上櫃權證收盤行情"),
  ]);

  const from = (result) => result.status === "fulfilled" && Array.isArray(result.value) ? result.value : [];
  const twseBase = from(twseBasic).find((row) => normalizeWarrantCode(row["權證代號"]) === q);
  const twseTrade = from(twseDaily).find((row) => normalizeWarrantCode(row["權證代號"]) === q);
  if (twseBase || twseTrade) {
    return enrichWarrantDetail({
      code: q,
      name: pickWarrantText(twseBase || twseTrade, ["權證簡稱", "權證名稱"]) || q,
      exchange: "上市 TWSE",
      market: "t",
      type: pickWarrantText(twseBase, ["權證類型", "類別"]),
      issuer: inferWarrantIssuer({ ...(twseBase || {}), name: pickWarrantText(twseBase || twseTrade, ["權證簡稱", "權證名稱"]) || q }),
      category: pickWarrantText(twseBase, ["類別"]),
      underlying: pickWarrantText(twseBase, ["標的證券/指數"]),
      exercisePrice: pickNumber(twseBase, ["最新履約價格(元)/履約指數", "原始履約價格(元)/履約指數"]),
      exerciseRatio: pickNumber(twseBase, ["最新標的履約配發數量(每仟單位權證)", "原始標的履約配發數量(每仟單位權證)"]),
      startDate: formatMarketDate(pickWarrantText(twseBase, ["履約開始日"])),
      lastTradeDate: formatMarketDate(pickWarrantText(twseBase, ["最後交易日"])),
      expiryDate: formatMarketDate(pickWarrantText(twseBase, ["履約截止日"])),
      tradeDate: formatMarketDate(pickWarrantText(twseTrade || twseBase, ["交易日期", "出表日期"])),
      volume: pickNumber(twseTrade, ["成交張數"]),
      value: pickNumber(twseTrade, ["成交金額"]),
      transactions: null,
      open: null,
      high: null,
      low: null,
      close: null,
      change: null,
      underlyingClose: null,
      source: "TWSE OpenAPI：上市權證基本資料彙總表 + 每日成交資料檔；空白行情欄位以 TWSE MIS 補值",
    });
  }

  const tpexIssueRow = from(tpexIssue).find((row) => normalizeWarrantCode(row.Code) === q);
  const tpexBase = from(tpexBasic).find((row) => normalizeWarrantCode(row["權證代號"]) === q);
  const tpexTrade = from(tpexDaily).find((row) => normalizeWarrantCode(row.Code) === q);
  if (tpexIssueRow || tpexBase || tpexTrade) {
    return enrichWarrantDetail({
      code: q,
      name: pickWarrantText(tpexIssueRow || tpexBase || tpexTrade, ["Name", "權證簡稱", "權證名稱"]) || q,
      exchange: "上櫃 TPEx",
      market: "o",
      type: pickWarrantText(tpexIssueRow || tpexBase, ["Type", "權證類型", "類別"]),
      issuer: inferWarrantIssuer({ ...(tpexIssueRow || tpexBase || {}), name: pickWarrantText(tpexIssueRow || tpexBase || tpexTrade, ["Name", "權證簡稱", "權證名稱"]) || q }),
      category: pickWarrantText(tpexBase, ["類別"]),
      underlyingCode: pickWarrantText(tpexIssueRow || tpexTrade, ["UnderlyingStockCode"]),
      underlying: pickWarrantText(tpexIssueRow || tpexBase || tpexTrade, ["UnderlyingStock", "標的證券/指數"]),
      exercisePrice: pickNumber(tpexIssueRow || tpexBase, ["LatestExercisePrice", "最新履約價格(元)/履約指數", "原始履約價格(元)/履約指數"]),
      exerciseRatio: pickNumber(tpexIssueRow || tpexBase, ["Latest ExerciseRatio", "最新標的履約配發數量(每仟單位權證)", "原始標的履約配發數量(每仟單位權證)"]),
      startDate: formatMarketDate(pickWarrantText(tpexBase, ["履約開始日"])),
      listedDate: formatMarketDate(pickWarrantText(tpexIssueRow, ["ListedDate"])),
      lastTradeDate: formatMarketDate(pickWarrantText(tpexBase, ["最後交易日"])),
      expiryDate: formatMarketDate(pickWarrantText(tpexIssueRow || tpexBase, ["ExpiryDate", "履約截止日"])),
      tradeDate: formatMarketDate(pickWarrantText(tpexTrade || tpexBase, ["Date", "交易日期", "出表日期"])),
      volume: pickNumber(tpexTrade, ["TradeVol."]),
      value: pickNumber(tpexTrade, ["TradeValue"]),
      transactions: pickNumber(tpexTrade, ["No.OfTransactions"]),
      open: pickNumber(tpexTrade, ["Open"]),
      high: pickNumber(tpexTrade, ["High"]),
      low: pickNumber(tpexTrade, ["Low"]),
      close: pickNumber(tpexTrade, ["Close"]),
      change: pickNumber(tpexTrade, ["Change"]),
      underlyingClose: pickNumber(tpexTrade, ["UnderlyingStockClosePrice"]),
      source: "TPEx OpenAPI：上櫃權證發行基本資料 + 收盤行情；空白行情欄位以 TWSE MIS 補值",
    });
  }

  throw new Error("官方權證端點查無此代號");
}

async function fetchTWSEPrice(code, ex) {
  const prefix = ex === "o" ? "otc" : "tse";
  const data = await fetchRealtimeMISData([twseMISChannel(code, ex)], "TWSE");
  const s = data?.msgArray?.[0];
  if (!s || !s.c) throw new Error(`TWSE 無此股票資料：${prefix}_${code}.tw`);

  const rawLast = parseNum(s.z);
  const last = Number(rawLast) > 0 ? rawLast : null;
  const prev = parseNum(s.y);
  const price = Number(last) > 0 ? last : prev;
  if (!Number.isFinite(price)) throw new Error("TWSE 股價欄位為空，可能目前非交易時段或資料暫停");

  return {
    code: s.c,
    name: s.n || code,
    ex: prefix,
    price,
    lastTrade: last,
    priceType: Number(last) > 0 ? "盤中成交" : "昨收",
    open: parseNum(s.o),
    high: parseNum(s.h),
    low: parseNum(s.l),
    prevClose: prev,
    date: formatTWSEDate(s.d),
    time: s.t || s["%"] || "",
  };
}

function formatTWSEDate(value) {
  const s = String(value || "");
  if (/^\d{7}$/.test(s)) {
    const y = Number(s.slice(0, 3)) + 1911;
    return `${y}-${s.slice(3, 5)}-${s.slice(5, 7)}`;
  }
  return /^\d{8}$/.test(s) ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}` : s;
}

async function fetchSupport(code, ex) {
  const openApiSupport = await fetchOpenAPIDailySupport(code, ex);
  if (Number.isFinite(openApiSupport)) return openApiSupport;
  if (ex === "o") return null;

  const lows = [];
  const now = new Date();
  for (let i = 0; i < 2; i += 1) {
    const month = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const ds = `${month.getFullYear()}${String(month.getMonth() + 1).padStart(2, "0")}01`;
    const url = ex === "o"
      ? `https://www.tpex.org.tw/www/zh-tw/afterTrading/tradingStock?code=${encodeURIComponent(code)}&date=${ds}&response=json`
      : `https://www.twse.com.tw/exchangeReport/STOCK_DAY?response=json&date=${ds}&stockNo=${encodeURIComponent(code)}`;
    try {
      const data = await fetchJSON(`${url}&_=${Date.now()}`, "歷史資料");
      const rows = data?.data || data?.tables?.[0]?.data || [];
      for (const row of rows) {
        const low = parseNum(row[5] ?? row[4]);
        const close = parseNum(row[6] ?? row[5]);
        if (Number.isFinite(low)) lows.push(low);
        if (Number.isFinite(close)) lows.push(close);
      }
    } catch (_) {}
  }
  return lows.length ? Math.min(...lows) : null;
}

function rocDateToISO(value) {
  const text = String(value || "").trim();
  if (/^\d{7}$/.test(text)) {
    const year = Number(text.slice(0, 3)) + 1911;
    return `${year}-${text.slice(3, 5)}-${text.slice(5, 7)}`;
  }
  const slash = text.match(/^(\d{2,3})\/(\d{1,2})\/(\d{1,2})$/);
  if (slash) {
    const year = Number(slash[1]) + 1911;
    return `${year}-${slash[2].padStart(2, "0")}-${slash[3].padStart(2, "0")}`;
  }
  return formatTWSEDate(text);
}

function recentMonthStarts(count = 6) {
  const now = new Date();
  return Array.from({ length: count }, (_, index) => new Date(now.getFullYear(), now.getMonth() - index, 1)).reverse();
}

async function asyncMapLimit(items, limit, mapper) {
  const source = Array.isArray(items) ? items : [];
  const results = new Array(source.length);
  let cursor = 0;
  const workers = Array.from({ length: Math.min(Math.max(1, Number(limit) || 1), source.length) }, async () => {
    while (cursor < source.length) {
      const index = cursor;
      cursor += 1;
      results[index] = await mapper(source[index], index);
    }
  });
  await Promise.all(workers);
  return results;
}

function monthKeyFromDate(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function isLocalRuntime() {
  return new Set(["localhost", "127.0.0.1", "::1", "[::1]"]).has(location.hostname);
}

function normalizeKLineRows(rows) {
  return rows
    .filter((row) => row && row.date && [row.open, row.high, row.low, row.close].every(Number.isFinite))
    .sort((a, b) => String(a.date).localeCompare(String(b.date)))
    .filter((row, index, arr) => index === 0 || row.date !== arr[index - 1].date);
}

function wait(ms = 0) {
  return new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}

async function fetchJSONRetry(url, label, options = {}, attempts = 2, retryDelayMs = 0) {
  let lastError = null;
  for (let i = 0; i < attempts; i += 1) {
    try {
      return await fetchJSON(`${url}${url.includes("?") ? "&" : "?"}_=${Date.now() + i}`, label, options);
    } catch (error) {
      lastError = error;
      if (i < attempts - 1 && retryDelayMs > 0) await wait(retryDelayMs * (i + 1));
    }
  }
  throw lastError || new Error(`${label} ????`);
}

async function fetchListedKLineHistory(code, months = 6) {
  const monthList = recentMonthStarts(months);
  const results = await asyncMapLimit(monthList, 6, async (month) => {
    const monthKey = monthKeyFromDate(month);
    const ds = `${month.getFullYear()}${String(month.getMonth() + 1).padStart(2, "0")}01`;
    const url = `https://www.twse.com.tw/exchangeReport/STOCK_DAY?response=json&date=${ds}&stockNo=${encodeURIComponent(code)}`;
    try {
      const data = await fetchJSONRetry(url, "TWSE 個股月歷史日行情", {}, 3);
      const monthRows = data?.data || [];
      return {
        status: { month: monthKey, status: monthRows.length ? "ok" : "empty", count: monthRows.length },
        rows: monthRows.map((row) => ({
          date: rocDateToISO(row[0]),
          volume: parseNum(row[1]),
          amount: parseNum(row[2]),
          open: parseNum(row[3]),
          high: parseNum(row[4]),
          low: parseNum(row[5]),
          close: parseNum(row[6]),
          change: parseNum(row[7]),
          transactions: parseNum(row[8]),
        })),
      };
    } catch (error) {
      return { status: { month: monthKey, status: "failed", count: 0, message: error.message }, rows: [] };
    }
  });
  const rows = results.flatMap((result) => result.rows);
  const monthStatus = results.map((result) => result.status);
  const normalizedRows = normalizeKLineRows(rows);
  const loadedMonths = new Set(normalizedRows.map((row) => String(row.date).slice(0, 7)));
  const missingMonths = monthStatus
    .filter((month) => month.status === "failed" || (month.status !== "empty" && !loadedMonths.has(month.month)))
    .map((month) => month.month);
  return {
    source: missingMonths.length
      ? `TWSE STOCK_DAY 官方月歷史日行情（缺少月份：${missingMonths.join("、")}）`
      : "TWSE STOCK_DAY 官方月歷史日行情",
    rows: normalizedRows,
    monthStatus,
    missingMonths,
  };
}

async function fetchOtcKLineHistory(code, months = 6) {
  const monthList = recentMonthStarts(months);
  const concurrency = months > 120 ? 1 : 2;
  const results = await asyncMapLimit(monthList, concurrency, async (month, index) => {
    if (index > 0) await wait(months > 120 ? 140 : 80);
    const monthKey = monthKeyFromDate(month);
    const ds = `${month.getFullYear()}/${String(month.getMonth() + 1).padStart(2, "0")}/01`;
    const url = `https://www.tpex.org.tw/www/zh-tw/afterTrading/tradingStock?code=${encodeURIComponent(code)}&date=${encodeURIComponent(ds)}&response=json`;
    try {
      const data = await fetchJSONRetry(url, "TPEx ????????", { timeoutMs: isLocalRuntime() ? 20000 : 12000 }, 5, months > 120 ? 300 : 150);
      const monthRows = data?.tables?.[0]?.data || [];
      return {
        status: { month: monthKey, status: monthRows.length ? "ok" : "empty", count: monthRows.length },
        rows: monthRows.map((row) => ({
          date: rocDateToISO(row[0]),
          volume: Number.isFinite(parseNum(row[1])) ? parseNum(row[1]) * 1000 : null,
          amount: Number.isFinite(parseNum(row[2])) ? parseNum(row[2]) * 1000 : null,
          open: parseNum(row[3]),
          high: parseNum(row[4]),
          low: parseNum(row[5]),
          close: parseNum(row[6]),
          change: parseNum(row[7]),
          transactions: parseNum(row[8]),
        })),
      };
    } catch (error) {
      return { status: { month: monthKey, status: "failed", count: 0, message: error.message }, rows: [] };
    }
  });
  const rows = results.flatMap((result) => result.rows);
  const monthStatus = results.map((result) => result.status);
  const normalizedRows = normalizeKLineRows(rows);
  const loadedMonths = new Set(normalizedRows.map((row) => String(row.date).slice(0, 7)));
  const missingMonths = monthStatus
    .filter((month) => month.status === "failed" || (month.status !== "empty" && !loadedMonths.has(month.month)))
    .map((month) => month.month);
  return {
    source: missingMonths.length
      ? `TPEx tradingStock ??????????????${missingMonths.join("?")}?`
      : "TPEx tradingStock ????????",
    rows: normalizedRows,
    monthStatus,
    missingMonths,
  };
}

function mergeKLineHistoryResults(primary, secondary) {
  const left = primary && typeof primary === "object" ? primary : {};
  const right = secondary && typeof secondary === "object" ? secondary : {};
  const rows = normalizeKLineRows([...(Array.isArray(left.rows) ? left.rows : []), ...(Array.isArray(right.rows) ? right.rows : [])]);
  const monthMap = new Map();
  [...(Array.isArray(left.monthStatus) ? left.monthStatus : []), ...(Array.isArray(right.monthStatus) ? right.monthStatus : [])].forEach((item) => {
    const key = String(item?.month || "").trim();
    if (!key) return;
    const current = monthMap.get(key);
    if (!current || current.status === "failed" || item.status === "ok") monthMap.set(key, item);
  });
  return {
    source: right.source || left.source || "",
    rows,
    monthStatus: Array.from(monthMap.values()).sort((a, b) => String(a.month || "").localeCompare(String(b.month || ""))),
    missingMonths: Array.from(new Set([...(Array.isArray(left.missingMonths) ? left.missingMonths : []), ...(Array.isArray(right.missingMonths) ? right.missingMonths : [])])).sort(),
  };
}

async function fetchStockKLineHistory(code, ex, months = 6) {
  let workerResult = null;
  try {
    const data = await fetchJSON(`/api/kline?code=${encodeURIComponent(code)}&ex=${encodeURIComponent(ex)}&months=${encodeURIComponent(months)}`, "本機歷史日 K 快取", { timeoutMs: 18000 });
    if (Array.isArray(data?.rows) && data.rows.length) {
      workerResult = {
        source: data.source || "本機資料庫歷史日 K 快取",
        rows: normalizeKLineRows(data.rows.map((row) => ({
          date: row.date,
          volume: parseNum(row.volume),
          amount: parseNum(row.amount),
          open: parseNum(row.open),
          high: parseNum(row.high),
          low: parseNum(row.low),
          close: parseNum(row.close),
          change: parseNum(row.change),
          transactions: parseNum(row.transactions),
        }))),
        monthStatus: data.monthStatus || [],
        missingMonths: data.missingMonths || [],
      };
    }
  } catch (_) {}

  const workerHasGaps = Boolean(workerResult?.missingMonths?.length)
    || Boolean((workerResult?.monthStatus || []).some((item) => item?.status === "failed"));
  if (workerResult?.rows?.length && !workerHasGaps) return workerResult;

  const result = ex === "o"
    ? await fetchOtcKLineHistory(code, months)
    : await fetchListedKLineHistory(code, months);
  if (result.rows.length) return workerResult?.rows?.length ? mergeKLineHistoryResults(workerResult, result) : result;
  if (workerResult?.rows?.length) return workerResult;

  const fallback = await fetchOpenAPIQuote(code, ex);
  return {
    source: `${fallback.priceType} 單日行情 fallback`,
    rows: normalizeKLineRows([{
      date: fallback.date || new Date().toLocaleDateString("sv-SE"),
      open: fallback.open,
      high: fallback.high,
      low: fallback.low,
      close: fallback.price,
      volume: null,
      amount: null,
      transactions: null,
    }]),
  };
}

async function fetchOpenAPIDailySupport(code, ex = "t") {
  try {
    const url = ex === "o"
      ? "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_quotes"
      : "https://openapi.twse.com.tw/v1/exchangeReport/STOCK_DAY_ALL";
    const data = await fetchJSON(url, ex === "o" ? "TPEx OpenAPI 上櫃行情" : "TWSE OpenAPI 日行情");
    const row = Array.isArray(data)
      ? data.find((item) => String(item.Code || item.SecuritiesCompanyCode) === code)
      : null;
    if (!row) return null;

    const low = parseNum(row.LowestPrice ?? row.Low);
    const close = parseNum(row.ClosingPrice ?? row.Close);
    const candidates = [low, close].filter(Number.isFinite);
    return candidates.length ? Math.min(...candidates) : null;
  } catch (_) {
    return null;
  }
}

async function fetchValuation(code, ex) {
  try {
    const url = ex === "o"
      ? "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_peratio_analysis"
      : "https://openapi.twse.com.tw/v1/exchangeReport/BWIBBU_d";
    const data = await fetchJSON(url, ex === "o" ? "TPEx 估值資料" : "TWSE 估值資料");
    const row = Array.isArray(data)
      ? data.find((item) => String(item.Code || item.SecuritiesCompanyCode) === code)
      : null;
    if (!row) return null;

    const pe = parseNum(row.PEratio ?? row.PriceEarningRatio);
    const pb = parseNum(row.PBratio ?? row.PriceBookRatio);
    const dividendYield = parseNum(row.DividendYield ?? row.YieldRatio);
    if (!Number.isFinite(pe) && !Number.isFinite(pb) && !Number.isFinite(dividendYield)) return null;

    return {
      date: formatTWSEDate(row.Date),
      pe,
      pb,
      dividendYield,
      fiscalYearQuarter: row.FiscalYearQuarter || "",
      dividendYear: row.DividendYear || "",
      note: ex === "o" ? "TPEx OpenAPI 上櫃股票個股本益比、殖利率及股價淨值比" : "TWSE OpenAPI 個股日本益比、殖利率及股價淨值比",
    };
  } catch (_) {
    return null;
  }
}

function dateKeyOffset(days = 0) {
  const date = new Date();
  date.setDate(date.getDate() - days);
  return `${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, "0")}${String(date.getDate()).padStart(2, "0")}`;
}

async function fetchLatestTwseInstitutionalRows() {
  for (let offset = 0; offset < 10; offset += 1) {
    const date = dateKeyOffset(offset);
    try {
      const url = `${STOCK_OFFICIAL_ENDPOINTS.listedInstitutional}?date=${date}&selectType=ALLBUT0999&response=json`;
      const data = await fetchJSON(url, "TWSE 三大法人買賣超", { timeoutMs: 15000 });
      if (data?.stat === "OK" && Array.isArray(data?.data) && Array.isArray(data?.fields)) return data;
    } catch (_) {}
  }
  return null;
}

function mapTwseTableRow(fields, row) {
  const mapped = {};
  (fields || []).forEach((field, index) => {
    mapped[field] = row?.[index];
  });
  return mapped;
}

function pickOfficialRow(rows, code, keys) {
  if (!Array.isArray(rows)) return null;
  return rows.find((row) => keys.some((key) => String(row?.[key] || "").trim().toUpperCase() === String(code).trim().toUpperCase())) || null;
}

function normalizeInstitutionalData(code, ex, sourceData) {
  if (ex === "o") {
    const row = pickOfficialRow(sourceData, code, ["SecuritiesCompanyCode"]);
    if (!row) return null;
    return {
      date: formatTWSEDate(row.Date),
      foreignDiff: pickNumber(row, [
        "ForeignInvestorsInclude MainlandAreaInvestors-Difference",
        "ForeignInvestorsIncludeMainlandAreaInvestors-Difference",
        "Foreign Investors include Mainland Area Investors (Foreign Dealers excluded)-Difference",
      ]),
      trustDiff: pickNumber(row, ["SecuritiesInvestmentTrustCompanies-Difference"]),
      dealerDiff: pickNumber(row, ["Dealers-Difference"]),
      totalDiff: pickNumber(row, ["TotalDifference"]),
      unit: "股",
      source: "TPEx OpenAPI 上櫃股票三大法人買賣明細資訊",
    };
  }
  const fields = sourceData?.fields || [];
  const raw = (sourceData?.data || []).find((item) => String(item?.[0] || "").trim().toUpperCase() === String(code).toUpperCase());
  if (!raw) return null;
  const row = mapTwseTableRow(fields, raw);
  return {
    date: formatTWSEDate(sourceData.date),
    foreignDiff: pickNumber(row, ["外陸資買賣超股數(不含外資自營商)"]),
    trustDiff: pickNumber(row, ["投信買賣超股數"]),
    dealerDiff: pickNumber(row, ["自營商買賣超股數"]),
    totalDiff: pickNumber(row, ["三大法人買賣超股數"]),
    unit: "股",
    source: "TWSE 官方三大法人買賣超日報",
  };
}

async function fetchInstitutionalTrading(code, ex) {
  try {
    if (ex === "o") {
      const rows = await fetchJSON(STOCK_OFFICIAL_ENDPOINTS.otcInstitutional, "TPEx 三大法人買賣明細");
      return normalizeInstitutionalData(code, ex, rows);
    }
    const data = await fetchLatestTwseInstitutionalRows();
    return normalizeInstitutionalData(code, ex, data);
  } catch (_) {
    return null;
  }
}

function normalizeInstitutionalRankingRowsForListed(sourceData) {
  const fields = sourceData?.fields || [];
  const date = formatTWSEDate(sourceData?.date);
  return (sourceData?.data || []).map((raw) => {
    const row = mapTwseTableRow(fields, raw);
    return {
      market: "listed",
      code: String(raw?.[0] || "").trim().toUpperCase(),
      name: String(raw?.[1] || "").trim(),
      date,
      foreignDiff: pickNumber(row, ["外陸資買賣超股數(不含外資自營商)"]),
      trustDiff: pickNumber(row, ["投信買賣超股數"]),
      dealerDiff: pickNumber(row, ["自營商買賣超股數"]),
      totalDiff: pickNumber(row, ["三大法人買賣超股數"]),
      source: "TWSE 官方三大法人買賣超日報",
    };
  }).filter((row) => row.code);
}

function normalizeInstitutionalRankingRowsForOtc(sourceRows) {
  return (sourceRows || []).map((row) => ({
    market: "otc",
    code: String(row?.SecuritiesCompanyCode || "").trim().toUpperCase(),
    name: String(row?.CompanyName || "").trim(),
    date: formatTWSEDate(row?.Date),
    foreignDiff: pickNumber(row, [
      "ForeignInvestorsInclude MainlandAreaInvestors-Difference",
      "ForeignInvestorsIncludeMainlandAreaInvestors-Difference",
      "Foreign Investors include Mainland Area Investors (Foreign Dealers excluded)-Difference",
    ]),
    trustDiff: pickNumber(row, ["SecuritiesInvestmentTrustCompanies-Difference"]),
    dealerDiff: pickNumber(row, ["Dealers-Difference"]),
    totalDiff: pickNumber(row, ["TotalDifference"]),
    source: "TPEx OpenAPI 上櫃股票三大法人買賣明細資訊",
  })).filter((row) => row.code);
}

async function loadInstitutionalRankingRows() {
  if (institutionalRankingsReady) return institutionalRankingsReady;
  institutionalRankingsReady = (async () => {
    const [listed, otc] = await Promise.allSettled([
      fetchLatestTwseInstitutionalRows(),
      fetchJSON(STOCK_OFFICIAL_ENDPOINTS.otcInstitutional, "TPEx 三大法人買賣明細", { timeoutMs: 15000 }),
    ]);
    return [
      ...normalizeInstitutionalRankingRowsForListed(listed.status === "fulfilled" ? listed.value : []),
      ...normalizeInstitutionalRankingRowsForOtc(otc.status === "fulfilled" ? otc.value : []),
    ];
  })().catch((error) => {
    institutionalRankingsReady = null;
    throw error;
  });
  return institutionalRankingsReady;
}

