      marginBalance: pickNumber(row, ["融資今日餘額"]),
      shortSell: pickNumber(row, ["融券賣出"]),
      shortCover: pickNumber(row, ["融券買進"]),
      shortBalance: pickNumber(row, ["融券今日餘額"]),
