function normalizeDividendRow(row, ex) {
  if (!row) return null;
  if (ex === "o") {
    return {
      date: formatTWSEDate(row.ExRrightsExDividendDate),
      type: row.ExRrightsExDividend || "",
      cashDividend: pickNumber(row, ["CashDividend"]),
      stockDividendRatio: pickNumber(row, ["StockDividendRatio"]),
      subscriptionPrice: pickNumber(row, ["SubscriptionPricePerShare"]),
      source: "TPEx OpenAPI 上櫃股票除權除息預告表",
    };
  }
  return {
    date: formatTWSEDate(row.Date),
    type: row.Exdividend || "",
    cashDividend: pickNumber(row, ["CashDividend"]),
    stockDividendRatio: pickNumber(row, ["StockDividendRatio"]),
    subscriptionPrice: pickNumber(row, ["SubscriptionPricePerShare"]),
    source: "TWSE OpenAPI 上市股票除權除息預告表",
  };
}

async function fetchDividendSchedule(code, ex, currentPrice) {
  try {
    const url = ex === "o" ? STOCK_OFFICIAL_ENDPOINTS.otcDividend : STOCK_OFFICIAL_ENDPOINTS.listedDividend;
    const rows = await fetchJSON(url, ex === "o" ? "TPEx 除權息預告" : "TWSE 除權息預告");
    const codeKeys = ex === "o" ? ["SecuritiesCompanyCode"] : ["Code"];
    const matches = (Array.isArray(rows) ? rows : []).filter((row) => codeKeys.some((key) => String(row?.[key] || "").trim().toUpperCase() === String(code).toUpperCase()));
    if (!matches.length) return null;
    const normalized = matches.map((row) => normalizeDividendRow(row, ex)).filter(Boolean)
      .sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
    const latest = normalized[0] || null;
    if (!latest) return null;
    const price = parseNum(currentPrice);
    latest.calculatedYield = Number.isFinite(latest.cashDividend) && Number.isFinite(price) && price > 0
      ? (latest.cashDividend / price) * 100
      : null;
    latest.yieldPrice = price;
    return latest;
  } catch (_) {
    return null;
  }
}

async function fetchPublicOffering(code) {
  try {
    const data = await fetchJSON(STOCK_OFFICIAL_ENDPOINTS.publicOffering, "TWSE 公開申購公告", { timeoutMs: 15000 });
    const fields = data?.fields || [];
    const rows = Array.isArray(data?.data) ? data.data.map((row) => mapTwseTableRow(fields, row)) : [];
    const row = rows.find((item) => String(item["證券代號"] || "").trim().toUpperCase() === String(code).toUpperCase());
    if (!row) return null;
    return {
      drawDate: formatTWSEDate(row["抽籤日期"]),
      name: row["證券名稱"] || "",
      market: row["發行市場"] || "",
      startDate: formatTWSEDate(row["申購開始日"]),
      endDate: formatTWSEDate(row["申購結束日"]),
      price: parseNum(row["承銷價(元)"] || row["實際承銷價(元)"]),
      shares: pickNumber(row, ["申購股數"]),
      winningRate: parseNum(row["中籤率(%)"]),
      status: row["取消公開抽籤 "] || "",
      source: "TWSE 官方公開申購公告-抽籤日程表",
    };
  } catch (_) {
    return null;
  }
}

async function fetchStockOfficialData(code, ex) {
  const [institutional, margin] = await Promise.all([
    fetchInstitutionalTrading(code, ex),
    fetchMarginBalance(code, ex),
  ]);
  return { institutional, margin };
}

async function fetchOpenAPIQuote(code, ex, options = {}) {
  const url = ex === "o"
    ? "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_quotes"
    : "https://openapi.twse.com.tw/v1/exchangeReport/STOCK_DAY_ALL";
  const data = await fetchJSON(url, ex === "o" ? "TPEx OpenAPI 上櫃行情" : "TWSE OpenAPI 日行情");
  const row = Array.isArray(data)
    ? data.find((item) => String(item.Code || item.SecuritiesCompanyCode) === code)
    : null;
  if (!row) throw new Error(`${ex === "o" ? "TPEx" : "TWSE"} OpenAPI 無此商品資料`);
  const price = parseNum(row.ClosingPrice ?? row.Close);
  if (!Number.isFinite(price)) throw new Error(`${ex === "o" ? "TPEx" : "TWSE"} OpenAPI 收盤價欄位為空`);
  return {
    code: String(row.Code || row.SecuritiesCompanyCode),
    name: row.Name || row.CompanyName || code,
    ex: ex === "o" ? "otc" : "tse",
    price,
    priceType: "OpenAPI 收盤",
    priceSource: "交易所 OpenAPI 收盤備援",
    open: options.includeOhlc === false ? null : parseNum(row.OpeningPrice ?? row.Open),
    high: options.includeOhlc === false ? null : parseNum(row.HighestPrice ?? row.High),
    low: options.includeOhlc === false ? null : parseNum(row.LowestPrice ?? row.Low),
    prevClose: null,
    date: formatTWSEDate(row.Date),
    time: "",
  };
}

async function fetchPrimaryStockQuote(code, ex) {
  const primaryEx = ex === "o" ? "o" : "t";
  const altEx = primaryEx === "t" ? "o" : "t";
  const errors = [];
  for (const candidateEx of [primaryEx, altEx]) {
    try {
      return applyLastTradeCache(await fetchTWSEPrice(code, candidateEx));
    } catch (error) {
      errors.push(error);
    }
  }
  throw new Error(`TWSE MIS 無法取得即時報價：${errors.map((error) => error.message).join("；")}`);
}

async function fetchQuote(code, ex) {
  try {
    return await fetchTWSEPrice(code, ex);
  } catch (error) {
    try {
      return await fetchOpenAPIQuote(code, ex);
    } catch (_) {
      throw error;
    }
  }
}

async function fetchMopsFinancialSupplement(code, ex) {
  const response = await fetch(apiURL(`/api/mops-financials?code=${encodeURIComponent(code)}&ex=${encodeURIComponent(ex)}`), { cache: "no-store" });
  const payload = await response.json().catch(() => null);
  if (!response.ok || !payload?.ok) {
    throw new Error(payload?.message || payload?.error || `MOPS HTTP ${response.status}`);
  }
  return payload;
}

async function fetchUnderlyingQuote(code, ex) {
  try {
    return await fetchOpenAPIQuote(code, ex);
  } catch (_) {
    return fetchQuote(code, ex);
  }
}

async function fetchUnderlyingQuoteByName(name) {
  const target = normalizeLookupName(name);
  if (!target) return null;
  const sources = [
    ["t", "https://openapi.twse.com.tw/v1/exchangeReport/STOCK_DAY_ALL", "TWSE OpenAPI 日行情"],
    ["o", "https://www.tpex.org.tw/openapi/v1/tpex_mainboard_quotes", "TPEx OpenAPI 上櫃行情"],
  ];
  for (const [ex, url, label] of sources) {
    try {
      const data = await fetchJSON(url, label);
      const row = Array.isArray(data)
        ? data.find((item) => normalizeLookupName(item.Name || item.CompanyName) === target)
          || data.find((item) => normalizeLookupName(item.Name || item.CompanyName).startsWith(target))
          || data.find((item) => normalizeLookupName(item.Name || item.CompanyName).includes(target))
        : null;
      if (!row) continue;
      const price = parseNum(row.ClosingPrice ?? row.Close);
      if (!Number.isFinite(price)) continue;
      return {
        code: String(row.Code || row.SecuritiesCompanyCode || ""),
        name: row.Name || row.CompanyName || name,
        ex: ex === "o" ? "otc" : "tse",
        price,
        priceType: "OpenAPI 收盤",
        date: formatTWSEDate(row.Date),
        time: "",
      };
    } catch (_) {}
  }
  return null;
}

