function buildStockPeerRows(report, peerContext) {
  const items = peerContext?.items || [];
  const quotes = peerContext?.quotes || new Map();
  const financialMap = peerContext?.financialMap || new Map();
  const valuationMap = peerContext?.valuationMap || new Map();
  const currentCode = String(report?.stock_code || "");
  const currentMarket = report?.companyProfile?.market?.includes("上櫃") || liveData?.ex === "otc" ? "otc" : "listed";
  const currentItem = items.find((item) => item.code === currentCode && (item.market === currentMarket || !items.some((entry) => entry.code === currentCode && entry.market === currentMarket)))
    || items.find((item) => item.code === currentCode)
    || null;
  const industryName = currentItem?.industryName || report?.companyProfile?.industry || "";
  if (!industryName) return { industryName: "", rows: [] };

  const peers = items
    .filter((item) => item.industryName === industryName && !isEtfItem(item))
    .map((item) => {
      const quote = quotes.get(quoteKey(item)) || null;
      const financial = financialMap.get(item.code) || {};
      const valuation = valuationMap.get(`${item.market}:${item.code}`) || {};
      const close = parseNum(quote?.close);
      const base = parseNum(financial.roeAdjustedBase);
      const discountPct = Number.isFinite(close) && Number.isFinite(base) && base !== 0
        ? round(((close - base) / base) * 100, 2)
        : null;
      const band = benchmarkBandInfo(base, close);
      const ranges = benchmarkRanges(base);
      return {
        code: item.code,
        name: item.name,
        market: item.market,
        close,
        pe: parseNum(valuation.pe),
        pb: parseNum(valuation.pb),
        roe: parseNum(financial.roe),
        base,
        discountPct,
        bandLabel: band?.label || "—",
        bandRange: renderBenchmarkRange(ranges[band?.key] || null),
        isCurrent: item.code === currentCode,
      };
    })
    .filter((row) => Number.isFinite(row.close) || row.isCurrent)
    .sort((a, b) => Number(b.isCurrent) - Number(a.isCurrent)
      || a.market.localeCompare(b.market)
      || a.code.localeCompare(b.code))
    .slice(0, 12);
  return { industryName, rows: peers };
}

function renderPeerComparisonCard(industryName, rows) {
  if (!rows.length) return "";
  const body = rows.map((row) => {
    const diffTone = Number(row.discountPct) <= 0 ? "up" : Number(row.discountPct) >= 30 ? "down" : "flat";
    const diffText = Number.isFinite(row.discountPct) ? `${row.discountPct > 0 ? "+" : ""}${row.discountPct.toFixed(2)}%` : "—";
    return `
      <tr class="market-quote-row ${row.isCurrent ? "peer-row-current" : ""}" data-stock-code="${htmlEscape(row.code)}">
        <td class="stock-name-cell"><b>${htmlEscape(row.name)}</b><span>${htmlEscape(row.code)} · ${row.market === "otc" ? "上櫃" : "上市"}${row.isCurrent ? " · 目前查詢" : ""}</span></td>
        <td data-label="股價">${renderMarketQuoteCell(row.close, 2)}</td>
        <td data-label="本益比">${renderMarketQuoteCell(row.pe, 2)}</td>
        <td data-label="股價淨值比">${renderMarketQuoteCell(row.pb, 2)}</td>
        <td data-label="ROE">${pct2(row.roe)}</td>
        <td data-label="基準值">${renderMarketQuoteCell(row.base, 2)}</td>
        <td data-label="基準差" class="${diffTone}">${diffText}</td>
        <td data-label="區間">${htmlEscape(row.bandLabel)}</td>
        <td data-label="區間股價">${htmlEscape(row.bandRange)}</td>
      </tr>
    `;
  }).join("");
  return `
    <section class="market-stock-panel">
      <div class="market-sector-head">
        <div>
          <div class="metric-tag">Peers</div>
          <h2>同業比較${industryName ? ` · ${htmlEscape(industryName)}` : ""}</h2>
        </div>
      </div>
      <div class="market-quote-table-wrap">
        <table class="market-quote-table peer-compare-table">
          <thead>
            <tr>
              <th>股票</th>
              <th>股價</th>
              <th>本益比</th>
              <th>股價淨值比</th>
              <th>ROE</th>
              <th>基準值</th>
              <th>基準差</th>
              <th>區間</th>
              <th>區間股價</th>
            </tr>
          </thead>
          <tbody>${body}</tbody>
        </table>
      </div>
    </section>
  `;
}

