function renderTerminalStat(label, value, tone = "") {
  return `<div class="terminal-stat"><span>${htmlEscape(label)}</span><b class="${tone}">${htmlEscape(value ?? "—")}</b></div>`;
}

function parseValuationLines(text) {
  const lines = String(text || "").split("；").map((line) => line.trim()).filter(Boolean);
  const find = (keyword) => {
    const value = lines.find((line) => line.includes(keyword));
    return value ? value.replace(keyword, "").trim() || "—" : "—";
  };
  return {
    pe: find("本益比"),
    pb: find("股價淨值比"),
    yieldText: find("殖利率"),
    extra: lines.filter((line) => !line.includes("本益比") && !line.includes("股價淨值比") && !line.includes("殖利率")),
  };
}

function renderStockTerminalSummary(report) {
  const s1 = report.section1;
  const s5 = report.section5 || {};
  const valuation = parseValuationLines(s1.pe_ratio);
  const benchmarkBase = s5.roeAdjustedBase ?? s5.adjustedBookValuePerShare ?? s5.bookValuePerShare;
  const benchmarkReady = Number.isFinite(Number(benchmarkBase)) && Number(benchmarkBase) > 0;
  const financialPeriod = report.financial_period || (s5.year && s5.quarter ? `${s5.year}Q${s5.quarter}` : "");
  const missingReasons = [
    financialPeriod ? null : "缺財務期間",
    Number.isFinite(Number(s5.bookValuePerShare)) && Number(s5.bookValuePerShare) > 0 ? null : "缺每股淨值",
    Number.isFinite(Number(s5.roe)) ? null : "缺最近四季 ROE",
  ].filter(Boolean);
  const completeness = benchmarkReady && !missingReasons.length
    ? `可計算 · ${financialPeriod}`
    : missingReasons.length ? `資料不足：${missingReasons.join("、")}` : `模型不適用 · ${financialPeriod}`;
  return `
    <section id="stock-summary" class="terminal-board compact-terminal-board" tabindex="-1">
      <div class="terminal-stat-grid">
        ${renderTerminalStat("資料日期", report.report_date || "—")}
        ${renderTerminalStat("價格基準值", completeness, benchmarkReady ? "up" : "")}
        ${renderTerminalStat("ROE", Number.isFinite(Number(s5.roe)) ? pct2(s5.roe) : "—", Number(s5.roe) >= 0.1 ? "up" : "")}
      </div>
      <div class="terminal-micro-grid">
        ${renderTerminalStat("本益比", valuation.pe)}
        ${renderTerminalStat("股價淨值比", valuation.pb)}
        ${renderTerminalStat("殖利率", valuation.yieldText)}
        ${renderTerminalStat("調整ROE", Number.isFinite(Number(s5.adjustedRoe)) ? pct2(s5.adjustedRoe) : "—", Number(s5.adjustedRoe) >= 0.1 ? "up" : "")}
      </div>
      <details class="stock-term-guide">
        <summary>這些數字怎麼看</summary>
        <p>本益比是股價相對每股盈餘的倍數；股價淨值比是股價相對每股淨值的倍數；殖利率是年度現金股利相對股價的比率。ROE 使用最近四季母公司淨利除以四季前股東權益，調整 ROE 再把其他權益納入分母；數值只供同期間比較，不代表適合買進。</p>
      </details>
    </section>
  `;
}

function renderStockMetricMatrix(report) {
  const s1 = report.section1;
  const s2 = report.section2;
  const s5 = report.section5 || {};
  const rows = [
    ["估值", "本益比", parseValuationLines(s1.pe_ratio).pe, ""],
    ["估值", "股價淨值比", parseValuationLines(s1.pe_ratio).pb, ""],
    ["估值", "殖利率", parseValuationLines(s1.pe_ratio).yieldText, ""],
    ["動能", "支撐", money(s2.P_support), "up"],
    ["動能", "目標", money(s2.P_target), "up"],
    ["動能", "動能幅度", `NT$${fixed(s2.momentum, 2)}`, Number(s2.momentum) >= 0 ? "up" : "down"],
    ["財務", "每股淨值", fixed(s5.bookValuePerShare, 2), ""],
    ["財務", "每股調整淨值", fixed(s5.adjustedBookValuePerShare, 2), ""],
    ["財務", "ROE調整基準值", fixed(s5.roeAdjustedBase, 2), ""],
  ];
  return `
    <section class="terminal-matrix">
      <div class="terminal-section-title">指標矩陣</div>
      <div class="terminal-matrix-table">
        ${rows.map(([group, label, value, tone]) => `
          <div class="terminal-matrix-row">
            <span>${htmlEscape(group)}</span>
            <b>${htmlEscape(label)}</b>
            <strong class="${tone}">${htmlEscape(value || "—")}</strong>
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function priceBandStatus(base, price) {
  const band = benchmarkBandInfo(base, price);
  if (!band) return null;
  return {
    ...band,
    tone: band.key === "outlier" ? "超出模型可判讀範圍，需人工確認" : `現價${band.label}`,
  };
}

function renderPriceBenchmarkCard(s5, currentPrice = liveData?.price) {
  const accent = UI_COLORS.warning;
  const financialPeriod = s5?.year && s5?.quarter ? `${s5.year}Q${s5.quarter}` : "";
  if (!financialPeriod) {
    return renderMetricCard("價格基準值", "估值區間", "資料不足，暫不判定", "缺少可辨識的財務資料期間", accent);
  }
  const base = s5?.roeAdjustedBase ?? s5?.adjustedBookValuePerShare ?? s5?.bookValuePerShare;
  if (!Number.isFinite(Number(base)) || Number(base) <= 0) {
    if (Number.isFinite(Number(s5?.bookValuePerShare)) && Number(s5.bookValuePerShare) > 0 && Number.isFinite(Number(s5?.roe))) {
      return renderMetricCard("價格基準值", "估值區間", "模型不適用，暫不判定", "ROE 或依公式計算的基準值非正", accent);
    }
    return renderMetricCard("價格基準值", "估值區間", "資料不足，暫不判定", "缺少有效的每股淨值或流通股數資料", accent);
  }
  const n = Number(base);
  const price = parseNum(currentPrice);
  if (!Number.isFinite(price) || price <= 0) {
    return renderMetricCard("價格基準值", "估值區間", "資料不足，暫不判定", "缺少有效行情價格", accent);
  }
  const status = priceBandStatus(n, price);
  const ranges = benchmarkRanges(n);
  const rows = [
    ["基準值", money(n)],
    ...BENCHMARK_BANDS.map((band) => [band.label, renderBenchmarkRange(ranges[band.key])]),
  ].map(([label, value]) => `<div class="benchmark-row ${status?.label === label ? "current" : ""}"><span>${htmlEscape(label)}</span><b>${htmlEscape(value)}</b></div>`).join("");

  return `
    <div class="metric-card benchmark-card" style="border-color:${accent}24">
      <div class="metric-tag" style="color:${accent};background:${accent}18">估值區間</div>
      <div class="metric-title">價格基準值</div>
      ${status ? `<div class="benchmark-status ${status.key === "outlier" ? "warning" : ""}">${htmlEscape(status.tone)} · 現價 ${money(price)}</div>` : ""}
      <div class="benchmark-list">${rows}</div>
      <p class="benchmark-definition">基準值依每股淨值與最近四季 ROE 計算；財務期間 ${htmlEscape(financialPeriod)}。它用來描述現價與財務基準的距離，不是目標價或買賣建議。</p>
      <p class="benchmark-note">基準值依每股淨值與最近四季 ROE 計算；基準差是現價相對基準值的距離。這是資料比較工具，不是目標價。</p>
    </div>
  `;
}

function movingAverageAt(rows, index, period) {
  if (index + 1 < period) return null;
  const slice = rows.slice(index + 1 - period, index + 1).map((row) => row.close).filter(Number.isFinite);
  return slice.length === period ? slice.reduce((sum, value) => sum + value, 0) / period : null;
}

function getTradingViewExchange(value) {
  const text = String(value || "").trim().toLowerCase();
  return text.startsWith("o") || text.includes("otc") || text.includes("tpex") || String(value || "").includes("上櫃")
    ? "TPEX"
    : "TWSE";
}

function buildTradingViewSymbol(report) {
  const code = String(report?.stock_code || "").trim().toUpperCase();
  if (!code) return "";
  const exchange = getTradingViewExchange(codeIndex.get(code)?.ex || liveData?.ex || report?.companyProfile?.market);
  return `${exchange}:${code}`;
}

function buildTradingViewSymbolUrl(symbol) {
  const [exchange, code] = String(symbol || "").split(":");
  if (!exchange || !code) return "https://www.tradingview.com/";
  return `https://www.tradingview.com/symbols/${encodeURIComponent(exchange)}-${encodeURIComponent(code)}/?utm_source=twetq.com&utm_medium=widget&utm_campaign=advanced-chart`;
}

const STOCK_KLINE_RANGE_OPTIONS = [
  { key: "6m", label: "6M" },
  { key: "ytd", label: "YTD" },
  { key: "1y", label: "1Y" },
  { key: "5y", label: "5Y" },
  { key: "all", label: "All" },
];
const STOCK_KLINE_TWSE_MIN_DATE = "2010-01-04";

function parseIsoDate(value) {
  const text = String(value || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return null;
  const [year, month, day] = text.split("-").map(Number);
  if (!year || !month || !day) return null;
  return new Date(Date.UTC(year, month - 1, day));
}

function formatIsoDate(value) {
  const date = value instanceof Date ? value : parseIsoDate(value);
  if (!date || Number.isNaN(date.getTime())) return "";
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}`;
}

function monthStartOffset(monthsAgo = 0) {
  const now = new Date();
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - monthsAgo, 1));
}

function maxIsoDate(a, b) {
  if (!a) return b || "";
  if (!b) return a || "";
  return a >= b ? a : b;
}

function monthsBetweenDates(startDateText, endDate = new Date()) {
  const start = parseIsoDate(startDateText);
  if (!start) return 0;
  const endYear = endDate.getUTCFullYear?.() ? endDate.getUTCFullYear() : endDate.getFullYear();
  const endMonth = endDate.getUTCMonth?.() ? endDate.getUTCMonth() : endDate.getMonth();
  return Math.max(1, (endYear - start.getUTCFullYear()) * 12 + (endMonth - start.getUTCMonth()) + 1);
}

function getStockKLineMarket(report) {
  const market = String(codeIndex.get(String(report?.stock_code || "").trim().toUpperCase())?.ex || liveData?.ex || report?.companyProfile?.market || "").trim().toLowerCase();
  return market.startsWith("o") || market.includes("otc") || market.includes("tpex") || market.includes("\u4e0a\u6ac3")
    ? "o"
    : "t";
}

function toLightweightKLineData(rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .filter((row) => row?.date && [row.open, row.high, row.low, row.close].every(Number.isFinite))
    .map((row) => ({
      time: row.date,
      open: Number(row.open),
      high: Number(row.high),
      low: Number(row.low),
      close: Number(row.close),
    }));
}

function renderStockKLineRangeButtons(activeKey = "6m") {
  return `
    <div class="kline-range-tabs" aria-label="\u6b77\u53f2\u65e5 K \u7dda\u5340\u9593">
      ${STOCK_KLINE_RANGE_OPTIONS.map((item) => `
        <button class="${item.key === activeKey ? "active" : ""}" type="button" data-kline-range-key="${item.key}" aria-pressed="${item.key === activeKey ? "true" : "false"}">${item.label}</button>
      `).join("")}
    </div>
  `;
}

function getStockKLineMinDate(report) {
  const listingDate = String(report?.companyProfile?.listingDate || "").trim();
  if (getStockKLineMarket(report) === "o") return listingDate;
  return maxIsoDate(listingDate, STOCK_KLINE_TWSE_MIN_DATE);
}

function getStockKLineRangeRequest(report, rangeKey = "6m") {
  const minDate = getStockKLineMinDate(report);
  const now = new Date();
  let startDate = "";
  if (rangeKey === "all") {
    startDate = minDate || formatIsoDate(monthStartOffset(59));
  } else if (rangeKey === "ytd") {
    startDate = formatIsoDate(new Date(Date.UTC(now.getUTCFullYear(), 0, 1)));
  } else if (rangeKey === "1y") {
    startDate = formatIsoDate(monthStartOffset(11));
  } else if (rangeKey === "5y") {
    startDate = formatIsoDate(monthStartOffset(59));
  } else {
    startDate = formatIsoDate(monthStartOffset(5));
  }
  const effectiveStartDate = maxIsoDate(startDate, minDate);
  return {
    key: rangeKey,
    startDate: effectiveStartDate,
    months: monthsBetweenDates(effectiveStartDate, now),
  };
}

function filterStockKLineRows(rows = [], startDate = "") {
  if (!startDate) return Array.isArray(rows) ? rows : [];
  return (Array.isArray(rows) ? rows : []).filter((row) => String(row?.date || "") >= startDate);
}

function syncStockKLineRangeButtons(card) {
  const activeKey = card?.dataset.klineRange || "6m";
  card?.querySelectorAll("[data-kline-range-key]").forEach((button) => {
    const active = button.dataset.klineRangeKey === activeKey;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function applyStockKLineRange(card, rangeKey = card?.dataset.klineRange || "6m") {
  if (!card?.__tradingViewSeries) return;
  const request = getStockKLineRangeRequest(card.__klineReport, rangeKey);
  const rows = filterStockKLineRows(card.__klineRowsRaw, request.startDate);
  const data = toLightweightKLineData(rows.length ? rows : card.__klineRowsRaw);
  card.dataset.klineRange = rangeKey;
  card.__tradingViewSeries.setData(data);
  card.__tradingViewChart?.timeScale().fitContent();
  syncStockKLineRangeButtons(card);
}

async function ensureStockKLineRangeLoaded(card, rangeKey = "6m") {
  if (!card?.__klineReport) return;
  const request = getStockKLineRangeRequest(card.__klineReport, rangeKey);
  const currentStartDate = String(card.__klineRowsRaw?.[0]?.date || "");
  if (request.startDate && currentStartDate && currentStartDate <= request.startDate) return;
  const loadKey = `${card.__klineReport.stock_code}:${getStockKLineMarket(card.__klineReport)}:${request.months}`;
  card.__klineLoads ||= new Map();
  if (!card.__klineLoads.has(loadKey)) {
    card.classList.add("kline-range-loading");
    card.__klineLoads.set(loadKey, fetchStockKLineHistory(card.__klineReport.stock_code, getStockKLineMarket(card.__klineReport), request.months)
      .then((data) => {
        card.__klineRowsRaw = normalizeKLineRows(data?.rows || card.__klineRowsRaw || []);
      })
      .finally(() => {
        card.classList.remove("kline-range-loading");
        card.__klineLoads.delete(loadKey);
      }));
  }
  await card.__klineLoads.get(loadKey);
}

function renderStockKLineChartCard(report) {
  const symbol = buildTradingViewSymbol(report);
  const symbolUrl = buildTradingViewSymbolUrl(symbol);
  return `
    <section class="kline-card tradingview-kline-card" data-tradingview-card data-tradingview-symbol="${htmlEscape(symbol)}" data-tradingview-name="${htmlEscape(report?.stock_name || "")}" data-kline-range="6m">
      <header class="tradingview-kline-head">
        <div>
          <div class="metric-tag">日 K 線</div>
          <h2>\u6b77\u53f2\u65e5 K \u7dda</h2>
        </div>
        <a class="tradingview-kline-link" href="${htmlEscape(symbolUrl)}" target="_blank" rel="noreferrer">\u5728 TradingView \u958b\u555f \u2197</a>
      </header>
      ${renderStockKLineRangeButtons("6m")}
      <div class="tradingview-kline-shell">
        <div class="lightweight-kline-chart" data-tradingview-widget></div>
      </div>
      <div class="lightweight-kline-attribution">TradingView Lightweight Charts&trade; <a href="https://www.tradingview.com/" target="_blank" rel="noreferrer">TradingView</a></div>
    </section>
  `;
}
function mountTradingViewKLine(root = document, report = lastStockReport) {
  const card = root?.querySelector("[data-tradingview-card]");
  const shell = card?.querySelector("[data-tradingview-widget]");
  if (!shell || card.__tradingViewReady) return;
  card.__tradingViewReady = true;
  card.__klineReport = report;
  card.__klineRowsRaw = normalizeKLineRows(report?.kline?.rows || []);
  const rows = toLightweightKLineData(card.__klineRowsRaw);
  const lib = window.LightweightCharts;
  if (!lib?.createChart || !rows.length) {
    shell.innerHTML = '<div class="kline-empty">\u6b77\u53f2\u65e5 K \u8cc7\u6599\u66ab\u6642\u7121\u6cd5\u986f\u793a\u3002</div>';
    return;
  }
  const formatter = new Intl.NumberFormat("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const chartSize = () => {
    const width = shell.clientWidth || window.innerWidth;
    return { width, height: shell.clientHeight || Math.round(width * 9 / 16) };
  };
  const initialSize = chartSize();
  const chart = lib.createChart(shell, {
    ...initialSize,
    layout: {
      background: { color: UI_COLORS.paper },
      textColor: UI_COLORS.ink,
      attributionLogo: false,
    },
    grid: {
      vertLines: { color: "rgba(32, 49, 61, 0.10)" },
      horzLines: { color: "rgba(32, 49, 61, 0.10)" },
    },
    rightPriceScale: {
      borderColor: "rgba(32, 49, 61, 0.20)",
    },
    timeScale: {
      borderColor: "rgba(32, 49, 61, 0.20)",
      timeVisible: false,
      fixLeftEdge: true,
      fixRightEdge: true,
    },
    crosshair: {
      vertLine: { color: "rgba(47, 113, 110, 0.30)" },
      horzLine: { color: "rgba(47, 113, 110, 0.22)" },
    },
    localization: {
      locale: "zh-TW",
      priceFormatter: (value) => formatter.format(value),
    },
  });
  const seriesOptions = {
    upColor: UI_COLORS.up,
    downColor: UI_COLORS.down,
    borderUpColor: UI_COLORS.up,
    borderDownColor: UI_COLORS.down,
    wickUpColor: UI_COLORS.up,
    wickDownColor: UI_COLORS.down,
  };
  const candleSeries = typeof chart.addSeries === "function" && lib.CandlestickSeries
    ? chart.addSeries(lib.CandlestickSeries, seriesOptions)
    : chart.addCandlestickSeries(seriesOptions);
  const resize = () => chart.applyOptions(chartSize());
  resize();
  if (typeof ResizeObserver !== "undefined") {
    const observer = new ResizeObserver(resize);
    observer.observe(shell);
    card.__tradingViewResizeObserver = observer;
  } else {
    window.addEventListener("resize", resize, { passive: true });
  }
  card.__tradingViewChart = chart;
  card.__tradingViewSeries = candleSeries;
  applyStockKLineRange(card, card.dataset.klineRange || "6m");
}

function renderDetailPanel(title, body, open = false) {
  return `
    <section class="detail-panel">
      <div class="detail-title">${htmlEscape(title)}</div>
      <div class="detail-body">${body}</div>
    </section>
  `;
}

function renderPageStrip(kicker, title, subtitle, tone = "neutral") {
  return `
    <section class="page-strip institutional-hero ${tone}">
      <div>
        <span class="institutional-kicker">${htmlEscape(kicker)}</span>
        <h1>${htmlEscape(title)}</h1>
        ${subtitle ? `<p>${htmlEscape(subtitle)}</p>` : ""}
      </div>
    </section>
  `;
}

function renderSectionNav(items, label = "本頁內容", className = "") {
  return `
    <nav class="section-nav ${htmlEscape(className)}" aria-label="${htmlEscape(label)}">
      <span>${htmlEscape(label)}</span>
      <div>${items.map(([id, text]) => `<a href="#${htmlEscape(id)}">${htmlEscape(text)}</a>`).join("")}</div>
    </nav>`;
}

function focusRenderedSection(id, message = "") {
  requestAnimationFrame(() => {
    const target = document.getElementById(id);
    if (!target) return;
    const disclosure = target.closest("details");
    if (disclosure) disclosure.open = true;
    target.focus({ preventScroll: true });
    target.scrollIntoView({ behavior: "smooth", block: "start" });
    const resultCount = target.querySelectorAll(".market-quote-row, .market-ranking-table tbody tr").length;
    const status = document.getElementById("researchResultStatus");
    if (status) status.textContent = message || `已顯示 ${resultCount.toLocaleString("zh-TW")} 檔`;
  });
}

