async function runHome() {
  setLoading(true);
  errorSlot.innerHTML = "";
  liveSlot.innerHTML = "";
  resultSlot.innerHTML = `<div class="panel-skeleton">讀取最新 Podcast...</div>`;
  try {
    const [latestResult, episodesResult] = await Promise.allSettled([
      loadPodcastLatest(false),
      loadPodcastEpisodes(),
    ]);
    if (currentMode !== "home") return;
    if (latestResult.status === "rejected" && episodesResult.status === "rejected") {
      throw latestResult.reason;
    }
    const latest = latestResult.status === "fulfilled" ? latestResult.value : null;
    const episodes = episodesResult.status === "fulfilled" ? podcastEpisodeRows(episodesResult.value) : [];
    renderHomePage(latest, episodes);
  } catch (error) {
    if (currentMode === "home") showRetryableLoadError("PODCAST 首頁資料", error);
  } finally {
    if (currentMode === "home") setLoading(false);
  }
}

