function renderLinkedText(value) {
  const text = String(value ?? "");
  const tokenPattern = /(https?:\/\/[^\s，。；、）)]+|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/gi;
  let html = "";
  let lastIndex = 0;
  text.replace(tokenPattern, (match, ...args) => {
    const offset = args.at(-2);
    html += htmlEscape(text.slice(lastIndex, offset));
    const isEmail = match.includes("@") && !match.startsWith("http");
    const href = isEmail ? `mailto:${match}` : match;
    html += `<a href="${htmlEscape(href)}">${htmlEscape(match)}</a>`;
    lastIndex = offset + match.length;
    return match;
  });
  return html + htmlEscape(text.slice(lastIndex));
}

