async function runPodcast(refresh = false) {
  setLoading(true);
  errorSlot.innerHTML = "";
  liveSlot.innerHTML = "";
  resultSlot.innerHTML = `<div class="panel-skeleton">讀取 PODCAST 資料...</div>`;
  const viewAtStart = podcastView;
  const epAtStart = podcastSearchEp;
  try {
    if (podcastView === "episodes") {
      const data = await loadPodcastEpisodes();
      if (currentMode === "podcast" && podcastView === viewAtStart) {
        renderPodcastEpisodesPage(data, podcastEpisodeRows(data));
      }
      return;
    }
    const data = await loadPodcastLatest(refresh, podcastSearchEp);
    if (currentMode !== "podcast" || podcastView !== viewAtStart || podcastSearchEp !== epAtStart) return;
    renderPodcastPage(data, data?.analysis?.stocks || [], data?.analysis?.industries || []);
    Promise.all([
      enrichPodcastStocks(data?.analysis?.stocks || []),
      enrichPodcastIndustries(data?.analysis?.industries || []),
    ])
      .then(([enrichedStocks, enrichedIndustries]) => {
        if (currentMode === "podcast" && podcastView === viewAtStart && podcastSearchEp === epAtStart) {
          renderPodcastPage(data, enrichedStocks, enrichedIndustries);
        }
      })
      .catch((error) => console.warn("Podcast quote enrichment failed", error));
  } catch (error) {
    if (currentMode === "podcast" && podcastView === viewAtStart) {
      showError(`無法取得 PODCAST 資料：${error.message}`);
    }
  } finally {
    if (currentMode === "podcast") setLoading(false);
  }
}

function renderMarketQuoteCell(value, digits = 2) {
  const n = parseNum(value);
  return Number.isFinite(n) ? n.toLocaleString("zh-TW", { minimumFractionDigits: digits, maximumFractionDigits: digits }) : "—";
}

const MARKET_CANVAS_SORT_COLUMNS = [
  ["code", "代號"],
  ["name", "公司名稱"],
  ["market", "市場"],
  ["industry", "產業"],
  ["close", "股價"],
  ["change", "漲跌"],
  ["changePct", "漲跌幅(%)"],
  ["volume", "成交量"],
  ["lots", "成交量(張)"],
  ["value", "成交金額(億)"],
];

function getMarketSortValue(stock, quote, key) {
  if (key === "code") return stock.code || "";
  if (key === "name") return stock.name || "";
  if (key === "market") return stock.market || "";
  if (key === "industry") return stock.industryName || "";
  if (key === "lots") return (parseNum(quote?.volume) || 0) / 1000;
  return quote?.[key];
}

function sortMarketStocks(stocks, quotes) {
  const key = marketState.sortKey;
  const dir = marketState.sortDir;
  if (!key || !dir) return stocks;
  const factor = dir === "asc" ? 1 : -1;
  return [...stocks].sort((a, b) => {
    const qa = quotes?.get(`${a.market}:${a.code}`);
    const qb = quotes?.get(`${b.market}:${b.code}`);
    const av = getMarketSortValue(a, qa, key);
    const bv = getMarketSortValue(b, qb, key);
    if (["stock", "code", "name", "market", "industry"].includes(key)) {
      return factor * String(av || "").localeCompare(String(bv || ""), "zh-Hant", { numeric: true });
    }
    const an = parseNum(av);
    const bn = parseNum(bv);
    const aMissing = !Number.isFinite(an);
    const bMissing = !Number.isFinite(bn);
    if (aMissing && bMissing) return a.code.localeCompare(b.code);
    if (aMissing) return 1;
    if (bMissing) return -1;
    return factor * (an - bn) || a.code.localeCompare(b.code);
  });
}

function renderMarketSortHeader(key, label) {
  const active = marketState.sortKey === key && marketState.sortDir;
  const icon = active ? (marketState.sortDir === "asc" ? "▲" : "▼") : "↕";
  const next = !active ? "正序" : marketState.sortDir === "asc" ? "倒序" : "預設";
  const current = active ? `目前${marketState.sortDir === "asc" ? "正序" : "倒序"}` : "目前未排序";
  return `<button class="market-sort-button ${active ? "active" : ""}" type="button" data-sort-key="${key}" title="點擊切換${label}${next}排序" aria-label="${label}，${current}；點擊切換為${next}排序"><span>${label}</span><b>${icon}</b>${active ? `<em>${marketState.sortDir === "asc" ? "正序" : "倒序"}</em>` : ""}</button>`;
}

function tablePageCount(total, pageSize = TABLE_PAGE_SIZE) {
  return Math.max(1, Math.ceil(Math.max(0, Number(total) || 0) / pageSize));
}

function clampTablePage(page, total, pageSize = TABLE_PAGE_SIZE) {
  return Math.min(tablePageCount(total, pageSize), Math.max(1, Number(page) || 1));
}

function renderMarketStockTable(stocks, quotes) {
  const pageSize = 5;
  const sortedStocks = sortMarketStocks(stocks, quotes);
  const page = clampTablePage(marketState.page, sortedStocks.length, pageSize);
  marketState.page = page;
  const pageStocks = sortedStocks.slice((page - 1) * pageSize, page * pageSize);
  const headerMap = new Map(MARKET_CANVAS_SORT_COLUMNS);
  const rows = pageStocks.map((stock) => {
    const quote = quotes?.get(`${stock.market}:${stock.code}`);
    const change = quote?.change;
    const changePct = quote?.changePct;
    const up = Number(change) > 0;
    const down = Number(change) < 0;
    const tone = up ? "up" : down ? "down" : "flat";
    const changeText = formatMoveQuote(change, 2);
    const pctText = formatMoveText(changePct, (n) => `${renderMarketQuoteCell(n, 2)}%`);
    const lots = Number.isFinite(parseNum(quote?.volume)) ? Math.round(parseNum(quote.volume) / 1000) : null;
    const valueYi = Number.isFinite(parseNum(quote?.value)) ? parseNum(quote.value) / 100000000 : null;
    return `
      <tr class="market-quote-row" data-stock-code="${htmlEscape(stock.code)}">
        <td data-label="代號"><a href="/stock/${encodeURIComponent(stock.code)}">${htmlEscape(stock.code)}</a></td>
        <td data-label="公司名稱"><a href="/stock/${encodeURIComponent(stock.code)}">${htmlEscape(stock.name)}</a></td>
        <td data-label="市場">${stock.market === "otc" ? "上櫃" : "上市"}</td>
        <td data-label="產業">${htmlEscape(stock.industryName || "未分類")}</td>
        <td data-label="股價">${renderMarketQuoteCell(quote?.close, 2)}</td>
        <td data-label="漲跌" class="${tone}">${changeText}</td>
        <td data-label="漲跌幅(%)" class="${tone}">${pctText}</td>
        <td data-label="成交量">${intText(quote?.volume)}</td>
        <td data-label="成交量(張)">${Number.isFinite(lots) ? lots.toLocaleString("zh-TW") : "—"}</td>
        <td data-label="成交金額(億)">${Number.isFinite(valueYi) ? valueYi.toLocaleString("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : "—"}</td>
      </tr>`;
  }).join("");
  return `
    <div class="paginated-table-region" data-table-region="market">
      <div class="market-quote-table-wrap paginated-table-wrap" tabindex="0" role="region" aria-label="個股清單，第 ${page} 頁，共 ${tablePageCount(sortedStocks.length, pageSize)} 頁">
        <table class="market-quote-table market-canvas-stock-table">
          <thead>
            <tr>
              ${[...headerMap.entries()].map(([key, label]) => `<th scope="col" aria-sort="${marketState.sortKey === key ? (marketState.sortDir === "asc" ? "ascending" : "descending") : "none"}">${renderMarketSortHeader(key, label)}</th>`).join("")}
            </tr>
          </thead>
          <tbody>${rows || `<tr><td colspan="10" class="market-empty-cell">此分類目前無個股</td></tr>`}</tbody>
        </table>
      </div>
      ${renderMarketCanvasPagination("market", "個股清單", sortedStocks.length, page, pageSize, `共 ${sortedStocks.length.toLocaleString("zh-TW")} 檔 · 每頁 ${pageSize} 筆`)}
    </div>
  `;
}

function rerenderMarketStockTableOnly() {
  const region = resultSlot.querySelector('[data-table-region="market"]');
  if (!region || !lastMarketRender) return false;
  region.outerHTML = renderMarketStockTable(lastMarketRender.visibleStocks, lastMarketRender.quotes);
  return true;
}

function formatShareCount(value) {
  const n = parseNum(value);
  return Number.isFinite(n) ? `${signedIntText(n)} 股` : "—";
}

function renderInstitutionalRankingList(title, rows, options = {}) {
  const limit = options.limit === null ? null : (Number.isFinite(options.limit) ? options.limit : 10);
  let displayRows = rows || [];
  if (options.sortByNetAmount) {
    displayRows = [...displayRows].sort((a, b) => b.amount - a.amount || a.stock.code.localeCompare(b.stock.code));
  }
  return renderMarketTableCard(
    title,
    displayRows,
    ["名次", "股票", "產業", "買賣超金額", "買賣超股數"],
    (item, index) => {
      const amountTone = marketMoveClass(item.amount);
      return `
        <tr data-ranking-amount="${htmlEscape(item.amount)}">
          <td class="market-table-rank">${index}</td>
          <td class="market-table-stock-cell"><button class="market-ranking-trigger" type="button" data-stock-code="${htmlEscape(item.stock.code)}"><b>${htmlEscape(item.stock.name)}</b><span>${htmlEscape(item.stock.code)}</span></button></td>
          <td>${htmlEscape(item.stock.industryName || "未分類")}</td>
          <td class="${amountTone}"><strong>${formatAmountYi(item.amount, true)}</strong></td>
          <td class="${amountTone}"><strong>${formatShareCount(item.totalDiff)}</strong></td>
        </tr>
      `;
    },
    (item, index) => {
      const amountTone = marketMoveClass(item.amount);
      return `
        <li class="market-mobile-rank-item" data-ranking-amount="${htmlEscape(item.amount)}">
          <span class="market-mobile-rank-number" aria-label="第 ${index} 名">${index}</span>
          <button class="market-mobile-stock market-ranking-trigger" type="button" data-stock-code="${htmlEscape(item.stock.code)}"><b>${htmlEscape(item.stock.name)}</b><span>${htmlEscape(item.stock.code)}</span></button>
          <strong class="market-mobile-primary ${amountTone}">${formatAmountYi(item.amount, true)}</strong>
          <dl class="market-mobile-details">
            <div><dt>產業</dt><dd>${htmlEscape(item.stock.industryName || "未分類")}</dd></div>
            <div><dt>買賣超股數</dt><dd class="${amountTone}">${formatShareCount(item.totalDiff)}</dd></div>
          </dl>
        </li>
      `;
    },
    { limit, direction: title.includes("賣") ? "sell" : "buy", scrollRows: options.scrollRows, tableVariant: "flow" },
  );
}

function renderMarketTableCard(title, rows, headers, rowRenderer, mobileRenderer, options = {}) {
  const limit = options.limit === null ? null : (Number.isFinite(options.limit) ? options.limit : 10);
  const topRows = Number.isFinite(limit) ? (rows || []).slice(0, limit) : (rows || []);
  const body = topRows.map((item, index) => rowRenderer(item, index + 1)).join("");
  const mobileBody = topRows.map((item, index) => mobileRenderer(item, index + 1)).join("");
  const direction = options.direction === "sell" ? "sell" : options.direction === "buy" ? "buy" : "neutral";
  const tableVariant = ["flow", "sector"].includes(options.tableVariant) ? options.tableVariant : "flow";
  const scrollRows = Number(options.scrollRows) === 10 ? 10 : 0;
  const scrollClass = scrollRows ? " market-table-card-scroll-10" : "";
  const tableScrollAttrs = scrollRows
    ? ` tabindex="0" role="region" aria-label="${htmlEscape(title)}，預設顯示十列，可上下捲動"`
    : "";
  const mobileScrollAttrs = scrollRows
    ? ` tabindex="0" aria-label="${htmlEscape(title)}，預設顯示十列，可上下捲動"`
    : ` aria-label="${htmlEscape(title)}"`;
  return `
    <article class="market-ranking-card market-ranking-card-expanded market-table-card${scrollClass}">
      <header><span class="institutional-direction-dot ${direction}"></span><h3>${htmlEscape(title)}</h3></header>
      <div class="market-ranking-table-wrap"${tableScrollAttrs}>
        <table class="market-ranking-table market-ranking-table-${tableVariant}">
          <thead><tr>${headers.map((header) => `<th>${htmlEscape(header)}</th>`).join("")}</tr></thead>
          <tbody>${body || `<tr><td colspan="${headers.length}" class="market-ranking-empty">目前沒有可排序資料</td></tr>`}</tbody>
        </table>
      </div>
      <ol class="market-mobile-ranking-list"${mobileScrollAttrs}>
        ${mobileBody || '<li class="market-ranking-empty">目前沒有可排序資料</li>'}
      </ol>
    </article>
  `;
}

function buildInstitutionalRankingRows(items, quotes, institutionalRows) {
  const stockMap = new Map((items || []).map((item) => [`${item.market}:${item.code}`, item]));
  return (institutionalRows || [])
    .map((row) => {
      const stock = stockMap.get(`${row.market}:${row.code}`);
      const quote = quotes?.get(`${row.market}:${row.code}`) || null;
      const close = parseNum(quote?.close);
      const totalDiff = parseNum(row.totalDiff);
      if (!stock || !quote || !Number.isFinite(close) || !Number.isFinite(totalDiff)) return null;
      return {
        ...row,
        stock,
        quote,
        close,
        totalDiff,
        amount: close * totalDiff,
      };
    })
    .filter(Boolean)
    .filter((item) => !isEtfItem(item.stock));
}

function buildInstitutionalSectorRankingRows(rows) {
  const sectorMap = new Map();
  for (const row of rows || []) {
    const name = String(row?.stock?.industryName || "未分類").trim() || "未分類";
    const current = sectorMap.get(name) || {
      name,
      amount: 0,
      foreignAmount: 0,
      trustAmount: 0,
      dealerAmount: 0,
      totalDiff: 0,
      count: 0,
    };
    current.amount += parseNum(row.amount) || 0;
    current.foreignAmount += (parseNum(row.close) || 0) * (parseNum(row.foreignDiff) || 0);
    current.trustAmount += (parseNum(row.close) || 0) * (parseNum(row.trustDiff) || 0);
    current.dealerAmount += (parseNum(row.close) || 0) * (parseNum(row.dealerDiff) || 0);
    current.totalDiff += parseNum(row.totalDiff) || 0;
    current.count += 1;
    sectorMap.set(name, current);
  }
  return Array.from(sectorMap.values()).sort((a, b) => b.amount - a.amount || a.name.localeCompare(b.name, "zh-Hant"));
}

function marketCanvasPaginationItems(page, pages) {
  if (pages <= 7) return Array.from({ length: pages }, (_, index) => index + 1);
  const visible = [...new Set([1, 2, page - 1, page, page + 1, pages])]
    .filter((item) => item >= 1 && item <= pages)
    .sort((a, b) => a - b);
  const items = [];
  visible.forEach((item, index) => {
    if (index && item - visible[index - 1] > 1) items.push("ellipsis");
    items.push(item);
  });
  return items;
}

function renderMarketCanvasPagination(scope, label, total, page, pageSize, countLabel) {
  const pages = tablePageCount(total, pageSize);
  const items = marketCanvasPaginationItems(page, pages);
  return `
    <nav class="market-canvas-pagination" aria-label="${htmlEscape(label)}分頁">
      <span class="market-canvas-pagination-count">${htmlEscape(countLabel || `共 ${Number(total).toLocaleString("zh-TW")} 筆 · 每頁 ${pageSize} 筆`)}</span>
      <div class="market-canvas-pagination-pages">
        <button type="button" aria-label="${htmlEscape(label)}上一頁" data-market-canvas-page-scope="${scope}" data-market-canvas-page="${page - 1}" ${page <= 1 ? "disabled" : ""}>‹</button>
        ${items.map((item) => item === "ellipsis"
          ? '<span aria-hidden="true">…</span>'
          : `<button type="button" class="${item === page ? "active" : ""}" aria-current="${item === page ? "page" : "false"}" data-market-canvas-page-scope="${scope}" data-market-canvas-page="${item}">${item}</button>`).join("")}
        <button type="button" aria-label="${htmlEscape(label)}下一頁" data-market-canvas-page-scope="${scope}" data-market-canvas-page="${page + 1}" ${page >= pages ? "disabled" : ""}>›</button>
      </div>
    </nav>`;
}

function buildMarketCanvasSectorRows(items, quotes, institutionalRows) {
  const stocks = marketFilterItems(items, marketState.market).filter((item) => !isEtfItem(item));
  const moveRows = calcSectorMoves(stocks, quotes);
  const flowRows = buildInstitutionalSectorRankingRows(buildInstitutionalRankingRows(stocks, quotes, institutionalRows));
  const flowByName = new Map(flowRows.map((row) => [row.name, row]));
  return moveRows.map((move) => ({
    ...move,
    ...(flowByName.get(move.name) || {}),
    count: move.count,
    avgPct: move.avgPct,
    foreignAmount: flowByName.get(move.name)?.foreignAmount || 0,
    trustAmount: flowByName.get(move.name)?.trustAmount || 0,
    dealerAmount: flowByName.get(move.name)?.dealerAmount || 0,
    amount: flowByName.get(move.name)?.amount || 0,
  }));
}

function sortMarketCanvasSectorRows(rows) {
  const sorted = [...rows];
  if (marketCanvasState.sectorTab === "move") {
    return sorted.sort((a, b) => (parseNum(b.avgPct) || 0) - (parseNum(a.avgPct) || 0) || a.name.localeCompare(b.name, "zh-Hant"));
  }
  return sorted.sort((a, b) => (parseNum(b.amount) || 0) - (parseNum(a.amount) || 0) || a.name.localeCompare(b.name, "zh-Hant"));
}

function renderMarketCanvasSectorCard(rows) {
  const page = clampTablePage(marketCanvasState.sectorPage, rows.length, MARKET_CANVAS_PAGE_SIZE);
  marketCanvasState.sectorPage = page;
  const start = (page - 1) * MARKET_CANVAS_PAGE_SIZE;
  const pageRows = rows.slice(start, start + MARKET_CANVAS_PAGE_SIZE);
  const body = pageRows.map((row, index) => {
    const active = row.name === rankingState.industry;
    const cells = [row.foreignAmount, row.trustAmount, row.dealerAmount, row.amount];
    return `
      <tr class="market-canvas-sector-row ${active ? "active" : ""}" data-rank-industry="${htmlEscape(row.name)}">
        <td>${start + index + 1}</td>
        <td><button type="button" aria-pressed="${active}">${htmlEscape(row.name)}</button></td>
        <td class="${marketMoveClass(row.avgPct)}">${formatMovePercent(row.avgPct, 2)}</td>
        ${cells.map((value) => `<td class="${marketMoveClass(value)}">${formatAmountYi(value, true)}</td>`).join("")}
      </tr>`;
  }).join("");
  return `
    <article class="market-canvas-research-card market-canvas-sector-card">
      <h2>類股</h2>
      <div class="market-canvas-sector-tabs" role="tablist" aria-label="類股排行模式">
        <button type="button" role="tab" aria-selected="${marketCanvasState.sectorTab === "move"}" class="${marketCanvasState.sectorTab === "move" ? "active" : ""}" data-market-sector-tab="move">類股漲跌排行</button>
        <button type="button" role="tab" aria-selected="${marketCanvasState.sectorTab === "flow"}" class="${marketCanvasState.sectorTab === "flow" ? "active" : ""}" data-market-sector-tab="flow">類股淨買賣超排行</button>
      </div>
      <div class="market-canvas-table-wrap" tabindex="0" role="region" aria-label="類股排行，第 ${page} 頁">
        <table class="market-canvas-data-table market-canvas-sector-table">
          <thead><tr><th>排名</th><th>類股</th><th>漲跌幅</th><th>外資</th><th>投信</th><th>自營商</th><th>合計</th></tr></thead>
          <tbody>${body || '<tr><td colspan="7">目前沒有類股資料</td></tr>'}</tbody>
        </table>
      </div>
      ${renderMarketCanvasPagination("sector", "類股排行", rows.length, page, MARKET_CANVAS_PAGE_SIZE, `共 ${rows.length.toLocaleString("zh-TW")} 個類股 · 每頁 ${MARKET_CANVAS_PAGE_SIZE} 筆`)}
    </article>`;
}

function renderMarketCanvasConcentration(items, quotes) {
  const stats = calcGroupFlowStats(items, quotes);
  const rows = stats.rankedStocks.filter((item) => Number.isFinite(item.value) && item.value > 0).slice(0, 10);
  return `
    <article class="market-canvas-research-card market-canvas-concentration-card">
      <h2>資金集中個股 Top 10</h2>
      <div class="market-canvas-table-wrap" tabindex="0" role="region" aria-label="資金集中個股前十名">
        <table class="market-canvas-data-table">
          <thead><tr><th>排名</th><th>代號</th><th>個股</th><th>集中度</th><th>成交量</th></tr></thead>
          <tbody>${rows.map((item, index) => {
            const share = stats.tradeValue > 0 ? item.value / stats.tradeValue : null;
            return `<tr data-stock-code="${htmlEscape(item.stock.code)}"><td>${index + 1}</td><td>${htmlEscape(item.stock.code)}</td><td><a href="/stock/${encodeURIComponent(item.stock.code)}">${htmlEscape(item.stock.name)}</a></td><td>${Number.isFinite(share) ? `${(share * 100).toLocaleString("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%` : "—"}</td><td>${intText(item.quote?.volume)}</td></tr>`;
          }).join("") || '<tr><td colspan="5">目前沒有成交資料</td></tr>'}</tbody>
        </table>
      </div>
    </article>`;
}

function renderMarketCanvasSectorDetail(sectorName, institutionalRows, dataDate) {
  const sectorRows = institutionalRows.filter((item) => String(item.stock?.industryName || "未分類").trim() === sectorName);
  const sortedRows = [...sectorRows].sort((a, b) => marketCanvasState.detailSort === "sell"
    ? a.amount - b.amount || a.stock.code.localeCompare(b.stock.code)
    : b.amount - a.amount || a.stock.code.localeCompare(b.stock.code));
  const page = clampTablePage(marketCanvasState.detailPage, sortedRows.length, MARKET_CANVAS_PAGE_SIZE);
  marketCanvasState.detailPage = page;
  const start = (page - 1) * MARKET_CANVAS_PAGE_SIZE;
  const pageRows = sortedRows.slice(start, start + MARKET_CANVAS_PAGE_SIZE);
  const totalAbsoluteAmount = sectorRows.reduce((sum, item) => sum + Math.abs(parseNum(item.amount) || 0), 0);
  return `
    <article id="market-sector-detail" class="market-canvas-research-card market-canvas-sector-detail" tabindex="-1">
      <header>
        <div><h2>類股淨買賣超明細</h2><p>目前類股：<b>${htmlEscape(sectorName || "尚未選擇")}</b><span>資料日期：${htmlEscape(dataDate)}</span></p></div>
        <div class="market-canvas-detail-sort" role="group" aria-label="明細排序">
          <button type="button" class="${marketCanvasState.detailSort === "buy" ? "active" : ""}" data-market-detail-sort="buy">買超排序</button>
          <button type="button" class="${marketCanvasState.detailSort === "sell" ? "active" : ""}" data-market-detail-sort="sell">賣超排序</button>
        </div>
      </header>
      <div class="market-canvas-table-wrap" tabindex="0" role="region" aria-label="${htmlEscape(sectorName)}類股淨買賣超明細，第 ${page} 頁">
        <table class="market-canvas-data-table market-canvas-detail-table">
          <thead><tr><th>排名</th><th>代號</th><th>個股</th><th>外資</th><th>投信</th><th>自營商</th><th>三大法人合計</th><th>成交量</th><th>占類股比重</th></tr></thead>
          <tbody>${pageRows.map((item, index) => {
            const foreign = (parseNum(item.close) || 0) * (parseNum(item.foreignDiff) || 0);
            const trust = (parseNum(item.close) || 0) * (parseNum(item.trustDiff) || 0);
            const dealer = (parseNum(item.close) || 0) * (parseNum(item.dealerDiff) || 0);
            const share = totalAbsoluteAmount > 0 ? Math.abs(item.amount) / totalAbsoluteAmount : null;
            return `<tr data-stock-code="${htmlEscape(item.stock.code)}"><td>${start + index + 1}</td><td>${htmlEscape(item.stock.code)}</td><td><a href="/stock/${encodeURIComponent(item.stock.code)}">${htmlEscape(item.stock.name)}</a></td>${[foreign, trust, dealer, item.amount].map((value) => `<td class="${marketMoveClass(value)}">${formatAmountYi(value, true)}</td>`).join("")}<td>${intText(item.quote?.volume)}</td><td>${Number.isFinite(share) ? `${(share * 100).toLocaleString("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%` : "—"}</td></tr>`;
          }).join("") || '<tr><td colspan="9">此類股目前沒有法人明細資料</td></tr>'}</tbody>
        </table>
      </div>
      ${renderMarketCanvasPagination("sector-detail", `${sectorName}類股淨買賣超明細`, sortedRows.length, page, MARKET_CANVAS_PAGE_SIZE, `${sectorName || "目前類股"}共 ${sortedRows.length.toLocaleString("zh-TW")} 檔 · 每頁 ${MARKET_CANVAS_PAGE_SIZE} 筆`)}
    </article>`;
}

function renderMarketCanvasResearchSections(items, quotes, institutionalRows) {
  const stocks = marketFilterItems(items, marketState.market).filter((item) => !isEtfItem(item));
  const sectorRows = sortMarketCanvasSectorRows(buildMarketCanvasSectorRows(items, quotes, institutionalRows));
  if (!sectorRows.some((row) => row.name === rankingState.industry)) rankingState.industry = sectorRows[0]?.name || "";
  const rankedStocks = buildInstitutionalRankingRows(stocks, quotes, institutionalRows);
  const dataDate = institutionalRows?.find((row) => row?.date)?.date || "官方資料未提供";
  return `
    <section id="rank-sectors" class="market-canvas-research" tabindex="-1">
      <div class="market-canvas-research-grid">
        ${renderMarketCanvasSectorCard(sectorRows)}
        ${renderMarketCanvasConcentration(stocks, quotes)}
      </div>
      ${renderMarketCanvasSectorDetail(rankingState.industry, rankedStocks, dataDate)}
    </section>`;
}

function getMarketCanvasResearchContext() {
  if (!lastMarketRender) return null;
  const { items, quotes, institutionalRows = [] } = lastMarketRender;
  const stocks = marketFilterItems(items, marketState.market).filter((item) => !isEtfItem(item));
  const sectorRows = sortMarketCanvasSectorRows(buildMarketCanvasSectorRows(items, quotes, institutionalRows));
  if (!sectorRows.some((row) => row.name === rankingState.industry)) rankingState.industry = sectorRows[0]?.name || "";
  return {
    stocks,
    sectorRows,
    rankedStocks: buildInstitutionalRankingRows(stocks, quotes, institutionalRows),
    dataDate: institutionalRows.find((row) => row?.date)?.date || "官方資料未提供",
  };
}

function rerenderMarketCanvasResearchParts({ sector = false, detail = false } = {}) {
  const context = getMarketCanvasResearchContext();
  const sectorCard = sector ? resultSlot.querySelector(".market-canvas-sector-card") : null;
  const detailCard = detail ? resultSlot.querySelector(".market-canvas-sector-detail") : null;
  if (!context || (sector && !sectorCard) || (detail && !detailCard)) return false;
  if (sector) sectorCard.outerHTML = renderMarketCanvasSectorCard(context.sectorRows);
  if (detail) detailCard.outerHTML = renderMarketCanvasSectorDetail(rankingState.industry, context.rankedStocks, context.dataDate);
  return true;
}

function focusMarketCanvasControl(selector) {
  requestAnimationFrame(() => resultSlot.querySelector(selector)?.focus({ preventScroll: true }));
}

function refreshMarketCanvasParts(parts, focusSelector, preserveScroll = false) {
  const scrollPosition = preserveScroll ? { x: scrollX, y: scrollY } : null;
  const previousOverflowAnchor = preserveScroll ? document.documentElement.style.overflowAnchor : "";
  if (preserveScroll) document.documentElement.style.overflowAnchor = "none";
  const ready = rerenderMarketCanvasResearchParts(parts) ? Promise.resolve() : runMarket({ silent: true });
  ready.then(() => {
    if (!scrollPosition) return focusMarketCanvasControl(focusSelector);
    window.scrollTo(scrollPosition.x, scrollPosition.y);
    requestAnimationFrame(() => {
      window.scrollTo(scrollPosition.x, scrollPosition.y);
      focusMarketCanvasControl(focusSelector);
      requestAnimationFrame(() => {
        document.documentElement.style.overflowAnchor = previousOverflowAnchor;
      });
    });
  });
}

function renderInstitutionalSectorRankingList(title, rows) {
  return renderMarketTableCard(
    title,
    rows,
    ["名次", "類股", "成分股", "買賣超金額", "買賣超股數"],
    (item, index) => {
      const tone = marketMoveClass(item.amount);
      return `
        <tr class="market-sector-ranking-row ${rankingState.industry === item.name ? "active" : ""}" data-ranking-amount="${htmlEscape(item.amount)}">
          <td class="market-table-rank">${index}</td>
          <td class="market-table-stock-cell"><button class="market-ranking-trigger" type="button" data-rank-industry="${htmlEscape(item.name)}" aria-pressed="${rankingState.industry === item.name}"><b>${htmlEscape(item.name)}</b></button></td>
          <td>${item.count.toLocaleString("zh-TW")} 檔</td>
          <td class="${tone}"><strong>${formatAmountYi(item.amount, true)}</strong></td>
          <td class="${tone}"><strong>${formatShareCount(item.totalDiff)}</strong></td>
        </tr>
      `;
    },
    (item, index) => {
      const tone = marketMoveClass(item.amount);
      return `
        <li class="market-mobile-rank-item market-sector-ranking-row ${rankingState.industry === item.name ? "active" : ""}" data-ranking-amount="${htmlEscape(item.amount)}">
          <span class="market-mobile-rank-number" aria-label="第 ${index} 名">${index}</span>
          <button class="market-mobile-stock market-ranking-trigger" type="button" data-rank-industry="${htmlEscape(item.name)}" aria-pressed="${rankingState.industry === item.name}"><b>${htmlEscape(item.name)}</b><span>${item.count.toLocaleString("zh-TW")} 檔成分股</span></button>
          <strong class="market-mobile-primary ${tone}">${formatAmountYi(item.amount, true)}</strong>
          <dl class="market-mobile-details">
            <div><dt>成分股</dt><dd>${item.count.toLocaleString("zh-TW")} 檔</dd></div>
            <div><dt>買賣超股數</dt><dd class="${tone}">${formatShareCount(item.totalDiff)}</dd></div>
          </dl>
        </li>
      `;
    },
    { limit: null, scrollRows: 10, tableVariant: "sector" },
  );
}

function renderInstitutionalMarketRankingSection(items, quotes, institutionalRows) {
  const filtered = marketFilterItems(items, rankingState.market);
  const instantRows = filtered
    .map((stock) => ({ stock, quote: quotes?.get(`${stock.market}:${stock.code}`) || null }))
    .filter((item) => item.quote && !isEtfItem(item.stock));
  const institutionalRanked = buildInstitutionalRankingRows(filtered, quotes, institutionalRows);
  const netBuy = institutionalRanked
    .filter((item) => item.amount > 0)
    .sort((a, b) => b.amount - a.amount)
    .slice(0, 10);
  const netSell = institutionalRanked
    .filter((item) => item.amount < 0)
    .sort((a, b) => a.amount - b.amount)
    .slice(0, 10);
  const sampleInstitutionalDate = institutionalRows?.find((row) => row?.date)?.date || "官方資料未提供";
  const quoteDate = instantRows.map((item) => String(item.quote?.date || "")).filter(Boolean).sort().at(-1) || "官方資料未提供";
  const institutionalIsOlder = /^\d/.test(sampleInstitutionalDate)
    && sampleInstitutionalDate.replace(/\D/g, "") < quoteDate.replace(/\D/g, "");
  const rankingCount = (market) => marketFilterItems(items, market)
    .filter((stock) => !isEtfItem(stock) && quotes?.has(`${stock.market}:${stock.code}`)).length;
  const marketButtons = [
    ["all", "上市櫃", rankingCount("all")],
    ["listed", "上市", rankingCount("listed")],
    ["otc", "上櫃", rankingCount("otc")],
  ].map(([key, label, count]) => `<button class="market-tab rank-market-tab ${rankingState.market === key ? "active" : ""}" type="button" data-rank-market="${key}">${label}<span>${Number(count).toLocaleString("zh-TW")}</span></button>`).join("");

  return `
    <section id="market-rankings" class="market-layer market-layer-browser institutional-section market-radar-section" tabindex="-1">
      <header class="institutional-section-head">
        <div><span class="institutional-kicker">DAILY FLOW</span><h2>三大法人排行</h2></div>
        <p>${htmlEscape(quoteDate)} 收盤價；一般股票不含 ETF，法人買超與賣超排行各顯示前 10 檔。</p>
      </header>
      <div class="market-tabs">${marketButtons}</div>
      <div class="market-summary">目前範圍：${marketScopeLabel(rankingState.market)}一般股票，不含 ETF，共 ${instantRows.length.toLocaleString("zh-TW")} 檔 · 法人資料日 ${htmlEscape(sampleInstitutionalDate)}${institutionalIsOlder ? "（資料日較行情早，非最新交易日）" : ""} · 台股紅漲綠跌 · 點股票可查看個股</div>
      <div id="rank-institutional" class="market-ranking-parallel" tabindex="-1">${renderInstitutionalRankingList("買超排行 Top 10", netBuy, { limit: 10, columns: 1 })}${renderInstitutionalRankingList("賣超排行 Top 10", netSell, { limit: 10, columns: 1 })}</div>
    </section>
  `;
}

function renderMarketSectorRankingSection(items, quotes, institutionalRows) {
  const filtered = marketFilterItems(items, marketState.market);
  const institutionalRanked = buildInstitutionalRankingRows(filtered, quotes, institutionalRows);
  const sectorRanked = buildInstitutionalSectorRankingRows(institutionalRanked);
  const activeSector = rankingState.industry && sectorRanked.find((item) => item.name === rankingState.industry)
    ? rankingState.industry
    : "";
  rankingState.industry = activeSector;
  const sectorStocks = activeSector
    ? institutionalRanked
      .filter((item) => String(item?.stock?.industryName || "未分類").trim() === activeSector)
      .sort((a, b) => b.amount - a.amount || a.stock.code.localeCompare(b.stock.code))
    : [];
  const sampleInstitutionalDate = institutionalRows?.find((row) => row?.date)?.date || "官方資料未提供";

  return `
    <section id="rank-sectors" class="market-layer market-layer-browser institutional-section market-radar-section" tabindex="-1">
      <header class="institutional-section-head">
        <div><span class="institutional-kicker">SECTOR FLOW</span><h2>類股淨買賣超排行</h2></div>
        <p>依三大法人淨買賣超彙整類股方向；法人資料日 ${htmlEscape(sampleInstitutionalDate)}。</p>
      </header>
      <div class="market-summary">目前範圍：${marketScopeLabel(marketState.market)}一般股票，不含 ETF · 點類股可展開成分股淨買賣超排序</div>
      <div class="market-ranking-grid market-ranking-grid-1">
        ${renderInstitutionalSectorRankingList("類股淨買賣超排行", sectorRanked)}
        ${activeSector
          ? renderInstitutionalRankingList(`${activeSector}淨買賣超排序`, sectorStocks, { limit: null, scrollRows: 10, sortByNetAmount: true })
          : `<article class="market-ranking-card market-ranking-card-expanded market-ranking-card-placeholder"><h3>類股淨買賣超明細</h3><div class="warrant-list-empty">點擊上方類股後顯示該類股個股淨買賣超排序</div></article>`}
      </div>
    </section>
  `;
}

function renderInstitutionalMarketRankingUnavailable(warnings = []) {
  const messages = [...new Set((warnings || []).map((message) => String(message || "").trim()).filter(Boolean))];
  const detailList = messages.length > 1
    ? `<ul>${messages.map((message) => `<li>${htmlEscape(message)}</li>`).join("")}</ul>`
    : "";
  return `
    <section id="market-rankings" class="market-layer market-layer-browser institutional-section market-radar-section" tabindex="-1">
      <header class="institutional-section-head">
        <div><span class="institutional-kicker">DAILY FLOW</span><h2>三大法人排行</h2></div>
        <p>市場排行需要另外整理全市場行情與法人日資料；這次載入暫時無法完整顯示。</p>
      </header>
      <div class="institutional-practical-note">
        <strong>市場排行暫時無法整理</strong>
        <p>${htmlEscape(messages[0] || "請稍後重新整理，再次讀取最近交易日的市場排行資料。")}</p>
        ${detailList}
      </div>
    </section>
  `;
}

function rerenderInstitutionalRadarFromCache() {
  if (!lastInstitutionalRadarData) return false;
  renderInstitutionalRadarPage(lastInstitutionalRadarData, lastInstitutionalMarketRankingContext);
  return true;
}

const SCREEN_SORT_COLUMNS = [
  ["stock", "股票"],
  ["close", "股價"],
  ["benchmarkBase", "基準值"],
  ["discountPct", "基準差"],
  ["priceBandOrder", "區間"],
  ["priceBandRangeSort", "區間股價"],
];

const SCREEN_BAND_OPTIONS = {
  all: "全部區間",
  ...Object.fromEntries(BENCHMARK_BANDS.map((band) => [band.key, band.label])),
};
const SCREEN_EXCLUDE_ETF = "__exclude_etf__";

function getScreenConfig() {
  return {
    market: screenInputs.market?.value || "all",
    industry: screenInputs.industry?.value || "",
    band: SCREEN_BAND_OPTIONS[screenInputs.band?.value] ? screenInputs.band.value : "all",
    keyword: String(screenInputs.keyword?.value || "").trim().toLowerCase(),
  };
}

function syncScreenChangeControls() {
  if (screenChangeMaxWrap) screenChangeMaxWrap.hidden = true;
}

function screenRowMatchesConfig(row, config) {
  const keyword = String(config.keyword || "").trim().toLowerCase();
  const matchesKeyword = !keyword || String(row.stock.code || "").toLowerCase().includes(keyword) || String(row.stock.name || "").toLowerCase().includes(keyword);
  const matchesBand = config.band === "all" || row.priceBandKey === config.band;
  return matchesKeyword && matchesBand;
}

function updateScreenIndustryOptions(items, selected = screenInputs.industry?.value || "") {
  if (!screenInputs.industry) return;
  const configMarket = screenInputs.market?.value || "all";
  const scopedItems = marketFilterItems(items, configMarket);
  const nonEtfCount = scopedItems.filter((item) => !isEtfItem(item)).length;
  const groups = getIndustryGroups(scopedItems);
  const available = new Set([SCREEN_EXCLUDE_ETF, ...groups.map((group) => group.name)]);
  const active = available.has(selected) ? selected : "";
  screenInputs.industry.innerHTML = [
    `<option value="">全部產業</option>`,
    nonEtfCount ? `<option value="${SCREEN_EXCLUDE_ETF}" ${active === SCREEN_EXCLUDE_ETF ? "selected" : ""}>排除 ETF（${nonEtfCount.toLocaleString("zh-TW")}）</option>` : "",
    ...groups.map((group) => `<option value="${htmlEscape(group.name)}" ${group.name === active ? "selected" : ""}>${htmlEscape(group.name)}（${group.stocks.length.toLocaleString("zh-TW")}）</option>`),
  ].join("");
}

function screenIndustryLabel(industry) {
  if (industry === SCREEN_EXCLUDE_ETF) return "排除 ETF";
  return industry || "全產業";
}

function buildSectorScreenContext(items, quotes, config) {
  const filtered = marketFilterItems(items, config.market);
  const sectors = calcSectorMoves(filtered, quotes)
    .filter((sector) => sector.name && sector.name !== "ETF / 其他");
  const totalTradeValue = sectors.reduce((sum, sector) => sum + (parseNum(sector.tradeValue) || 0), 0);
  const sectorMap = new Map();
  sectors.forEach((sector) => {
    const share = totalTradeValue > 0 ? (parseNum(sector.tradeValue) || 0) / totalTradeValue : null;
    sectorMap.set(sector.name, { ...sector, fundShare: share, moveRank: null, fundRank: null });
  });
  [...sectors]
    .sort((a, b) => {
      const av = Number.isFinite(a.avgPct) ? a.avgPct : -Infinity;
      const bv = Number.isFinite(b.avgPct) ? b.avgPct : -Infinity;
      return bv - av || b.tradeValue - a.tradeValue || a.name.localeCompare(b.name, "zh-Hant");
    })
    .forEach((sector, index) => {
      const item = sectorMap.get(sector.name);
      if (item) item.moveRank = index + 1;
    });
  [...sectors]
    .sort((a, b) => (parseNum(b.tradeValue) || 0) - (parseNum(a.tradeValue) || 0) || a.name.localeCompare(b.name, "zh-Hant"))
    .forEach((sector, index) => {
      const item = sectorMap.get(sector.name);
      if (item) item.fundRank = index + 1;
    });
  return { sectorMap, totalTradeValue };
}

function buildScreenRows(items, quotes, financialMap = new Map(), config = getScreenConfig()) {
  return marketFilterItems(items, config.market)
    .filter((stock) => {
      if (!config.industry) return true;
      if (config.industry === SCREEN_EXCLUDE_ETF) return !isEtfItem(stock);
      return stock.industryName === config.industry;
    })
    .map((stock) => {
      const quote = quotes?.get(`${stock.market}:${stock.code}`);
      const financial = financialMap.get(stock.code) || {};
      const close = parseNum(quote?.close);
      const change = parseNum(quote?.change);
      const changePct = parseNum(quote?.changePct);
      const benchmarkBase = parseNum(financial.roeAdjustedBase);
      const financialPeriod = financial.year && financial.quarter ? `${financial.year}Q${financial.quarter}` : "";
      const band = financialPeriod ? benchmarkBandInfo(benchmarkBase, close) : null;
      const discountPct = Number.isFinite(close) && Number.isFinite(benchmarkBase) && benchmarkBase !== 0
        ? ((close - benchmarkBase) / benchmarkBase) * 100
        : null;
      const ranges = benchmarkRanges(benchmarkBase);
      const activeRange = ranges[band?.key] || null;
      return {
        stock,
        quote,
        close,
        change,
        changePct,
        benchmarkBase,
        financialPeriod,
        priceBandKey: band?.key || "",
        priceBand: band?.label || "資料不足，暫不判定",
        priceBandOrder: band?.order ?? 99,
        priceBandRange: activeRange,
        priceBandRangeSort: Array.isArray(activeRange) ? activeRange[0] : null,
        discountPct,
        headRange: ranges.head,
        bodyRange: ranges.body,
        tailRange: ranges.tail,
        boneRange: ranges.bone,
        crazyRange: ranges.crazy,
        equityParent: financial.equityParent,
        outstandingLots: financial.outstandingLots,
        otherComprehensiveIncome: financial.otherComprehensiveIncome,
        otherEquity: financial.otherEquity,
        ociPerShare: financial.ociPerShare,
        otherEquityPerShare: financial.otherEquityPerShare,
        bookValuePerShare: financial.bookValuePerShare,
        adjustedBookValuePerShare: financial.adjustedBookValuePerShare,
        parentNetIncome: financial.parentNetIncome,
        roe: financial.roe,
        adjustedRoe: financial.adjustedRoe,
      };
    })
    .filter((row) => {
      const hasValidModel = Number.isFinite(row.close) && row.close > 0
        && Number.isFinite(row.benchmarkBase) && row.benchmarkBase > 0
        && Boolean(row.financialPeriod) && Boolean(row.priceBandKey);
      const explicitSearchFallback = Boolean(config.keyword) && config.band === "all";
      return screenRowMatchesConfig(row, config) && (hasValidModel || explicitSearchFallback);
    });
}

function benchmarkRanges(base) {
  const n = parseNum(base);
  if (!Number.isFinite(n) || n <= 0) {
    return Object.fromEntries(BENCHMARK_BANDS.map((band) => [band.key, null]));
  }
  return {
    below: [0, n * 0.85],
    head: [n * 0.85, n],
    body: [n, n * 1.15],
    tail: [n * 1.15, n * 1.3],
    bone: [n * 1.3, n * 2],
    crazy: [n * 2, n * 10],
    outlier: [n * 10, Infinity],
  };
}

function renderBenchmarkRange(value) {
  if (!Array.isArray(value)) return "—";
  const [low, high] = value;
  const lowText = renderMarketQuoteCell(low, 2);
  const highText = high === Infinity ? "∞" : renderMarketQuoteCell(high, 2);
  return `${lowText}~${highText}`;
}

function getScreenSortValue(row, key) {
  if (key === "stock") return row.stock.code || row.stock.name || "";
  const value = row[key];
  return Array.isArray(value) ? value[0] : value;
}

function sortScreenRows(rows) {
  const key = screenState.sortKey;
  const dir = screenState.sortDir;
  if (!key || !dir) return rows;
  const factor = dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const av = getScreenSortValue(a, key);
    const bv = getScreenSortValue(b, key);
    if (key === "stock") return factor * String(av || "").localeCompare(String(bv || ""), "zh-Hant", { numeric: true });
    const an = parseNum(av);
    const bn = parseNum(bv);
    const aMissing = !Number.isFinite(an);
    const bMissing = !Number.isFinite(bn);
    if (aMissing && bMissing) return a.stock.code.localeCompare(b.stock.code);
    if (aMissing) return 1;
    if (bMissing) return -1;
    return factor * (an - bn) || a.stock.code.localeCompare(b.stock.code);
  });
}

function renderScreenSortHeader(key, label) {
  const active = screenState.sortKey === key && screenState.sortDir;
  const icon = active ? (screenState.sortDir === "asc" ? "▲" : "▼") : "↕";
  const current = active ? `目前${screenState.sortDir === "asc" ? "正序" : "倒序"}` : "目前未排序";
  return `<button class="market-sort-button ${active ? "active" : ""}" type="button" data-screen-sort-key="${key}" title="點擊切換${label}排序" aria-label="${label}，${current}；點擊切換排序"><span>${label}</span><b>${icon}</b>${active ? `<em>${screenState.sortDir === "asc" ? "正序" : "倒序"}</em>` : ""}</button>`;
}

function renderTechnicalScreenTable(rows) {
  const pageSize = Math.max(6, Number(screenState.pageSize) || 6);
  const sortedRows = sortScreenRows(rows);
  const page = clampTablePage(screenState.page, sortedRows.length, pageSize);
  screenState.page = page;
  const pageRows = sortedRows.slice((page - 1) * pageSize, page * pageSize);
  const headerMap = new Map(SCREEN_SORT_COLUMNS);
  const body = pageRows.map((row) => {
    const diffTone = row.priceBandKey === "outlier" ? "warning" : !Number.isFinite(row.discountPct) ? "flat" : Number(row.discountPct) <= 0 ? "up" : Number(row.discountPct) >= 30 ? "down" : "flat";
    const discountText = Number.isFinite(row.discountPct) ? `${row.discountPct > 0 ? "+" : ""}${renderMarketQuoteCell(row.discountPct, 2)}%` : "—";
    return `
      <tr class="market-quote-row" data-stock-code="${htmlEscape(row.stock.code)}">
        <td class="stock-name-cell"><a class="screen-stock-link" href="/stock/${encodeURIComponent(row.stock.code)}" aria-label="查看 ${htmlEscape(row.stock.code)} ${htmlEscape(row.stock.name)}"><b>${htmlEscape(row.stock.name)}</b><span>${htmlEscape(row.stock.code)} · ${row.stock.market === "otc" ? "上櫃" : "上市"} · ${htmlEscape(row.stock.industryName || "未分類")}</span></a></td>
        <td data-label="收盤價">${renderMarketQuoteCell(row.close, 2)}</td>
        <td data-label="基準值">${renderMarketQuoteCell(row.benchmarkBase, 2)}</td>
        <td data-label="基準差" class="${diffTone}">${discountText}</td>
        <td data-label="區間">${htmlEscape(row.priceBand)}</td>
        <td data-label="區間股價">${renderBenchmarkRange(row.priceBandRange)}</td>
      </tr>
    `;
  }).join("");
  return `
    <div class="paginated-table-region" data-table-region="screen">
      <div class="market-quote-table-wrap paginated-table-wrap" tabindex="0" role="region" aria-label="選股候選清單，第 ${page} 頁，共 ${tablePageCount(sortedRows.length, pageSize)} 頁">
        <table class="market-quote-table technical-screen-table">
          <thead>
            <tr>
              ${[...headerMap.entries()].map(([key, label]) => `<th scope="col" aria-sort="${screenState.sortKey === key ? (screenState.sortDir === "asc" ? "ascending" : "descending") : "none"}">${renderScreenSortHeader(key, label)}</th>`).join("")}
            </tr>
          </thead>
          <tbody>${body || `<tr><td colspan="${SCREEN_SORT_COLUMNS.length}" class="market-empty-cell">目前沒有符合條件的股票</td></tr>`}</tbody>
        </table>
      </div>
      ${renderScreenCanvasPagination(sortedRows.length, page, pageSize)}
    </div>
  `;
}

function renderScreenCanvasPagination(total, page, pageSize) {
  const pages = tablePageCount(total, pageSize);
  const candidates = [...new Set([1, page - 2, page - 1, page, page + 1, page + 2, pages])]
    .filter((value) => value >= 1 && value <= pages)
    .sort((a, b) => a - b);
  let previous = 0;
  const pageButtons = candidates.map((value) => {
    const gap = previous && value - previous > 1 ? '<span class="screen-page-gap" aria-hidden="true">…</span>' : "";
    previous = value;
    return `${gap}<button class="${value === page ? "active" : ""}" type="button" data-table-page-scope="screen" data-table-page="${value}"${value === page ? ' aria-current="page"' : ""}>${value}</button>`;
  }).join("");
  return `
    <nav class="table-pagination screen-canvas-pagination" aria-label="選股候選清單分頁">
      <span class="table-pagination-count">顯示 ${total ? ((page - 1) * pageSize) + 1 : 0}–${Math.min(total, page * pageSize)} / ${Number(total).toLocaleString("zh-TW")} 筆</span>
      <div class="table-pagination-actions">
        <button type="button" data-table-page-scope="screen" data-table-page="${page - 1}" ${page <= 1 ? "disabled" : ""} aria-label="上一頁">‹</button>
        ${pageButtons}
        <button type="button" data-table-page-scope="screen" data-table-page="${page + 1}" ${page >= pages ? "disabled" : ""} aria-label="下一頁">›</button>
      </div>
      <label class="screen-page-size">每頁顯示 <select data-screen-page-size><option value="6" ${pageSize === 6 ? "selected" : ""}>6</option><option value="12" ${pageSize === 12 ? "selected" : ""}>12</option><option value="24" ${pageSize === 24 ? "selected" : ""}>24</option></select></label>
    </nav>`;
}

function rerenderTechnicalScreenTableOnly() {
  const region = resultSlot.querySelector('[data-table-region="screen"]');
  if (!region) return false;
  region.outerHTML = renderTechnicalScreenTable((lastScreenRows || []).slice(0, SCREEN_RESULT_LIMIT));
  return true;
}

function rerenderTechnicalScreenPageFromCache({ resetIndustry = false } = {}) {
  if (!lastScreenSnapshot) return false;
  if (resetIndustry) updateScreenIndustryOptions(lastScreenSnapshot.items, "");
  renderTechnicalScreenPage(lastScreenSnapshot.items, lastScreenSnapshot.quotes, lastScreenSnapshot.financialMap);
  return true;
}

function renderScreenBandQuickFilters(config, bandCounts) {
  const groups = [
    ["全部", [["all", "全部區間"]]],
    ["低於基準", [["below", "15% 以上"], ["head", "0–15%"]]],
    ["高於基準", [["body", "0–15%"], ["tail", "15–30%"], ["bone", "30–100%"], ["crazy", "100–900%"]]],
    ["模型外", [["outlier", "超出可判讀範圍"]]],
  ];
  const countFor = (key) => key === "all"
    ? [...bandCounts.entries()].filter(([band]) => band !== "outlier").reduce((sum, [, value]) => sum + value, 0)
    : bandCounts.get(key) || 0;
  return `
    <section class="screen-band-filter" aria-labelledby="screen-band-filter-title">
      <header>
        <div><span>PRICE RANGE</span><h2 id="screen-band-filter-title">價格基準值區間</h2></div>
        <p>快速選擇相對基準值區間；數字為目前市場與產業條件下的檔數。</p>
      </header>
      <div class="screen-band-quick" aria-label="價格區間快速篩選">
        ${groups.map(([label, options]) => `
          <div class="screen-band-group">
            <span class="screen-band-group-label">${htmlEscape(label)}</span>
            <div>
              ${options.map(([key, title]) => `
                <button class="${config.band === key ? "active" : ""}" type="button" data-screen-band="${key}" aria-pressed="${config.band === key ? "true" : "false"}">
                  <span>${htmlEscape(title)}</span>
                  <b>${countFor(key).toLocaleString("zh-TW")}</b>
                </button>
              `).join("")}
            </div>
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function renderScreenBandGuide() {
  const ranges = [
    ["低於基準 15% 以上", "現價低於基準值較多", "只表示價格與模型基準的距離，不代表低風險或適合買進。"],
    ["低於基準 0-15%", "現價接近但低於基準值", "用來縮小觀察範圍，不是安全區或買進訊號。"],
    ["高於基準 0-15%", "現價接近但高於基準值", "表示現價略高於模型基準，仍需搭配資料期間與公司狀況判讀。"],
    ["高於基準 15-30%", "現價高於基準值一段距離", "只描述距離，不代表適合賣出。"],
    ["高於基準 30-100%", "現價明顯高於基準值", "模型差距較大，應先確認財務資料與產業特性。"],
    ["高於基準 100-900%", "現價為基準值 2 至 10 倍", "模型差距很大，不能直接當成投資結論。"],
    ["超出模型可判讀範圍", "基準差大於 +900%", "不納入區間摘要，需人工確認資料與模型是否適用。"],
  ];
  return `
    <details class="screen-band-guide">
      <summary>價格區間怎麼看？</summary>
      <div class="screen-band-guide-body" aria-label="價格基準值區間說明">
        <div class="screen-band-guide-intro">
          <b>選股功能說明</b>
          <p>基準值依每股淨值與最近四季 ROE 計算；基準差是收盤價相對基準值的距離，區間股價是各分區的上下限，不是目標價或買賣建議。</p>
        </div>
        ${ranges.map(([title, range, note]) => `
          <div>
            <b>${htmlEscape(title)}</b>
            <span>${htmlEscape(range)}</span>
            <em>${htmlEscape(note)}</em>
          </div>
        `).join("")}
      </div>
    </details>
  `;
}

const SCREEN_RESULT_LIMIT = 100;

function renderScreenStarterExamples() {
  return `
    <div class="screen-starter-examples" aria-label="選股起始範例">
      <span>不知道怎麼開始：</span>
      <button type="button" data-screen-example="listed">只看上市</button>
      <button type="button" data-screen-example="semiconductor">只看半導體</button>
      <button type="button" data-screen-example="near-base">接近基準值</button>
    </div>`;
}

function renderTechnicalScreenPage(items, quotes = new Map(), financialMap = new Map()) {
  lastScreenSnapshot = { items, quotes, financialMap };
  updateScreenIndustryOptions(items);
  const config = getScreenConfig();
  const allRows = buildScreenRows(items, quotes, financialMap, { ...config, band: "all" });
  const modelRows = allRows.filter((row) => row.priceBandKey && row.priceBandKey !== "outlier");
  const rows = config.band === "all"
    ? config.keyword ? allRows : modelRows
    : allRows.filter((row) => row.priceBandKey === config.band);
  lastScreenRows = rows;
  const bandCounts = allRows.filter((row) => row.priceBandKey).reduce((map, row) => {
    map.set(row.priceBandKey, (map.get(row.priceBandKey) || 0) + 1);
    return map;
  }, new Map());
  const summaryRows = rows.filter((row) => row.priceBandKey && row.priceBandKey !== "outlier");
  const medianDiscount = medianFinite(summaryRows.map((row) => row.discountPct));
  const quoteDate = rows.map((row) => row.quote?.date || "").filter(Boolean).sort().at(-1) || "官方資料未提供";
  const financialPeriod = rows.map((row) => row.financialPeriod || "").filter(Boolean).sort().at(-1) || "官方資料未提供";
  const calculatedAt = new Date().toLocaleString("zh-TW", { hour12: false });
  const outlierCount = allRows.filter((row) => row.priceBandKey === "outlier").length;
  const screenHead = document.querySelector("#screenCanvasPageHead");
  if (screenHead) screenHead.innerHTML = `<div><h1>選股</h1><p>依市場、產業與價格基準值區間建立研究清單；收盤價 · 資料日 ${htmlEscape(quoteDate)}。</p></div><time>資料時間：${htmlEscape(quoteDate)}</time>`;
  resultSlot.innerHTML = `
    <div class="market-dashboard screen-dashboard screen-canvas-page fade-up">
      ${renderScreenBandQuickFilters(config, bandCounts)}
      <section id="screen-results" class="institutional-section screen-canvas-results" tabindex="-1">
        <header class="institutional-section-head">
          <div><h2>篩選結果：${rows.length.toLocaleString("zh-TW")} 檔</h2><p>${htmlEscape(screenIndustryLabel(config.industry))} · 財報 ${htmlEscape(financialPeriod)} · 模型範圍外 ${outlierCount.toLocaleString("zh-TW")} 檔</p></div>
        </header>
        ${renderTechnicalScreenTable(rows.slice(0, SCREEN_RESULT_LIMIT))}
      </section>
    </div>
  `;
}

async function runTechnicalScreen(options = {}) {
  const silent = Boolean(options.silent);
  const forceRefresh = Boolean(options.forceRefresh);
  if (loading && !forceRefresh) return;
  stopQuoteRefresh();
  if (!silent) setLoading(true);
  if (!silent) setStep(-1);
  liveData = null;
  if (!silent) liveSlot.innerHTML = "";
  if (!silent) errorSlot.innerHTML = "";
  if (!silent) renderPageLoading("選股資料");
  suggestions.hidden = true;
  input.classList.remove("has-suggestions");
  try {
    if (!silent || forceRefresh) resetMarketDataCache();
    const [items, quotes, financialMap] = await Promise.all([loadMarketUniverse(), loadMarketQuotes(), loadScreenFinancialMap()]);
    lastMarketRefreshAt = Date.now();
    renderTechnicalScreenPage(items, quotes, financialMap);
  } catch (error) {
    showRetryableLoadError("選股資料", error);
  } finally {
    if (!silent) setLoading(false);
  }
}

function renderMarketPage(items, charts = [], quotes = new Map(), subindustryData = null, institutionalRows = []) {
  const filtered = marketFilterItems(items, marketState.market);
  const stocksWithoutEtf = filtered.filter((item) => !isEtfItem(item));
  const baseGroups = getIndustryGroups(filtered);
  const groups = stocksWithoutEtf.length
    ? [{ name: "排除 ETF", stocks: stocksWithoutEtf.sort((a, b) => a.market.localeCompare(b.market) || a.code.localeCompare(b.code)) }, ...baseGroups]
    : baseGroups;
  const defaultGroup = groups.find((group) => !["排除 ETF", "ETF", "ETF / 其他"].includes(group.name)) || groups[0] || { name: "", stocks: [] };
  if (marketState.industry && !groups.some((group) => group.name === marketState.industry)) marketState.industry = "";
  const activeGroup = marketState.industry
    ? groups.find((group) => group.name === marketState.industry) || defaultGroup
    : { name: "", stocks: stocksWithoutEtf };
  const subindustryOptions = getMarketSubindustryOptions(activeGroup, subindustryData, marketState.market);
  if (!subindustryOptions.some((entry) => entry.code === marketState.subIndustry)) {
    marketState.subIndustry = "";
  }
  const activeSubindustry = subindustryOptions.find((entry) => entry.code === marketState.subIndustry) || null;
  const activeSubindustryKeys = activeSubindustry ? new Set(activeSubindustry.stockKeys || []) : null;
  const groupStocks = activeSubindustryKeys
    ? activeGroup.stocks.filter((stock) => activeSubindustryKeys.has(`${stock.market}:${stock.code}`))
    : activeGroup.stocks;
  const keyword = String(marketState.keyword || "").trim().toLowerCase();
  const visibleStocks = keyword
    ? groupStocks.filter((stock) => `${stock.code} ${stock.name}`.toLowerCase().includes(keyword))
    : groupStocks;
  const stockPanelTitle = activeSubindustry
    ? `${activeGroup.name}類股 - ${activeSubindustry.name}`
    : activeGroup.name ? `${activeGroup.name}類股` : "全部個股";
  const activeMarketLabel = marketScopeLabel(marketState.market);
  const listedCount = items.filter((item) => item.market === "listed").length;
  const otcCount = items.filter((item) => item.market === "otc").length;
  const marketButtons = [
    ["all", "上市櫃", items.length],
    ["listed", "上市", listedCount],
    ["otc", "上櫃", otcCount],
  ].map(([key, label, count]) => `<button class="market-tab ${marketState.market === key ? "active" : ""}" type="button" data-market="${key}">${label}<span>${Number(count).toLocaleString("zh-TW")}</span></button>`).join("");
  const renderGroupLinks = (sectionGroups, marketKey) => sectionGroups.map((group) => `
    <button class="industry-link ${marketState.market === marketKey && group.name === activeGroup.name ? "active" : ""}" type="button" data-market="${marketKey}" data-industry="${htmlEscape(group.name)}">
      <span>${htmlEscape(group.name)}</span>
      <b>${group.stocks.length.toLocaleString("zh-TW")}</b>
    </button>
  `).join("");
  const listedItems = items.filter((item) => item.market === "listed");
  const otcItems = items.filter((item) => item.market === "otc");
  const listedGroups = [{ name: "排除 ETF", stocks: listedItems.filter((item) => !isEtfItem(item)).sort((a, b) => a.code.localeCompare(b.code)) }, ...getIndustryGroups(listedItems)]
    .filter((group) => group.stocks.length);
  const otcGroups = [{ name: "排除 ETF", stocks: otcItems.filter((item) => !isEtfItem(item)).sort((a, b) => a.code.localeCompare(b.code)) }, ...getIndustryGroups(otcItems)]
    .filter((group) => group.stocks.length);
  const categorySource = marketState.market === "all"
    ? [["上市櫃類股", groups, "all"]]
    : marketState.market === "listed"
      ? [["上市類股", listedGroups, "listed"]]
      : [["上櫃類股", otcGroups, "otc"]];
  const categorySections = categorySource.filter(([, sectionGroups]) => sectionGroups.length).map(([title, sectionGroups, marketKey]) => `
    <section class="category-section">
      <h3>${title}</h3>
      <div class="category-link-grid">${renderGroupLinks(sectionGroups, marketKey) || `<div class="warrant-list-empty">目前無分類資料</div>`}</div>
    </section>
  `).join("");
  const sampleQuote = visibleStocks.map((stock) => quotes?.get(`${stock.market}:${stock.code}`)).find(Boolean);
  const quoteDate = sampleQuote?.date || "官方資料未提供";
  lastMarketRender = { items, quotes, institutionalRows, visibleStocks, activeGroup, activeSubindustry, subindustryOptions, quoteDate };
  const marketOptions = [["all", "全部"], ["listed", "上市"], ["otc", "上櫃"]].map(([value, label]) => `<option value="${value}" ${marketState.market === value ? "selected" : ""}>${label}</option>`).join("");
  const industryOptions = `<option value="">全部</option>${groups.map((group) => `<option value="${htmlEscape(group.name)}" ${group.name === activeGroup.name ? "selected" : ""}>${htmlEscape(group.name)}</option>`).join("")}`;

  resultSlot.innerHTML = `
    <div class="market-dashboard institutional-radar-page market-radar-page canvas-market-page fade-up">
      <header class="canvas-page-head"><h1>市場總覽</h1><time>資料時間：${htmlEscape(quoteDate)}</time></header>
      <p id="researchResultStatus" class="sr-only" role="status" aria-live="polite"></p>
      <section id="market-indexes" class="market-layer market-layer-status institutional-section market-radar-section" tabindex="-1">
        ${renderIndexCards(charts, filtered, quotes)}
      </section>
      ${renderMarketCanvasPulse(filtered, quotes, institutionalRows)}
      ${renderMarketCanvasResearchSections(items, quotes, institutionalRows)}
      <section id="market-stocks" class="market-layer market-layer-browser institutional-section market-radar-section" tabindex="-1">
        <section class="market-content-group market-stock-list-section">
          <form id="marketCanvasSearchForm" class="market-canvas-controls">
            <h2>個股搜尋</h2>
            <label class="market-canvas-keyword"><span class="sr-only">搜尋公司名稱或代號</span><input id="marketCanvasKeyword" type="search" value="${htmlEscape(marketState.keyword)}" placeholder="搜尋公司名稱或代號，例如：台積電 2330"></label>
            <label><span>市場</span><select id="marketCanvasMarket">${marketOptions}</select></label>
            <label><span>產業</span><select id="marketCanvasIndustry">${industryOptions}</select></label>
            <button type="submit">搜尋</button><button type="button" data-market-canvas-clear>清除條件</button>
          </form>
          <p class="market-canvas-summary">${htmlEscape(stockPanelTitle)} · ${visibleStocks.length.toLocaleString("zh-TW")} 檔 · 資料日 ${htmlEscape(quoteDate)}</p>
          ${renderMarketStockTable(visibleStocks, quotes)}
        </section>
      </section>
    </div>
  `;
}

