async function run(query = input.value) {
  if (currentMode === "warrant") return runWarrant(query);
  if (currentMode === "strategy") return runStrategy(query);
  if (currentMode === "screen") return runTechnicalScreen();
  if (currentMode === "market") return runMarket();
  if (currentMode === "futures") return runFutures();
  if (currentMode === "portfolio") return renderPortfolioPage();
  return runStock(query);
}

async function runStrategy(query = input.value) {
  const raw = String(query || "").trim();
  if (!raw || loading) return;
  stopQuoteRefresh();
  setLoading(true);
  setStep(-1);
  liveData = null;
  liveSlot.innerHTML = "";
  errorSlot.innerHTML = "";
  resultSlot.innerHTML = "";
  suggestions.hidden = true;
  input.classList.remove("has-suggestions");

  try {
    await Promise.all([loadStockDatabase(), loadWarrantDatabase()]);
    const underlying = resolveWarrantUnderlying(raw);
    if (!underlying) throw new Error(`找不到「${raw}」，請輸入股票或 ETF 代號/名稱。`);
    const warrants = getWarrantsByUnderlying(underlying);
    updateStrategyIssuerOptions(warrants);
    const strategyConfig = getStrategyConfig();
    let underlyingQuote = null;
    try {
      underlyingQuote = await fetchUnderlyingQuote(underlying.code, underlying.ex);
    } catch (_) {}
    const strategyWarrants = getStrategyWarrants(warrants, underlyingQuote?.price, strategyConfig);
    renderWarrantListForUnderlying(underlying, [], strategyWarrants, underlyingQuote, { strategyOnly: true, strategyConfig });
  } catch (error) {
    showRetryableLoadError("策略權證", error);
  } finally {
    setStep(-1);
    setLoading(false);
  }
}

async function runWarrant(query = input.value) {
  const raw = String(query || "").trim();
  if (!raw || loading) return;
  stopQuoteRefresh();
  setLoading(true);
  setStep(-1);
  liveData = null;
  liveSlot.innerHTML = "";
  errorSlot.innerHTML = "";
  resultSlot.innerHTML = "";
  suggestions.hidden = true;
  input.classList.remove("has-suggestions");

  try {
    await loadWarrantDatabase();
    await loadStockDatabase();
    const underlying = resolveWarrantUnderlying(raw);
    const exactWarrant = warrantCodeIndex.has(normalizeWarrantCode(raw));
    if (underlying && !exactWarrant) {
      const warrants = getWarrantsByUnderlying(underlying);
      if (!warrants.length) throw new Error(`找不到「${underlying.code} ${underlying.name}」的對應權證。`);
      updateWarrantIssuerOptions(warrantIssuerInput, warrants);
      const warrantConfig = getWarrantLookupConfig();
      const filteredWarrants = filterWarrantsByIssuer(warrants, warrantConfig.issuer);
      let underlyingQuote = null;
      try {
        underlyingQuote = await fetchUnderlyingQuote(underlying.code, underlying.ex);
      } catch (_) {}
      const strategyWarrants = getStrategyWarrants(warrants, underlyingQuote?.price);
      renderWarrantListForUnderlying(underlying, filteredWarrants, strategyWarrants, underlyingQuote, { warrantConfig });
      return;
    }
    const warrant = resolveWarrant(raw);
    if (!warrant) throw new Error(`找不到「${raw}」，請輸入正確權證代號或權證名稱。`);
    const detail = await fetchWarrantDetail(warrant.code);
    renderWarrantResult(detail);
  } catch (error) {
    showRetryableLoadError("權證資料", error);
  } finally {
    setStep(-1);
    setLoading(false);
  }
}

async function runStock(query = input.value) {
  const raw = String(query || "").trim();
  if (!raw || loading) return;
  stopQuoteRefresh();
  setLoading(true);
  setStep(0);
  liveData = null;
  liveSlot.innerHTML = "";
  errorSlot.innerHTML = "";
  resultSlot.innerHTML = "";
  suggestions.hidden = true;
  input.classList.remove("has-suggestions");

  await loadStockDatabase();
  const stock = resolveStock(raw);
  if (!stock) {
    showError(`找不到「${raw}」，請檢查股票代號或公司名稱。`, getNearbyStocks(raw));
    setStep(-1);
    setLoading(false);
    return;
  }

  try {
    setStep(1);
    liveData = await fetchPrimaryStockQuote(stock.code, stock.ex);
    liveSlot.innerHTML = renderTicker(liveData);
    setStep(2);
    const ex = liveData.ex === "otc" ? "o" : "t";
    const cached = await fetchStockQueryCache(liveData.code, ex).catch(() => null);
    if (!cached?.stale && (cached?.kline || cached?.financial || cached?.officialData || cached?.companyProfile)) {
      const cachedReport = buildStockReport(liveData, cached.support, cached.valuation, cached.financial, cached.kline, cached.companyProfile, cached.officialData);
      setStep(3);
      liveSlot.innerHTML = "";
      renderResult(cachedReport, cached.peerContext || null);
      startQuoteRefresh(liveData);
      setStep(-1);
      setLoading(false);
      fetchStockQueryBundle(liveData.code, ex)
        .then((fresh) => saveStockQueryCache(liveData.code, ex, fresh).catch(() => {}))
        .catch(() => {});
      return;
    }
    const fresh = await fetchStockQueryBundle(liveData.code, ex);
    setStep(3);
    const report = buildStockReport(liveData, fresh.support, fresh.valuation, fresh.financial, fresh.kline, fresh.companyProfile, fresh.officialData);
    liveSlot.innerHTML = "";
    renderResult(report, fresh.peerContext || null);
    startQuoteRefresh(liveData);
    saveStockQueryCache(liveData.code, ex, fresh).catch(() => {});
  } catch (error) {
    stopQuoteRefresh();
    showRetryableLoadError(`「${stock.code}」資料`, error);
  } finally {
    setStep(-1);
    setLoading(false);
  }
}

function institutionalSigned(value, digits = 1, suffix = "") {
  const n = parseNum(value);
  if (!Number.isFinite(n)) return "—";
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toLocaleString("zh-TW", { minimumFractionDigits: digits, maximumFractionDigits: digits })}${suffix}`;
}

function institutionalAmount(value) {
  const n = parseNum(value);
  return Number.isFinite(n) ? institutionalSigned(n / 1e8, 1, " 億") : "—";
}

function institutionalLots(value) {
  const n = parseNum(value);
  if (!Number.isFinite(n)) return "—";
  const lots = n / 1000;
  const digits = Math.abs(lots) >= 100 ? 0 : 1;
  return institutionalSigned(lots, digits, " 張");
}

function institutionalTone(value) {
  const n = parseNum(value);
  return !Number.isFinite(n) || n === 0 ? "flat" : n > 0 ? "up" : "down";
}

function renderInstitutionalSummaryCard(label, value, note, tone = "flat", key = "") {
  return `
    <article class="institutional-summary-card ${tone}"${key ? ` data-radar-summary="${htmlEscape(key)}"` : ""}>
      <span>${htmlEscape(label)}</span>
      <strong>${value}</strong>
      <small>${htmlEscape(note)}</small>
    </article>
  `;
}

function renderInstitutionalRankingCard(title, rows, direction) {
  const rankingRows = rows || [];
  const body = rankingRows.map((row, index) => {
    const streak = row.streak?.days > 0
      ? `<span class="institutional-streak ${htmlEscape(row.streak.direction)}">連${row.streak.direction === "buy" ? "買" : "賣"} ${intText(row.streak.days)} 日</span>`
      : '<span class="institutional-streak flat">—</span>';
    const tone = institutionalTone(row.changePct);
    return `
      <tr>
        <td class="institutional-rank-number">${index + 1}</td>
        <td class="institutional-stock-cell"><a href="/stock/${encodeURIComponent(row.code)}"><b>${htmlEscape(row.name)}</b><span>${htmlEscape(row.code)}</span></a></td>
        <td class="${direction === "buy" ? "up" : "down"}" data-label="買賣超"><strong>${institutionalLots(row.netShares)}</strong></td>
        <td data-label="收盤">${renderMarketQuoteCell(row.close, 2)}</td>
        <td class="${tone}" data-label="漲跌幅">${institutionalSigned(row.changePct, 2, "%")}</td>
        <td data-label="連續">${streak}</td>
      </tr>
    `;
  }).join("");
  const mobileBody = rankingRows.map((row, index) => {
    const streak = row.streak?.days > 0
      ? `<span class="institutional-streak ${htmlEscape(row.streak.direction)}">連${row.streak.direction === "buy" ? "買" : "賣"} ${intText(row.streak.days)} 日</span>`
      : '<span class="institutional-streak flat">—</span>';
    const tone = institutionalTone(row.changePct);
    return `
      <li class="institutional-mobile-rank-item">
        <span class="institutional-mobile-rank-number" aria-label="第 ${index + 1} 名">${index + 1}</span>
        <a class="institutional-mobile-stock" href="/stock/${encodeURIComponent(row.code)}"><b>${htmlEscape(row.name)}</b><span>${htmlEscape(row.code)}</span></a>
        <strong class="institutional-mobile-net ${direction === "buy" ? "up" : "down"}">${institutionalLots(row.netShares)}</strong>
        <dl class="institutional-mobile-details">
          <div><dt>收盤</dt><dd>${renderMarketQuoteCell(row.close, 2)}</dd></div>
          <div><dt>漲跌幅</dt><dd class="${tone}">${institutionalSigned(row.changePct, 2, "%")}</dd></div>
          <div><dt>連續</dt><dd>${streak}</dd></div>
        </dl>
      </li>
    `;
  }).join("");
  return `
    <article class="institutional-ranking-card">
      <header><span class="institutional-direction-dot ${direction}"></span><h3>${htmlEscape(title)}</h3></header>
      <div class="institutional-table-wrap">
        <table>
          <thead><tr><th>名次</th><th>股票</th><th>買賣超</th><th>收盤</th><th>漲跌幅</th><th>連續</th></tr></thead>
          <tbody>${body || '<tr><td colspan="6" class="institutional-empty">此來源目前沒有可排序資料</td></tr>'}</tbody>
        </table>
      </div>
      <ol class="institutional-mobile-ranking-list" aria-label="${htmlEscape(title)}">
        ${mobileBody || '<li class="institutional-empty">此來源目前沒有可排序資料</li>'}
      </ol>
    </article>
  `;
}

